window.__QUESTION_BANK__ = {"subjects":[{"id":"coa","name":"Computer Organization","chapters":[{"id":"ch01","name":"第一章简介"},{"id":"ch02","name":"第二章计算机演变"},{"id":"ch03","name":"第三章计算机功能与互连的顶层视图"},{"id":"ch04","name":"第四章高速缓存"},{"id":"ch05","name":"第五章内部存储器"},{"id":"ch06","name":"第六章外部存储器"},{"id":"ch07","name":"第七章输入输出"},{"id":"ch08","name":"第八章"},{"id":"ch09","name":"第九章计算机算数"},{"id":"ch10","name":"第十章指令集：特征与功能"},{"id":"ch11","name":"第十一章指令集：寻址方式与指令格式"},{"id":"ch12","name":"第十二章CPU结构与功能"},{"id":"ch13","name":"第十三章精简指令集计算机"},{"id":"ch14","name":"第十四章指令级并行性和超标量处理"},{"id":"ch15","name":"第十五章控制单元操作"},{"id":"ch16","name":"第十六章多处理器与集群"}],"mcq":[{"id":"coa-ch01-001","chapterId":"ch01","chapterName":"第一章简介","stemEn":"Which of the following statements is incorrect?","stemCn":"下列说法哪一项不正确？","options":[{"key":"A","textEn":"Computer organization is transparent to programmers.","textCn":"计算机组成对程序员来说是透明的。"},{"key":"B","textEn":"Computer implementation is transparent to programmers.","textCn":"计算机实现对程序员来说是透明的。"},{"key":"C","textEn":"Computer architecture is transparent to programmers.","textCn":"计算机体系结构对程序员来说是透明的。"},{"key":"D","textEn":"All of the above statements are incorrect.","textCn":"上述所有说法都是不正确的。"}],"answerKey":"C","explanationCn":"计算机系统结构（Computer Architecture）主要指程序员可见的属性，例如指令系统、数据类型、寻址方式、I/O 机制等，因此它对程序员来说不是透明的。计算机组成和计算机实现更多涉及内部实现细节，通常对程序员透明，所以 C 错误。","explanationEn":""},{"id":"coa-ch01-002","chapterId":"ch01","chapterName":"第一章简介","stemEn":"Which of the following statements is correct?","stemCn":"下列说法哪一项正确？","options":[{"key":"A","textEn":"Whether a computer has a multiplication instruction is an issue considered by computer organization.","textCn":"计算机是否具有乘法指令是计算机组成考虑的问题。"},{"key":"B","textEn":"Computers in the same family have the same architecture, but their organization may be different.","textCn":"同一系列的计算机具有相同的体系结构，但具体组成可能不同。"},{"key":"C","textEn":"Instruction set, word length, I/O mechanisms, and addressing modes are concepts involved in computer implementation.","textCn":"指令集、字长、I/O机制和寻址模式是计算机实现中涉及的概念。"},{"key":"D","textEn":"Control signals, interfaces, memory technology, and bus technology are concepts involved in computer architecture.","textCn":"控制信号、接口、存储器技术和总线技术是计算机体系结构中涉及的概念。"}],"answerKey":"B","explanationCn":"同一系列计算机通常具有相同的体系结构，因此程序兼容；但不同型号的机器在具体组成和实现方式上可以不同。A 中“是否有乘法指令”属于体系结构范畴；C 中列出的指令集、字长、寻址方式等也属于体系结构；D 中控制信号、接口、存储技术、总线技术属于计算机组成或实现范畴。","explanationEn":""},{"id":"coa-ch02-001","chapterId":"ch02","chapterName":"第二章计算机演变","stemEn":"The characteristic of the working mode of a von Neumann machine is ( ).","stemCn":"冯诺依曼机工作模式的特点是（ ）。","options":[{"key":"A","textEn":"Multiple instruction streams and a single data stream","textCn":"多个指令流和单个数据流"},{"key":"B","textEn":"Accessing by address and executing instructions sequentially","textCn":"按地址访问并顺序执行指令"},{"key":"C","textEn":"Stack operations","textCn":"堆栈操作"},{"key":"D","textEn":"Using binary representation","textCn":"使用二进制表示"}],"answerKey":"B","explanationCn":"冯·诺依曼机的核心思想是“存储程序”，程序和数据都存放在存储器中，CPU 按地址访问存储器，并通常按照指令顺序逐条执行。D“采用二进制”也是冯·诺依曼机的重要特点之一，但题目问的是“工作方式”的特点，因此应选 B。","explanationEn":""},{"id":"coa-ch02-002","chapterId":"ch02","chapterName":"第二章计算机演变","stemEn":"In a von Neumann machine, instructions and data are both stored in memory in binary form. The CPU distinguishes them based on ( ).","stemCn":"在冯·诺依曼机器中，指令和数据都以二进制形式存储在内存中。 CPU根据( )来区分它们。","options":[{"key":"A","textEn":"The addresses of instructions and data","textCn":"指令和数据的地址"},{"key":"B","textEn":"The addressing modes of instructions and data","textCn":"指令和数据的寻址方式"},{"key":"C","textEn":"The lengths of instructions and data","textCn":"指令和数据的长度"},{"key":"D","textEn":"Different stages of the instruction cycle","textCn":"指令周期的不同阶段"}],"answerKey":"D","explanationCn":"在冯·诺依曼机中，指令和数据都以二进制形式存放在同一个存储器中，从外部形式上并不能直接区分。CPU 是根据指令周期的不同阶段来区分它们的：取指阶段从存储器取出的内容被看作指令，执行阶段访问到的内容可能被看作数据。","explanationEn":""},{"id":"coa-ch02-003","chapterId":"ch02","chapterName":"第二章计算机演变","stemEn":"When processor performance develops rapidly while the performance of other computer components fails to keep up, many capability mismatch problems arise. The problem that has the greatest impact on computer performance is ( ).","stemCn":"当处理器性能快速发展而其他计算机组件的性能却未能跟上时，就会出现许多能力不匹配的问题。对计算机性能影响最大的问题是（ ）。","options":[{"key":"A","textEn":"The interface problem between the processor and main memory","textCn":"处理器和主存之间的接口问题"},{"key":"B","textEn":"The interface problem between main memory and external memory","textCn":"主存与外存之间的接口问题"},{"key":"C","textEn":"The speed mismatch between the processor and peripherals","textCn":"处理器和外设之间的速度不匹配"},{"key":"D","textEn":"The speed mismatch between external devices and internal memory","textCn":"外部设备和内存之间的速度不匹配"}],"answerKey":"A","explanationCn":"处理器速度提升很快，而主存储器访问速度提升相对较慢，导致 CPU 经常需要等待主存，这就是常说的“存储墙”问题。由于 CPU 和主存之间的数据交换非常频繁，因此处理器与主存储器之间的接口和速度差异对整机性能影响最大。","explanationEn":""},{"id":"coa-ch02-004","chapterId":"ch02","chapterName":"第二章计算机演变","stemEn":"ARM processors are designed to meet the needs of ( ).","stemCn":"ARM 处理器旨在满足 ( ) 的需求。","options":[{"key":"A","textEn":"Embedded real-time systems","textCn":"嵌入式实时系统"},{"key":"B","textEn":"Application platforms","textCn":"应用平台"},{"key":"C","textEn":"Application security","textCn":"应用安全"},{"key":"D","textEn":"All of the above","textCn":"上述所有的"}],"answerKey":"D","explanationCn":"ARM 处理器具有低功耗、高性能、可扩展性强等特点，广泛应用于嵌入式实时系统、移动和应用平台，同时也支持安全机制。因此 A、B、C 都符合 ARM 处理器的设计需求，应选 D。","explanationEn":""},{"id":"coa-ch03-001","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"Which of the following cannot be transmitted on the data bus?","stemCn":"以下哪项不能在数据总线上传输？","options":[{"key":"A","textEn":"Instructions","textCn":"指令"},{"key":"B","textEn":"Source operands","textCn":"源操作数"},{"key":"C","textEn":"Interrupt request signals","textCn":"中断请求信号"},{"key":"D","textEn":"Destination operands","textCn":"目标操作数"}],"answerKey":"C","explanationCn":"数据总线用于传输数据，包括指令、源操作数和目的操作数等。中断请求信号属于控制信息，应通过控制总线传输，而不是通过数据总线传输。","explanationEn":""},{"id":"coa-ch03-002","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"In one bus transaction, the master module only needs to provide a starting address, and the slave device can read or write multiple data items from several consecutive address units starting from that address. This type of bus data transfer is called ( ).","stemCn":"在一次总线事务中，主控模块只需要提供一个起始地址，从属设备就可以从该地址开始的几个连续的地址单元中读取或写入多个数据项。这种类型的总线数据传输称为（ ）。","options":[{"key":"A","textEn":"Parallel transfer","textCn":"并行传输"},{"key":"B","textEn":"Serial transfer","textCn":"串行传输"},{"key":"C","textEn":"Synchronous transfer","textCn":"同步传输"},{"key":"D","textEn":"Block transfer / burst transfer","textCn":"块传输/突发传输"}],"answerKey":"D","explanationCn":"块传输，也称突发传输，是指主设备给出一个起始地址后，连续传输多个相邻地址中的数据。这样可以减少每次传输都重新给出地址的开销，提高总线传输效率。","explanationEn":""},{"id":"coa-ch03-003","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"Multiple components connected to a bus ( ).","stemCn":"连接到总线的多个组件 ( )。","options":[{"key":"A","textEn":"Can only send data to the bus at different times, but may receive data from the bus at the same time","textCn":"只能在不同时间向总线发送数据，但可能同时从总线接收数据"},{"key":"B","textEn":"Can only send data to the bus at different times, and can only receive data from the bus at different times","textCn":"只能在不同时间向总线发送数据，并且只能在不同时间从总线接收数据"},{"key":"C","textEn":"Can send data to the bus at the same time, but can only receive data from the bus at different times","textCn":"可以同时向总线发送数据，但只能分时从总线接收数据"},{"key":"D","textEn":"Can send data to the bus at the same time, and may receive data from the bus at the same time","textCn":"可以同时向总线发送数据，也可以同时从总线接收数据"}],"answerKey":"A","explanationCn":"总线是共享传输介质，同一时刻只能有一个部件向总线发送数据，否则会产生冲突。但多个部件可以同时从总线上接收同一份数据，因此选 A。","explanationEn":""},{"id":"coa-ch03-004","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"The system bus is used to connect components such as ( ).","stemCn":"系统总线用于连接( )等组件。","options":[{"key":"A","textEn":"Registers and arithmetic units","textCn":"寄存器和算术单元"},{"key":"B","textEn":"CPU, main memory, and I/O modules","textCn":"CPU、主存和I/O模块"},{"key":"C","textEn":"Arithmetic units and controllers","textCn":"算术单元和控制器"},{"key":"D","textEn":"Interfaces and peripherals","textCn":"接口及外围设备"}],"answerKey":"B","explanationCn":"系统总线是计算机系统中的公共通信通道，主要用于连接 CPU、主存储器和 I/O 模块。寄存器与运算器之间通常通过 CPU 内部总线连接，接口和外设之间也不是系统总线的主要连接对象。","explanationEn":""},{"id":"coa-ch03-005","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"Which of the following statements about bus design is incorrect?","stemCn":"以下关于总线设计的表述哪一项是不正确的？","options":[{"key":"A","textEn":"A parallel bus must be faster than a serial bus","textCn":"并行总线必须比串行总线更快"},{"key":"B","textEn":"Signal-line multiplexing can reduce the number of signal lines","textCn":"信号线复用可以减少信号线数量"},{"key":"C","textEn":"Block transfer / burst transfer can improve the bus data transfer rate","textCn":"块传输/突发传输可以提高总线数据传输速率"},{"key":"D","textEn":"Split-transaction communication can improve bus utilization","textCn":"分割事务通信可以提高总线利用率"}],"answerKey":"A","explanationCn":"并行总线一次可以传输多位数据，但并不一定总比串行总线快。高速串行总线通过提高时钟频率、减少信号干扰和简化线路设计，也可以达到很高的数据传输速率。因此 A 的说法过于绝对，是错误的。","explanationEn":""},{"id":"coa-ch03-006","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"If counter-polling arbitration is used for bus arbitration, and each count starts from the stopping point of the previous count, then ( ).","stemCn":"如果总线仲裁采用计数器轮询仲裁，并且每次计数都从前一次计数的停止点开始，则( )。","options":[{"key":"A","textEn":"Devices with smaller device numbers have higher priority","textCn":"设备编号越小的设备优先级越高"},{"key":"B","textEn":"Devices with larger device numbers have higher priority","textCn":"设备编号越大的设备优先级越高"},{"key":"C","textEn":"Each device has an equal opportunity to use the bus","textCn":"每个设备都有平等的机会使用总线"},{"key":"D","textEn":"The priority of devices cannot be determined","textCn":"无法确定设备的优先级"}],"answerKey":"C","explanationCn":"如果计数器每次都从上一次停止的位置继续计数，那么总线使用机会会在各设备之间轮流分配，不会固定偏向编号小或编号大的设备。因此每个设备获得总线的机会基本相等。","explanationEn":""},{"id":"coa-ch03-007","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"Synchronous control is ( ).","stemCn":"同步控制为（ ）。","options":[{"key":"A","textEn":"A control method only used for CPU control","textCn":"仅用于CPU控制的控制方式"},{"key":"B","textEn":"A control method only used for I/O control","textCn":"仅用于I/O控制的控制方式"},{"key":"C","textEn":"A control method controlled by a unified timing signal","textCn":"一种统一定时信号控制的控制方法"},{"key":"D","textEn":"A control method in which all instructions have the same execution time","textCn":"所有指令执行时间相同的控制方法"}],"answerKey":"C","explanationCn":"同步控制方式的特点是各操作按照统一的时钟信号或统一的时序信号进行控制。它并不是只适用于 CPU 或 I/O，也不表示所有指令执行时间都完全相同。","explanationEn":""},{"id":"coa-ch03-008","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"Asynchronous bus communication is ( ).","stemCn":"异步总线通信是( )。","options":[{"key":"A","textEn":"It requires neither clock signals nor handshake signals","textCn":"它既不需要时钟信号也不需要握手信号"},{"key":"B","textEn":"It only requires clock signals and does not require handshake signals","textCn":"只需要时钟信号，不需要握手信号"},{"key":"C","textEn":"It requires both clock signals and handshake signals","textCn":"它需要时钟信号和握手信号"},{"key":"D","textEn":"It does not require clock signals and only requires handshake signals","textCn":"不需要时钟信号，只需要握手信号"}],"answerKey":"D","explanationCn":"异步通信不使用统一的时钟信号，而是通过请求、应答等握手信号来协调发送方和接收方的工作。因此它适合速度不同的模块之间通信。","explanationEn":""},{"id":"coa-ch03-009","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"According to the different components connected by buses, buses can be divided into ( ).","stemCn":"根据总线连接的部件不同，总线可分为（ ）。","options":[{"key":"A","textEn":"Data bus, address bus, and control bus","textCn":"数据总线、地址总线和控制总线"},{"key":"B","textEn":"On-chip bus, system bus, and external bus","textCn":"片内总线、系统总线、外部总线"},{"key":"C","textEn":"Memory bus, I/O bus, and DMA bus","textCn":"内存总线、I/O 总线和 DMA 总线"},{"key":"D","textEn":"ISA bus, VESA bus, and PCI bus","textCn":"ISA总线、VESA总线、PCI总线"}],"answerKey":"B","explanationCn":"按照连接部件的不同，总线可以分为片内总线、系统总线和外部总线。按照传输信息的不同，才可分为数据总线、地址总线和控制总线。","explanationEn":""},{"id":"coa-ch03-010","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"In bus design, which of the following factors does not need to be considered?","stemCn":"在总线设计中，以下哪一个因素不需要考虑？","options":[{"key":"A","textEn":"Bus length","textCn":"总线长度"},{"key":"B","textEn":"Bus arbitration method","textCn":"总线仲裁方式"},{"key":"C","textEn":"Bus width","textCn":"总线宽度"},{"key":"D","textEn":"Bus type","textCn":"总线类型"}],"answerKey":"A","explanationCn":"总线设计中通常重点考虑总线类型、总线宽度、总线仲裁方式、通信方式、传输方式等。总线长度虽然会影响物理实现中的信号质量，但在本题所考查的总线逻辑设计因素中，不作为主要设计因素，因此选 A。","explanationEn":""},{"id":"coa-ch04-001","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"Which of the following factors does not affect the Cache hit rate?","stemCn":"以下哪个因素不影响Cache命中率？","options":[{"key":"A","textEn":"Cache capacity","textCn":"缓存容量"},{"key":"B","textEn":"Main memory access time","textCn":"主存存取时间"},{"key":"C","textEn":"Cache line size","textCn":"缓存行大小"},{"key":"D","textEn":"The replacement algorithm used","textCn":"使用的替换算法"}],"answerKey":"B","explanationCn":"Cache 命中率主要受以下因素影响： - Cache 容量 - Cache 行大小 - 映射方式 - 替换算法 - 程序访问局部性 主存访问时间会影响**缺失代价**和系统平均访问时间，但它不会直接决定 Cache 是否命中。 因此不会影响 Cache 命中率的是 **main memory access time**，选 B。","explanationEn":""},{"id":"coa-ch04-002","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"Which of the following statements about Cache write policies in a uniprocessor system is incorrect?","stemCn":"以下关于单处理器系统中的 Cache 写入策略的表述哪一项是不正确的？","options":[{"key":"A","textEn":"If iterative operations are very frequent, write-back is suitable.","textCn":"如果迭代操作非常频繁，则适合回写。"},{"key":"B","textEn":"Write-through can strictly guarantee the consistency of Cache data and main memory data.","textCn":"Write-through可以严格保证Cache数据和主存数据的一致性。"},{"key":"C","textEn":"In general, write-through generates much more write traffic than write-back.","textCn":"一般来说，直写产生的写流量比回写多得多。"},{"key":"D","textEn":"Write-back is suitable for systems in which I/O modules are directly connected to main memory.","textCn":"回写式适用于 I/O 模块直接连接到主存储器的系统。"}],"answerKey":"D","explanationCn":"写策略主要包括： 1. **Write-through（写直达）** CPU 写 Cache 时，同时写入主存，因此主存和 Cache 数据一致性较好，但写主存次数多，写流量大。 2. **Write-back（写回）** CPU 修改 Cache 后，先只修改 Cache，并设置修改位；当该块被替换时才写回主存。它可以减少写主存次数，适合频繁修改同一数据的场景。 D 错误的原因是： 如果 I/O 模块直接访问主存，而 CPU 修改的数据暂时只保存在 Cache 中没有写回主存，那么 I/O 设备从主存读到的可能是旧数据，会造成 Cache 与主存一致性问题。 因此写回法并不适合直接主存访问频繁且缺少一致性维护机制的系统。","explanationEn":""},{"id":"coa-ch04-003","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"The main purpose of separating instruction Cache and data Cache is ( ).","stemCn":"分离指令Cache和数据Cache的主要目的是（ ）。","options":[{"key":"A","textEn":"To improve the Cache hit rate","textCn":"提高Cache命中率"},{"key":"B","textEn":"To reduce possible resource conflicts","textCn":"减少可能的资源冲突"},{"key":"C","textEn":"To reduce the system average access time","textCn":"减少系统平均访问时间"},{"key":"D","textEn":"To improve Cache utilization","textCn":"提高缓存利用率"}],"answerKey":"B","explanationCn":"指令 Cache 和数据 Cache 分离的主要目的，是减少取指令和访问数据之间的冲突。 在流水线处理器中，CPU 可能一边取指令，一边访问数据。如果指令和数据共用一个 Cache，就可能发生资源竞争。 采用分离的 I-Cache 和 D-Cache 后，取指和访存可以同时进行，从而减少结构相关和资源冲突。 因此选 B。","explanationEn":""},{"id":"coa-ch04-004","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"In Cache replacement algorithms, which algorithm takes both the locality principle and the residence time factor into account?","stemCn":"Cache替换算法中，哪种算法同时考虑了局部性原则和停留时间因素？","options":[{"key":"A","textEn":"Random replacement algorithm (RAND)","textCn":"随机替换算法（RAND）"},{"key":"B","textEn":"First-in first-out algorithm (FIFO)","textCn":"先进先出算法（FIFO）"},{"key":"C","textEn":"Least frequently used algorithm (LFU)","textCn":"最不常用算法 (LFU)"},{"key":"D","textEn":"Least recently used algorithm (LRU)","textCn":"最近最少使用算法（LRU）"}],"answerKey":"D","explanationCn":"LRU，即最近最少使用算法，会替换最长时间没有被访问过的 Cache 块。 它的依据是程序的**时间局部性**：最近被访问过的数据，在不久的将来很可能再次被访问。 同时，LRU 也考虑了块在 Cache 中的“近期使用情况”，即某个块已经多久没有被访问。 因此 LRU 兼顾了局部性原理和驻留时间因素，选 D。","explanationEn":""},{"id":"coa-ch04-005","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"When a Cache miss occurs, the main memory not only needs to send information to the CPU, but also needs to write information into the Cache. In this process, the widths of the information transferred from main memory to the CPU and from main memory to the Cache are respectively ( ).","stemCn":"当发生Cache miss时，主存不仅需要向CPU发送信息，还需要将信息写入Cache中。在此过程中，从主存到CPU和从主存到Cache传输的信息宽度分别为( )。","options":[{"key":"A","textEn":"Block, block","textCn":"块，块"},{"key":"B","textEn":"Block, word","textCn":"块、字"},{"key":"C","textEn":"Word, block","textCn":"字、块"},{"key":"D","textEn":"Word, word","textCn":"字、字"}],"answerKey":"C","explanationCn":"当 Cache 未命中时，CPU 当前真正需要的是某一个具体的数据字或指令字，因此主存给 CPU 传送的信息宽度通常是**字**。 但是为了利用空间局部性，系统会把包含该字的整个主存块调入 Cache，所以主存给 Cache 传送的信息宽度是**块**。 因此： $$ 主存 \\to CPU：字 $$ $$ 主存 \\to Cache：块 $$ 选 C。","explanationEn":""},{"id":"coa-ch04-006","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"A Cache system has a main memory capacity of 16 MB and a Cache capacity of 128 KB. The capacity of this Cache system is ( ).","stemCn":"Cache系统的主存容量为16MB，Cache容量为128KB。该Cache系统的容量为( )。","options":[{"key":"A","textEn":"16 MB + 128 KB","textCn":"16MB + 128KB"},{"key":"B","textEn":"16 MB","textCn":"16MB"},{"key":"C","textEn":"16 MB - 128 KB","textCn":"16 MB - 128 KB"},{"key":"D","textEn":"128 KB","textCn":"128KB"}],"answerKey":"B","explanationCn":"Cache 是主存中部分内容的副本，并不是在主存地址空间之外额外增加的一块可编址存储空间。 因此，系统的存储容量仍然由主存容量决定，而不是主存容量加 Cache 容量。 所以该 Cache 系统的容量为： $$ 16MB $$ 选 B。","explanationEn":""},{"id":"coa-ch04-007","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"When the CPU executes a program segment, the number of Cache hits is 1900 and the number of memory accesses caused by Cache misses is 100. The Cache access cycle is 50 ns, and the main memory access cycle is 250 ns. The average access time of the system is ( ).","stemCn":"CPU执行一个程序段时，Cache命中次数为1900次，Cache未命中导致的内存访问次数为100次。Cache访问周期为50 ns，主存访问周期为250 ns。系统的平均访问时间为（ ）。","options":[{"key":"A","textEn":"62.5 ns","textCn":"62.5纳秒"},{"key":"B","textEn":"50 ns","textCn":"50纳秒"},{"key":"C","textEn":"250 ns","textCn":"250纳秒"},{"key":"D","textEn":"58 ns","textCn":"58纳秒"}],"answerKey":"A","explanationCn":"已知： - Cache 命中次数：$1900$ - Cache 未命中次数：$100$ - 总访问次数： $$ 1900 + 100 = 2000 $$ Cache 命中率为： $$ H = \\frac{1900}{2000} = 0.95 $$ Cache 未命中率为： $$ 1 - H = 0.05 $$ 命中时，只需要访问 Cache： $$ T_{hit} = 50ns $$ 未命中时，通常需要先访问 Cache 发现未命中，再访问主存： $$ T_{miss} = 50ns + 250ns = 300ns $$ 平均访问时间为： $$ T = H \\times T_{hit} + (1-H) \\times T_{miss} $$ 代入数据： $$ T = 0.95 \\times 50 + 0.05 \\times 300 $$ $$ T = 47.5 + 15 = 62.5ns $$ 所以选 A。 也可以写成： $$ T = 50 + 0.05 \\times 250 = 62.5ns $$","explanationEn":""},{"id":"coa-ch04-008","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"The computer storage system consists of ( ).","stemCn":"计算机存储系统由( )组成。","options":[{"key":"A","textEn":"Cache","textCn":"缓存"},{"key":"B","textEn":"Register set","textCn":"寄存器组"},{"key":"C","textEn":"Cache, main memory, and auxiliary memory","textCn":"高速缓存、主存储器和辅助存储器"},{"key":"D","textEn":"Auxiliary memory","textCn":"辅助存储器"}],"answerKey":"C","explanationCn":"计算机存储系统通常是一个层次结构，包括： - Cache：速度快、容量小 - Main memory：CPU 可直接访问，容量较大 - Auxiliary memory：容量大、速度较慢，例如硬盘、SSD 等 因此，计算机存储系统不是单独的 Cache 或辅存，而是由 Cache、主存和辅存共同构成。 选 C。","explanationEn":""},{"id":"coa-ch04-009","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"Among the following types of memory, which one must be accessed by the CPU through an I/O process?","stemCn":"下列存储器中，哪一种必须由 CPU 通过 I/O 过程访问？","options":[{"key":"A","textEn":"Hard disk","textCn":"硬盘"},{"key":"B","textEn":"Main memory","textCn":"主存储器"},{"key":"C","textEn":"Cache","textCn":"缓存"},{"key":"D","textEn":"Registers","textCn":"寄存器"}],"answerKey":"A","explanationCn":"CPU 可以直接访问寄存器、Cache 和主存。 但是硬盘属于外部存储设备，CPU 不能像访问主存一样直接访问硬盘中的数据，而需要通过 I/O 控制器、设备驱动、总线等 I/O 过程完成读写。 因此选 A。","explanationEn":""},{"id":"coa-ch04-010","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"A magnetic disk belongs to which type of memory?","stemCn":"磁盘属于哪种类型的存储器？","options":[{"key":"A","textEn":"Random access memory","textCn":"随机存取存储器"},{"key":"B","textEn":"Read-only memory","textCn":"只读存储器"},{"key":"C","textEn":"Sequential access memory","textCn":"顺序存取存储器"},{"key":"D","textEn":"Direct access memory","textCn":"直接存取存储器"}],"answerKey":"D","explanationCn":"磁盘可以根据磁道、扇区等地址信息直接定位到较小的数据区域，而不需要像磁带那样必须从头顺序读到目标位置。 因此磁盘属于**直接存取存储器**。 注意区分： - 磁带：典型顺序存取 - 磁盘：典型直接存取 - RAM：随机存取 所以选 D。","explanationEn":""},{"id":"coa-ch04-011","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"For internal memory, its ( ) should be equal to the number of data lines connected to the memory module.","stemCn":"对于内部存储器，其 ( ) 应等于连接到存储器模块的数据线的数量。","options":[{"key":"A","textEn":"Access time","textCn":"访问时间"},{"key":"B","textEn":"Transfer unit","textCn":"传送单位"},{"key":"C","textEn":"Capacity","textCn":"容量"},{"key":"D","textEn":"Storage rate","textCn":"存储率"}],"answerKey":"B","explanationCn":"内部存储器每次和外部交换数据的位数，取决于连接到存储器模块的数据线条数。 例如数据线有 32 条，则一次可以传送 32 位数据。这个一次传送的数据位数称为**传送单位**。 因此： $$ 传送单位 = 数据线条数对应的数据位数 $$ 所以选 B。","explanationEn":""},{"id":"coa-ch04-012","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"( ) is equal to the access time plus the additional time required before the next memory access can begin.","stemCn":"( ) 等于访问时间加上下一次内存访问开始之前所需的额外时间。","options":[{"key":"A","textEn":"Latency time","textCn":"延迟时间"},{"key":"B","textEn":"Direct access time","textCn":"直接访问时间"},{"key":"C","textEn":"Transfer rate","textCn":"传输率"},{"key":"D","textEn":"Memory cycle time","textCn":"存储器存取周期"}],"answerKey":"D","explanationCn":"存储器的访问时间指从发出读写请求到完成数据访问所需的时间。 但是一次存储器访问结束后，存储器可能还需要一定的恢复时间，才能开始下一次访问。 因此，存取周期时间包括两部分： $$ 存取周期时间 = 访问时间 + 恢复时间或附加时间 $$ 所以题干所描述的是 **Memory cycle time（存取周期时间）**，选 D。","explanationEn":""},{"id":"coa-ch04-013","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"When the ( ) policy is used, every write operation to the Cache must also be performed in main memory.","stemCn":"当使用( )策略时，对Cache的每个写操作也必须在主存中执行。","options":[{"key":"A","textEn":"Write-through","textCn":"直写式"},{"key":"B","textEn":"Write-back","textCn":"回写"},{"key":"C","textEn":"LRU","textCn":"LRU"},{"key":"D","textEn":"FIFO","textCn":"FIFO（先进先出）"}],"answerKey":"A","explanationCn":"写直达策略中，CPU 写 Cache 的同时，也要把相同内容写入主存。 这样可以保证 Cache 和主存中的数据始终保持一致。 写直达的特点是： - 优点：一致性好，主存数据始终较新； - 缺点：每次写 Cache 都要写主存，写流量较大，速度可能较慢。 与之相对，写回策略只在 Cache 块被替换时才把修改过的数据写回主存。 因此本题选 A。","explanationEn":""},{"id":"coa-ch05-001","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"A SRAM memory chip has a capacity of 128 KB and is addressed with a word length of 32 bits. If its address range starts from `0000H`, then the ending address is ( ).","stemCn":"SRAM 存储器芯片的容量为 128 KB，并以 32 位字长进行寻址。如果其地址范围从‘0000H’开始，那么结束地址是( )。","options":[{"key":"A","textEn":"`3FFFH`","textCn":"`3FFFH`"},{"key":"B","textEn":"`7FFFH`","textCn":"`7FFFH`"},{"key":"C","textEn":"`FFFFH`","textCn":"`FFFFH`"},{"key":"D","textEn":"`5FFFH`","textCn":"`5FFFH`"}],"answerKey":"B","explanationCn":"已知 SRAM 容量为： $$ 128KB = 128 \\times 1024B = 131072B $$ 按 32 位字长编址： $$ 32bit = 4B $$ 所以可编址单元数为： $$ \\frac{131072B}{4B} = 32768 = 2^{15} $$ 地址从 `0000H` 开始，共有 $2^{15}$ 个地址，因此最后一个地址为： $$ 2^{15} - 1 = 32767 $$ 转换成十六进制： $$ 32767 = 7FFFH $$ 所以地址范围为： $$ 0000H \\sim 7FFFH $$ 选 B。","explanationEn":""},{"id":"coa-ch05-002","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"The CPU address lines are `A15` to `A0` from high to low. If several `16K × 4-bit` memory chips are used to form a 64 KB memory, which address lines should participate in chip-select decoding?","stemCn":"CPU地址线从高到低依次为‘A15’到‘A0’。如果用几个“16K×4位”存储芯片组成一个64KB的存储器，哪些地址线应该参与片选译码？","options":[{"key":"A","textEn":"`A1`, `A2`","textCn":"“A1”、“A2”"},{"key":"B","textEn":"`A14`, `A13`","textCn":"“A14”、“A13”"},{"key":"C","textEn":"`A15`, `A14`","textCn":"“A15”、“A14”"},{"key":"D","textEn":"`A3`, `A2`","textCn":"“A3”、“A2”"}],"answerKey":"C","explanationCn":"一个 `16K × 4-bit` 芯片的地址容量为： $$ 16K = 2^{14} $$ 所以芯片内部需要 14 根地址线： $$ A_0 \\sim A_{13} $$ CPU 地址线共有： $$ A_{15} \\sim A_0 $$ 要组成 64KB 存储器，需要把 64KB 地址空间分成若干个 16K 地址范围，因此高位地址线用于选择不同芯片组。 低 14 位 `A0 ~ A13` 用于芯片内部寻址，剩下的高 2 位： $$ A_{15}, A_{14} $$ 用于片选译码。 所以选 C。","explanationEn":""},{"id":"coa-ch05-003","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Four `32K × 8-bit` memory chips can be used to design a memory with a capacity of ( ).","stemCn":"可以使用四个“32K×8位”存储芯片来设计容量为（ ）的存储器。","options":[{"key":"A","textEn":"`32K × 16-bit`","textCn":"`32K × 16 位`"},{"key":"B","textEn":"`128K × 16-bit`","textCn":"`128K × 16 位`"},{"key":"C","textEn":"`32K × 16-bit`","textCn":"`32K × 16 位`"},{"key":"D","textEn":"`64K × 16-bit`","textCn":"`64K × 16 位`"}],"answerKey":"D","explanationCn":"每个芯片容量为： $$ 32K \\times 8bit $$ 若要组成 16 位字长，需要两个 `32K × 8-bit` 芯片进行**位扩展**： $$ 32K \\times 8bit + 32K \\times 8bit = 32K \\times 16bit $$ 现在共有 4 个芯片，可以分成两组，每组 2 个芯片。 每组形成： $$ 32K \\times 16bit $$ 两组再进行**字扩展**： $$ 32K \\times 16bit \\times 2 = 64K \\times 16bit $$ 所以可组成： $$ 64K \\times 16bit $$ 选 D。","explanationEn":""},{"id":"coa-ch05-004","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Which of the following statements about ROM and RAM is incorrect?","stemCn":"以下关于 ROM 和 RAM 的说法哪一项是不正确的？","options":[{"key":"A","textEn":"The readout of RAM is destructive, so regeneration is required after reading.","textCn":"RAM的读取具有破坏性，因此读取后需要重新生成。"},{"key":"B","textEn":"Flash memory belongs to semiconductor memory, so it has random access capability.","textCn":"闪存属于半导体存储器，因此具有随机存取能力。"},{"key":"C","textEn":"ROM can only be read and not written, and it can retain data after power failure.","textCn":"ROM只能读不能写，断电后仍能保留数据。"},{"key":"D","textEn":"SRAM does not need refreshing, while DRAM needs refreshing after reading.","textCn":"SRAM不需要刷新，而DRAM读取后需要刷新。"}],"answerKey":"A","explanationCn":"A 错误。RAM 包括 SRAM 和 DRAM，并不是所有 RAM 的读出都是破坏性读出。 SRAM 使用触发器保存数据，读出通常不是破坏性的，不需要再生。 DRAM 使用电容保存数据，读出可能破坏原有电荷状态，因此读后需要恢复或刷新。 B 正确。Flash 属于半导体存储器，读操作可以随机访问。 C 正确。ROM 通常断电后仍能保存数据。 D 正确。SRAM 不需要刷新，DRAM 需要刷新。 所以错误的是 A。","explanationEn":""},{"id":"coa-ch05-005","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Suppose the CPU has 24 address lines and 16 data lines. If `512K × 8-bit` RAM chips are used to construct the main memory of this machine, at most how many such chips are required?","stemCn":"假设CPU有24条地址线和16条数据线。如果用“512K×8位”RAM芯片来构建本机的主存，最多需要多少个这样的芯片？","options":[{"key":"A","textEn":"$2^{56}$","textCn":"$2^{56}$"},{"key":"B","textEn":"512","textCn":"512"},{"key":"C","textEn":"64","textCn":"64"},{"key":"D","textEn":"128","textCn":"128"}],"answerKey":"C","explanationCn":"CPU 有 24 根地址线，因此可表示的地址个数为： $$ 2^{24} $$ 数据总线为 16 位，所以每个地址单元的数据宽度按 16 位计算。 因此主存总容量为： $$ 2^{24} \\times 16bit $$ 每片 RAM 芯片容量为： $$ 512K \\times 8bit $$ 其中： $$ 512K = 512 \\times 1024 = 2^{19} $$ 所以每片芯片容量为： $$ 2^{19} \\times 8bit = 2^{19} \\times 2^3bit = 2^{22}bit $$ 主存总容量为： $$ 2^{24} \\times 16bit = 2^{24} \\times 2^4bit = 2^{28}bit $$ 所需芯片数为： $$ \\frac{2^{28}}{2^{22}} = 2^6 = 64 $$ 所以选 C。","explanationEn":""},{"id":"coa-ch05-006","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Which of the following can send data to the processor twice in each clock cycle?","stemCn":"以下哪项可以在每个时钟周期内向处理器发送两次数据？","options":[{"key":"A","textEn":"DDR DRAM","textCn":"DDR DRAM（双倍数据率动态随机存储器）"},{"key":"B","textEn":"SDRAM","textCn":"SDRAM（同步动态随机存储器）"},{"key":"C","textEn":"CDRAM","textCn":"CDRAM（带缓存的动态随机存储器）"},{"key":"D","textEn":"None of the above","textCn":"以上都不是"}],"answerKey":"A","explanationCn":"DDR DRAM 的 DDR 是 **Double Data Rate**，即双倍数据率。 它可以在时钟信号的上升沿和下降沿各传输一次数据，因此每个时钟周期可以传输两次数据。 普通 SDRAM 通常每个时钟周期传输一次数据。 CDRAM 是带缓存的 DRAM，不是“双沿传输”的典型定义。 所以选 A。","explanationEn":""},{"id":"coa-ch05-007","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"In which of the following memories is the traditional flip-flop logic-gate method used to store binary numbers?","stemCn":"以下哪种存储器是采用传统的触发器逻辑门方法来存储二进制数的？","options":[{"key":"A","textEn":"ROM","textCn":"ROM（只读存储器）"},{"key":"B","textEn":"SRAM","textCn":"SRAM（静态随机存储器）"},{"key":"C","textEn":"DRAM","textCn":"DRAM（动态随机存储器）"},{"key":"D","textEn":"RAM","textCn":"RAM（随机存取存储器）"}],"answerKey":"B","explanationCn":"SRAM 使用触发器保存二进制信息。只要不断电，触发器状态可以保持，因此 SRAM 不需要刷新。 DRAM 使用电容存储电荷表示二进制信息，由于电容会漏电，所以需要定期刷新。 ROM 主要用于保存固定信息，不是用普通触发器作为基本存储单元。 因此采用传统触发器逻辑门方式存储二进制数的是 **SRAM**，选 B。","explanationEn":""},{"id":"coa-ch06-001","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Which of the following statements about disk storage is incorrect?","stemCn":"以下关于磁盘存储的说法哪一项是不正确的？","options":[{"key":"A","textEn":"The formatted capacity of a disk is smaller than its unformatted capacity.","textCn":"磁盘格式化后的容量小于未格式化的容量。"},{"key":"B","textEn":"A sector contains data, address information, and check information.","textCn":"扇区包含数据、地址信息和校验信息。"},{"key":"C","textEn":"The minimum read/write unit of a disk storage device is a byte.","textCn":"磁盘存储设备的最小读/写单位是字节。"},{"key":"D","textEn":"A disk drive may contain multiple platters, and the heads of all platters generally move together.","textCn":"磁盘驱动器可能包含多个盘片，并且所有盘片的磁头通常一起移动。"}],"answerKey":"C","explanationCn":"磁盘的最小读写单位不是字节，而是扇区。 也就是说，即使只需要访问某一个字节，磁盘实际读写时通常也要以扇区为单位进行数据传输。 其他选项分析： - A 正确：磁盘格式化后要划分扇区，并加入地址、同步、校验等控制信息，所以格式化容量小于非格式化容量。 - B 正确：扇区中不仅有用户数据，还包含地址标识、校验码等信息。 - D 正确：多盘片磁盘中通常每个盘面有磁头，这些磁头安装在同一组磁臂上，一般一起移动。 所以错误的是 C。","explanationEn":""},{"id":"coa-ch06-002","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"If the rotational speed of a disk doubles, then ( ).","stemCn":"如果磁盘转速加倍，则（ ）。","options":[{"key":"A","textEn":"The average access time will be halved.","textCn":"平均访问时间将减半。"},{"key":"B","textEn":"The average seek time will be halved.","textCn":"平均寻道时间将减半。"},{"key":"C","textEn":"The storage density will be doubled.","textCn":"存储密度将增加一倍。"},{"key":"D","textEn":"The rotational latency will be halved.","textCn":"旋转延迟将减半。"}],"answerKey":"D","explanationCn":"磁盘访问时间一般包括： $$ T_a = T_s + T_r + T_t $$ 其中： - $T_s$：寻道时间 - $T_r$：旋转延迟 - $T_t$：数据传输时间 当磁盘转速翻倍时，盘片转一圈所需时间减半，因此平均旋转延迟也会减半。 但要注意： - 平均寻道时间主要由磁头移动机构决定，与转速无直接关系。 - 存储密度由磁记录技术和磁道布局决定，不会因为转速翻倍而直接翻倍。 - 平均访问时间包含寻道时间、旋转延迟和传输时间，不能简单认为整体减半。 所以选 D。","explanationEn":""},{"id":"coa-ch06-003","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Which measures can be used to improve RAID reliability? I. Disk mirroring II. Striping III. Parity checking IV. Increasing the Cache mechanism","stemCn":"哪些措施可以提高 RAID 的可靠性？I. 磁盘镜像 II. 数据条带化 III. 奇偶校验 IV. 增加 Cache 机制","options":[{"key":"A","textEn":"I and II only","textCn":"仅限 I 和 II"},{"key":"B","textEn":"I and III only","textCn":"仅限 I 和 III"},{"key":"C","textEn":"I, II, and IV only","textCn":"仅 I、II 和 IV"},{"key":"D","textEn":"II, III, and IV only","textCn":"仅限 II、III 和 IV"}],"answerKey":"B","explanationCn":"用于提高 RAID 可靠性的主要措施是： - **Disk mirroring（磁盘镜像）**：例如 RAID 1，把相同数据写入多个磁盘，一块盘损坏后仍可由镜像盘恢复。 - **Parity checking（奇偶校验）**：例如 RAID 5、RAID 6，通过校验信息恢复故障磁盘中的数据。 条带化主要用于提高并行访问性能，本身不提供冗余保护。 增加 Cache 机制主要提高访问速度，也不是 RAID 可靠性的核心冗余措施。 因此正确的是 I 和 III，选 B。","explanationEn":""},{"id":"coa-ch06-004","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Which of the following optical discs can be both read and written?","stemCn":"下列哪种光盘既可以读取又可以写入？","options":[{"key":"A","textEn":"CD-ROM","textCn":"CD-ROM（只读光盘）"},{"key":"B","textEn":"CD-R","textCn":"CD-R（一次写入型光盘）"},{"key":"C","textEn":"CD-RW","textCn":"CD-RW（可擦写光盘）"},{"key":"D","textEn":"DVD","textCn":"DVD"}],"answerKey":"C","explanationCn":"CD-RW 中的 RW 表示 ReWritable，即可重写。它既可以读取，也可以多次写入和擦除。 其他选项： - CD-ROM：只读光盘，不能写入。 - CD-R：一次写入，多次读取，不能反复擦写。 - DVD：只是光盘类别，普通 DVD-ROM 只读，不能笼统认为一定可读写。 所以选 C。","explanationEn":""},{"id":"coa-ch06-005","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Which of the following statements about DVD is incorrect?","stemCn":"以下关于 DVD 的说法哪一项是不正确的？","options":[{"key":"A","textEn":"The pits and grooves of DVD are arranged more densely than those of CD.","textCn":"DVD 的凹坑和凹槽排列得比 CD 更密集。"},{"key":"B","textEn":"One side of a DVD can use a double-layer structure, and data in each layer can be read by adjusting the laser focus.","textCn":"DVD的一面可以采用双层结构，通过调整激光焦点可以读取每一层的数据。"},{"key":"C","textEn":"The track pitch of DVD is smaller than that of CD.","textCn":"DVD 的磁道间距比 CD 的小。"},{"key":"D","textEn":"DVD cannot record data on both sides.","textCn":"DVD 无法双面记录数据。"}],"answerKey":"D","explanationCn":"DVD 相比 CD 具有更高的数据密度，主要原因包括： - 坑点更小、排列更密； - 磁道间距或光道间距更小； - 可以采用单面双层结构； - 也可以采用双面结构存储数据。 因此 D“DVD 不能用双面记录数据”是错误的。DVD 可以有单面单层、单面双层、双面单层、双面双层等形式。","explanationEn":""},{"id":"coa-ch06-006","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Adjacent tracks on a disk are separated by ( ).","stemCn":"磁盘上的相邻磁道由 ( ) 分隔。","options":[{"key":"A","textEn":"Gaps","textCn":"间隙"},{"key":"B","textEn":"Sectors","textCn":"扇区"},{"key":"C","textEn":"Bits","textCn":"位"},{"key":"D","textEn":"Heads","textCn":"磁头"}],"answerKey":"A","explanationCn":"磁盘上的相邻磁道之间需要留出一定的间隙，防止读写时相互干扰。 这些间隙称为 gaps。 扇区是磁道上的分区，磁头是读写部件，位是数据的最小单位，都不是用来分隔相邻磁道的结构。 所以选 A。","explanationEn":""},{"id":"coa-ch06-007","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"The disadvantage of ( ) is that the amount of data stored on inner and outer tracks is the same.","stemCn":"()的缺点是内外磁道上存储的数据量是相同的。","options":[{"key":"A","textEn":"SSD","textCn":"SSD（固态硬盘）"},{"key":"B","textEn":"CAV","textCn":"CAV（恒定角速度）"},{"key":"C","textEn":"ROM","textCn":"ROM（只读存储器）"},{"key":"D","textEn":"CLV","textCn":"CLV（恒定线速度）"}],"answerKey":"B","explanationCn":"CAV 是 Constant Angular Velocity，即恒定角速度。 在 CAV 方式下，磁盘转速保持不变，通常每条磁道划分的扇区数相同，因此内圈磁道和外圈磁道存储的数据量相同。 但外圈磁道周长更长，如果仍然只存储与内圈相同的数据量，就会导致外圈空间利用率较低。 这就是 CAV 的一个缺点。 CLV 是恒定线速度，可以让不同半径处的数据通过速度相近，常见于一些光盘系统。 所以选 B。","explanationEn":""},{"id":"coa-ch07-001","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"When the system uses memory-mapped I/O, the instruction used to perform input/output operations is ( ).","stemCn":"当系统使用内存映射I/O时，用于执行输入/输出操作的指令是（ ）。","options":[{"key":"A","textEn":"Control instruction","textCn":"控制指令"},{"key":"B","textEn":"Memory access instruction","textCn":"内存访问指令"},{"key":"C","textEn":"Input/output instruction","textCn":"输入输出指令"},{"key":"D","textEn":"None of the above","textCn":"以上都不是"}],"answerKey":"B","explanationCn":"存储映射式 I/O 把 I/O 设备的寄存器地址映射到主存地址空间中。 因此 CPU 访问 I/O 设备时，就像访问主存单元一样，可以使用普通的访存指令，例如 load/store 指令。 这种方式不需要专门的输入/输出指令。 所以选 B。","explanationEn":""},{"id":"coa-ch07-002","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"Which of the following statements about I/O modules is incorrect?","stemCn":"以下关于 I/O 模块的描述哪一项是不正确的？","options":[{"key":"A","textEn":"The status register and the control register may share the same register.","textCn":"状态寄存器和控制寄存器可以共享同一个寄存器。"},{"key":"B","textEn":"The CPU usually sends the I/O device address to the I/O module, rather than sending it directly to the I/O device.","textCn":"CPU通常将I/O设备地址发送给I/O模块，而不是直接发送给I/O设备。"},{"key":"C","textEn":"In isolated I/O, the I/O device address and the main memory address may be the same.","textCn":"在隔离I/O中，I/O设备地址和主存储器地址可能相同。"},{"key":"D","textEn":"In memory-mapped I/O, the CPU cannot use memory access instructions to access I/O devices.","textCn":"在内存映射I/O中，CPU不能使用内存访问指令来访问I/O设备。"}],"answerKey":"D","explanationCn":"D 错误。存储映射式 I/O 的核心特点就是：I/O 端口或 I/O 设备寄存器被编入主存地址空间，CPU 可以使用访存指令访问这些 I/O 地址。 其他选项分析： - A 正确：某些设备中，状态寄存器和控制寄存器可能共用同一个寄存器，通过不同位表示不同含义。 - B 正确：CPU 通常把设备地址或端口地址发送给 I/O 模块，由 I/O 模块选择具体设备。 - C 正确：分离式 I/O 中，I/O 地址空间和主存地址空间是分开的，所以二者地址编号可能相同，但通过不同指令或控制信号区分。 所以错误的是 D。","explanationEn":""},{"id":"coa-ch07-003","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"In isolated I/O, memory units and I/O devices are distinguished by ( ).","stemCn":"在隔离I/O中，存储器单元和I/O设备用( )来区分。","options":[{"key":"A","textEn":"Different memories","textCn":"不同的存储器"},{"key":"B","textEn":"Different address lines","textCn":"不同的地址线"},{"key":"C","textEn":"Different instructions","textCn":"不同的指令"},{"key":"D","textEn":"Different data lines","textCn":"不同的数据线"}],"answerKey":"C","explanationCn":"分离式 I/O 又称独立编址 I/O。 在这种方式下，主存地址空间和 I/O 地址空间相互独立，可能出现相同的地址编号。 CPU 通过不同类型的指令来区分访问对象： - 访问主存：使用访存指令； - 访问 I/O 设备：使用专门的 I/O 指令。 因此区分存储单元和 I/O 设备的关键是**不同的指令**，选 C。","explanationEn":""},{"id":"coa-ch07-004","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"When the CPU responds to an interrupt, the first step it completes is ( ).","stemCn":"当CPU响应中断时，它完成的第一步是( )。","options":[{"key":"A","textEn":"Enable interrupts","textCn":"启用中断"},{"key":"B","textEn":"Save the breakpoint","textCn":"保存断点"},{"key":"C","textEn":"Disable interrupts","textCn":"禁用中断"},{"key":"D","textEn":"Transfer to the interrupt service routine","textCn":"转移到中断服务程序"}],"answerKey":"C","explanationCn":"CPU 响应中断时，首先需要关中断，防止在当前中断响应过程尚未完成时又被新的中断打断，造成现场混乱。 一般中断响应的大致过程为： 1. 关中断； 2. 保存断点，例如保存 PC； 3. 保存必要的硬件状态，例如 PSW； 4. 转入中断服务程序； 5. 中断处理完成后恢复现场； 6. 开中断并返回原程序。 所以最先完成的是关中断，选 C。","explanationEn":""},{"id":"coa-ch07-005","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"When the CPU responds to an interrupt, the two important hardware states that need to be protected are ( ).","stemCn":"当CPU响应中断时，需要保护的两个重要的硬件状态是( )。","options":[{"key":"A","textEn":"PC and PSW","textCn":"PC（程序计数器）和 PSW（程序状态字）"},{"key":"B","textEn":"PC and IR","textCn":"PC（程序计数器）和 IR（指令寄存器）"},{"key":"C","textEn":"MAR and IR","textCn":"MAR（存储器地址寄存器）和 IR（指令寄存器）"},{"key":"D","textEn":"MBR and PSW","textCn":"MBR（存储器缓冲寄存器）和 PSW（程序状态字）"}],"answerKey":"A","explanationCn":"CPU 响应中断时，必须保证中断处理结束后能够回到原程序继续执行，因此需要保存： - **PC，Program Counter，程序计数器**：保存下一条将要执行的指令地址，也就是断点； - **PSW，Program Status Word，程序状态字**：保存当前程序运行状态，例如条件码、中断允许位、处理器状态等。 IR、MAR、MBR 虽然也是重要寄存器，但通常不是中断响应中最核心、必须保护的两个硬件状态。 所以选 A。","explanationEn":""},{"id":"coa-ch07-006","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"Which of the following statements about interrupts is incorrect?","stemCn":"以下关于中断的描述哪一项是不正确的？","options":[{"key":"A","textEn":"The CPU responds to an interrupt only after an instruction finishes execution.","textCn":"CPU只有在指令执行完毕后才会响应中断。"},{"key":"B","textEn":"When the CPU is executing an interrupt service routine, it can no longer respond to interrupts.","textCn":"当CPU正在执行中断服务程序时，它不能再响应中断。"},{"key":"C","textEn":"The occurrence of an interrupt is independent of the execution of the current instruction.","textCn":"中断的发生与当前指令的执行无关。"},{"key":"D","textEn":"The CPU detects interrupt request signals to know whether there is an interrupt.","textCn":"CPU通过检测中断请求信号来知道是否有中断发生。"}],"answerKey":"B","explanationCn":"B 错误。CPU 在执行中断服务程序时，并不是绝对不能响应新的中断。 在支持多级中断或中断嵌套的系统中，如果更高优先级的中断请求到来，并且系统允许中断嵌套，CPU 可以暂停当前中断服务程序，转去响应更高优先级的中断。 其他选项分析： - A 正确：一般外部中断通常在一条指令执行结束后响应。 - C 正确：外部中断通常由外设或外部事件产生，与当前指令本身无直接关系。 - D 正确：CPU 通过检测中断请求线或中断请求信号判断是否有中断发生。 所以错误的是 B。","explanationEn":""},{"id":"coa-ch07-007","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"In DMA mode, during the data transfer process, the control of the bus is held by ( ).","stemCn":"在DMA模式下，在数据传输过程中，总线的控制权由( )保持。","options":[{"key":"A","textEn":"Peripheral device","textCn":"周边设备"},{"key":"B","textEn":"CPU","textCn":"CPU（中央处理器）"},{"key":"C","textEn":"Main memory","textCn":"主存储器"},{"key":"D","textEn":"DMA controller","textCn":"DMA控制器"}],"answerKey":"D","explanationCn":"DMA 方式下，数据传送由 DMA 控制器负责。 CPU 初始化 DMA 控制器后，DMA 控制器会请求总线控制权，并在获得总线后控制主存和外设之间的数据传送。 因此，在 DMA 数据传送过程中，总线控制权由 DMA 控制器掌握。 所以选 D。","explanationEn":""},{"id":"coa-ch07-008","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"Which of the following statements is correct?","stemCn":"下列说法是正确的？","options":[{"key":"A","textEn":"Both interrupt-driven I/O and DMA require interrupt requests to implement data transfer.","textCn":"中断驱动的I/O和DMA都需要中断请求来实现数据传输。"},{"key":"B","textEn":"Interrupt-driven I/O requires interrupt requests, while DMA does not require interrupt requests.","textCn":"中断驱动的I/O需要中断请求，而DMA不需要中断请求。"},{"key":"C","textEn":"Both interrupt-driven I/O and DMA require interrupt requests, but their purposes are different.","textCn":"中断驱动的I/O和DMA都需要中断请求，但它们的目的不同。"},{"key":"D","textEn":"DMA must wait until the instruction cycle ends before cycle stealing can be performed.","textCn":"DMA 必须等到指令周期结束才能执行周期窃取。"}],"answerKey":"C","explanationCn":"中断驱动式 I/O 和 DMA 都可能使用中断请求，但目的不同。 - **中断驱动式 I/O**：设备每次准备好数据或需要服务时，向 CPU 发中断请求，CPU 进入中断服务程序完成具体数据传送。 - **DMA 方式**：数据块传送过程中主要由 DMA 控制器完成，传送结束后通常通过中断通知 CPU，表示本次 DMA 操作完成。 因此两者都可能发中断请求，但中断的用途不同。 所以选 C。","explanationEn":""},{"id":"coa-ch07-009","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"In the I/O channel mode, the I/O program is stored in ( ).","stemCn":"在I/O通道模式下，I/O程序存储在( )中。","options":[{"key":"A","textEn":"Main memory","textCn":"主存储器"},{"key":"B","textEn":"I/O channel","textCn":"输入输出通道"},{"key":"C","textEn":"CPU","textCn":"CPU（中央处理器）"},{"key":"D","textEn":"Hard disk","textCn":"硬盘"}],"answerKey":"A","explanationCn":"I/O 通道方式中，CPU 会在主存中准备好通道程序，然后启动通道。 通道从主存中取出并执行通道程序，控制外设完成输入输出操作。 因此，I/O 程序，即通道程序，存放在主存中。 所以选 A。","explanationEn":""},{"id":"coa-ch07-010","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"Which of the following devices is more suitable to be connected to a byte multiplexor channel?","stemCn":"下列设备中，哪一种更适合连接字节多路通道？","options":[{"key":"A","textEn":"Hard disk","textCn":"硬盘"},{"key":"B","textEn":"Communication line","textCn":"通讯线"},{"key":"C","textEn":"High-speed network card","textCn":"高速网卡"},{"key":"D","textEn":"Keyboard","textCn":"键盘"}],"answerKey":"D","explanationCn":"字节多路通道适合连接多个低速字符设备，它以字节为单位在多个设备之间交替传送数据。 键盘属于典型低速输入设备，数据量小、传输速度低，适合连接在字节多路通道上。 硬盘和高速网卡属于高速设备，更适合数组多路通道或选择通道等方式。 所以选 D。","explanationEn":""},{"id":"coa-ch07-011","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"An I/O module needs to include the function of ( ) in order to coordinate the data flow between internal resources and external devices.","stemCn":"I/O 模块需要包含 ( ) 的功能，以协调内部资源和外部设备之间的数据流。","options":[{"key":"A","textEn":"Periodic polling","textCn":"定期轮询"},{"key":"B","textEn":"Status reporting","textCn":"状态报告"},{"key":"C","textEn":"Control and timing","textCn":"控制和计时"},{"key":"D","textEn":"Error detection","textCn":"错误检测"}],"answerKey":"C","explanationCn":"I/O 模块的核心功能之一是**控制和定时**。 由于 CPU、主存和外设之间速度不同、工作方式不同，I/O 模块必须通过控制信号和时序安排来协调它们之间的数据流。 例如： - 什么时候启动设备； - 什么时候读写数据； - 什么时候通知 CPU； - 什么时候进行状态检查或结束传输。 因此用于协调内部资源和外部设备之间数据流的是 **control and timing**，选 C。","explanationEn":""},{"id":"coa-ch07-012","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"If an I/O module can provide a high-level interface to the processor and handle most specific I/O operations, this type of I/O module is generally called a ( ).","stemCn":"如果一个I/O模块可以向处理器提供高级接口并处理大多数特定的I/O操作，则这种类型的I/O模块通常被称为( )。","options":[{"key":"A","textEn":"I/O channel","textCn":"输入输出通道"},{"key":"B","textEn":"DMA","textCn":"DMA"},{"key":"C","textEn":"I/O controller","textCn":"输入/输出控制器"},{"key":"D","textEn":"Device controller","textCn":"设备控制器"}],"answerKey":"A","explanationCn":"I/O 通道是一种功能较强的 I/O 部件，可以看作专门负责 I/O 操作的处理器。 它能够向 CPU 提供较高级的接口，并能执行通道程序，承担大部分具体 I/O 事务的处理。 CPU 只需要启动通道并提供相关参数，之后由 I/O 通道独立控制设备完成输入输出操作。 因此，这种能够分担 CPU I/O 管理工作的模块称为 **I/O channel**，选 A。","explanationEn":""},{"id":"coa-ch08-001","chapterId":"ch08","chapterName":"第八章","stemEn":"A machine has a word length of 8 bits, where the highest bit is the sign bit. If the true form (sign-magnitude) representation is used, what is the minimum non-zero positive number that can be represented by a fixed-point fractional number? ()","stemCn":"机器字长为 8 位，最高位为符号位。若采用原码（符号-数值）表示，定点小数可表示的最小非零正数是多少？（ ）","options":[{"key":"A","textEn":"$2^{-9}$","textCn":"$2^{-9}$"},{"key":"B","textEn":"$2^{-8}$","textCn":"$2^{-8}$"},{"key":"C","textEn":"$2^{-7}$","textCn":"$2^{-7}$"},{"key":"D","textEn":"$2^{-6}$","textCn":"$2^{-6}$"}],"answerKey":"C","explanationCn":": 机器字长为8位，最高位是符号位（占用1位），剩余的7位是数值位。对于定点小数，小数点固定在符号位之后。要表示最小的非零正数，符号位应为0（代表正数），数值位的最低位为1，其余高位均为0。即它的二进制形式为 $0.0000001_2$。根据二进制转十进制的权重，其对应的十进制真值为 $1 \\times 2^{-7}$。故选C。","explanationEn":""},{"id":"coa-ch08-002","chapterId":"ch08","chapterName":"第八章","stemEn":"Which of the following statements is correct? ()","stemCn":"下列说法是正确的？ ()","options":[{"key":"A","textEn":"When the machine uses two's complement representation, 0 has two encoding formats.","textCn":"当机器使用二进制补码表示时，0有两种编码格式。"},{"key":"B","textEn":"When the machine uses true form (sign-magnitude) representation, 0 has two encoding formats.","textCn":"采用原码（符号-数值）表示时，0 有两种编码。"},{"key":"C","textEn":"When the machine uses one's complement representation, 0 has one encoding format.","textCn":"采用反码表示时，0 只有一种编码。"},{"key":"D","textEn":"Regardless of the representation used for machine numbers, 0 always has two encoding formats.","textCn":"无论机器数采用哪种编码，0 始终有两种编码。"}],"answerKey":"B","explanationCn":": 在计算机的数据表示中： **原码 (Sign-Magnitude)**：0有两种表示方式，即正零（$0000...0$）和负零（$1000...0$）。所以选项B正确。 **反码 (One's Complement)**：0同样有两种表示方式，正零（$0000...0$）和负零（$1111...1$）。所以选项C错误。 **补码 (Two's Complement)**：0只有唯一的一种全零表示（例如8位补码中均为 $00000000$）。所以选项A错误。 综合上述，选项D也显然错误。故选B。","explanationEn":""},{"id":"coa-ch08-003","chapterId":"ch08","chapterName":"第八章","stemEn":"If $X = 104$ and $Y = -24$, which of the following expressions will cause an overflow when evaluated using 8-bit fixed-point two's complement arithmetic? ()","stemCn":"如果 $X = 104$ 且 $Y = -24$，使用 8 位定点二进制补码算术求值时，以下哪个表达式会导致溢出？ ()","options":[{"key":"A","textEn":"$X - Y$","textCn":"$X - Y$"},{"key":"B","textEn":"$-X + Y$","textCn":"$-X + Y$"},{"key":"C","textEn":"$X + Y$","textCn":"$X+Y$"},{"key":"D","textEn":"$-X - Y$","textCn":"$-X - Y$"}],"answerKey":"A","explanationCn":": 8位定点整数采用补码表示时，其能够表示的数值范围是 $[-128, 127]$。我们分别计算四个选项的实际结果： A) $X - Y = 104 - (-24) = 128$。结果128超出了8位补码能表示的最大正整数127，产生正溢出。 B) $-X + Y = -104 + (-24) = -128$。结果-128刚好等于8位补码能表示的最小负数，不发生溢出。 C) $X + Y = 104 + (-24) = 80$。结果在表示范围内，不发生溢出。 D) $-X - Y = -104 - (-24) = -80$。结果在表示范围内，不发生溢出。 故选A。","explanationEn":""},{"id":"coa-ch08-004","chapterId":"ch08","chapterName":"第八章","stemEn":"When an overflow occurs in fixed-point arithmetic, the system should ().","stemCn":"当定点运算发生溢出时，系统应该（）。","options":[{"key":"A","textEn":"Normalize to the left","textCn":"向左归一化"},{"key":"B","textEn":"Normalize to the right","textCn":"向右规格化"},{"key":"C","textEn":"Perform rounding","textCn":"执行舍入"},{"key":"D","textEn":"Issue an error message via an interrupt","textCn":"通过中断发出错误消息"}],"answerKey":"D","explanationCn":": 在计算机硬件算术逻辑单元（ALU）中执行定点运算时，如果结果超出了该数据类型所能表示的范围（发生溢出），硬件自身无法自动纠正这个错误（如浮点数可以通过调整阶码规格化来处理，但定点数没有阶码）。此时系统硬件会产生一个“溢出异常”（Overflow Exception），通常通过触发中断机制，将控制权转交给操作系统的中断处理程序，以便发出出错信息或终止程序运行。故选D。","explanationEn":""},{"id":"coa-ch08-005","chapterId":"ch08","chapterName":"第八章","stemEn":"In the standard floating-point representation, the () is hidden.","stemCn":"在标准浮点表示中，() 被隐藏。","options":[{"key":"A","textEn":"Exponent","textCn":"指数"},{"key":"B","textEn":"Radix point (Decimal point)","textCn":"基数点（小数点）"},{"key":"C","textEn":"Significand (Mantissa)","textCn":"有效数（尾数）"},{"key":"D","textEn":"Sign","textCn":"符号"}],"answerKey":"B","explanationCn":": 计算机中的浮点数和定点数一样，其小数点的位置是默认约定的，并不需要占用物理比特位来专门存储一个“小数点”符号。浮点数形式一般为 $N = (-1)^S \\times M \\times R^E$，其中符号位(S)、阶码(E)和有效数(M)都是实际存储在寄存器或内存当中的。因此，小数点是隐含（隐藏）的。（注：在IEEE 754标准中，规格化尾数最高位的1也是隐藏的，但在这些选项中，最根本的不占存储位的属性是小数点）。故选B。","explanationEn":""},{"id":"coa-ch08-006","chapterId":"ch08","chapterName":"第八章","stemEn":"The maximum integer that can be represented by a single-precision floating-point number in the IEEE 754 standard is ().","stemCn":"IEEE 754 标准中单精度浮点数可以表示的最大整数是 ()。","options":[{"key":"A","textEn":"$2^{-126} - 2^{-103}$","textCn":"$2^{-126} - 2^{-103}$"},{"key":"B","textEn":"$2^{127} - 2^{-104}$","textCn":"$2^{127} - 2^{-104}$"},{"key":"C","textEn":"$2^{128} - 2^{104}$","textCn":"$2^{128} - 2^{104}$"},{"key":"D","textEn":"$2^{127} - 2^{103}$","textCn":"$2^{127} - 2^{103}$"}],"answerKey":"C","explanationCn":": IEEE 754 单精度浮点数共32位，格式为：1位符号位(S) + 8位阶码(E) + 23位尾数(M)。 **符号位**：最大正数，所以 $S = 0$。 **阶码**：8位阶码能够表示的范围是 $0 \\sim 255$。其中255全1用来表示无穷大（Infinity）或非数值（NaN）。所以最大的合法规格化数值的阶码是254。由于单精度偏移量(Bias)为127，其实际的指数 $e = 254 - 127 = 127$。 **尾数**：要使值最大，23位尾数需全为1，此时尾数部分的值为 $(1 + 1 - 2^{-23})$，即 $(2 - 2^{-23})$。 因此，该浮点数表示的最大值为： $V = (2 - 2^{-23}) \\times 2^{127} = 2^{128} - 2^{104}$ 故选C。","explanationEn":""},{"id":"coa-ch08-007","chapterId":"ch08","chapterName":"第八章","stemEn":"The value range of a floating-point number depends on the ().","stemCn":"浮点数的取值范围取决于()。","options":[{"key":"A","textEn":"Number of bits in the exponent","textCn":"指数中的位数"},{"key":"B","textEn":"Number of bits in the significand (mantissa)","textCn":"有效数（尾数）中的位数"},{"key":"C","textEn":"Value of the exponent","textCn":"指数值"},{"key":"D","textEn":"Value of the significand (mantissa)","textCn":"有效数的值（尾数）"}],"answerKey":"A","explanationCn":": 在浮点数的格式中： 1. **阶码（指数）的位数**：决定了数值可以被放大的最大倍数或缩小的最小倍数，即决定了浮点数的**表示范围**（表数范围）。 2. **尾数（有效数）的位数**：决定了浮点数所能表示的有效数字的长度，即决定了浮点数的**精度**。 本题问的是“取值范围”，自然取决于指数位的位数。故选A。","explanationEn":""},{"id":"coa-ch08-008","chapterId":"ch08","chapterName":"第八章","stemEn":"The fundamental reason for overflow when performing arithmetic operations on fixed-point numbers is that ().","stemCn":"对定点数进行算术运算时发生溢出的根本原因是（）。","options":[{"key":"A","textEn":"The main memory capacity is insufficient","textCn":"主存容量不足"},{"key":"B","textEn":"The sign bit overflows","textCn":"符号位溢出"},{"key":"C","textEn":"The operand address is too large","textCn":"操作数地址太大"},{"key":"D","textEn":"The result of the operation exceeds the representable range","textCn":"运算结果超出可表示范围"}],"answerKey":"D","explanationCn":": 计算机内部使用有限长度的二进制位（字长）来表示数据。无论是8位、16位还是32位，其能够表示的最大和最小数值总是有一个固定的边界。当对数值进行加减等算术运算时，如果真实的数学结果超出了该字长所能表示的最大正界或最小负界，就会发生溢出。因此，“运算结果超过了所能表示的范围”是发生溢出的根本原因。故选D。","explanationEn":""},{"id":"coa-ch08-009","chapterId":"ch08","chapterName":"第八章","stemEn":"The bit extension rule for integers represented in two's complement is ().","stemCn":"以二进制补码表示的整数的位扩展规则是（）。","options":[{"key":"A","textEn":"Move the sign bit to the leftmost position and fill the remaining empty bits with 0s","textCn":"将符号位移动到最左边的位置，剩余的空位用0填充"},{"key":"B","textEn":"Move the sign bit to the leftmost position and fill the remaining empty bits with 1s","textCn":"将符号位移至最左边位置，其余空位补1"},{"key":"C","textEn":"Move the sign bit to the leftmost position and fill the remaining empty bits with the sign bit","textCn":"将符号位移动到最左边的位置，用符号位填充剩余的空位"},{"key":"D","textEn":"Move the sign bit to the rightmost position and fill the remaining empty bits with 1s","textCn":"将符号位移至最右位置，其余空位补1"}],"answerKey":"C","explanationCn":": 将一个低字长的数据（例如8位）转换为高字长的数据（例如16位）称为位扩展（位扩展运算）。在补码表示法中，必须使用“符号扩展”（Sign Extension）来保证数值大小以及正负号在扩展后不变。具体规则是：将原来的符号位作为新的最高位（最左边），而在新增的那些中间空位上，全部填充原来的符号位。即正数高位全补0，负数高位全补1。故选C。","explanationEn":""},{"id":"coa-ch09-001","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"A negative number smaller than $-(2 - 2^{-23}) \\times 2^{128}$ is called ().","stemCn":"小于 $-(2 - 2^{-23}) \\times 2^{128}$ 的负数称为 ()。","options":[{"key":"A","textEn":"Negative overflow","textCn":"负溢出"},{"key":"B","textEn":"Negative underflow","textCn":"负下溢"},{"key":"C","textEn":"Positive overflow","textCn":"正溢出"},{"key":"D","textEn":"Positive underflow","textCn":"正下溢"}],"answerKey":"A","explanationCn":": 在 IEEE 754 单精度浮点数标准中： 能够表示的最大正数是 $(2 - 2^{-23}) \\times 2^{127}$（由于本题中给出的公式阶码部分写作 $2^{128}$ 通常代表超出表数最大极限的区域）。 无论如何，当一个数值由于运算结果负得太多，以至于它的绝对值超出了浮点格式所能表示的最大负数边界时，在数轴上它落在了最左侧无法触及的区域。这种情况被称为**负溢出（Negative overflow）**。故选A。","explanationEn":""},{"id":"coa-ch09-002","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"When a positive exponent exceeds the maximum allowable range, this condition is known as ().","stemCn":"当正指数超出最大允许范围时，这种情况称为（）。","options":[{"key":"A","textEn":"Significand underflow","textCn":"尾数下溢"},{"key":"B","textEn":"Radix overflow","textCn":"基数溢出"},{"key":"C","textEn":"Exponent overflow","textCn":"指数溢出"},{"key":"D","textEn":"Exponent underflow","textCn":"指数下溢"}],"answerKey":"C","explanationCn":": 浮点数的取值范围主要是由阶码（指数）的位数和它的范围决定的。当运算结果的阶码（即指数）超过了机器所能允许的最大正指数限制时，阶码部分无法正确存储，在硬件上被称为**阶码上溢（Exponent overflow）**或指数上溢。故选C。 ### Chapter 9: Instruction System (指令系统)","explanationEn":""},{"id":"coa-ch09-003","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Which of the following statements about a one-address instruction is correct? ()","stemCn":"下列关于单地址指令的表述哪一项是正确的？ ()","options":[{"key":"A","textEn":"It has only one operand.","textCn":"它只有一个操作数。"},{"key":"B","textEn":"It must have two operands, one of which is implicit.","textCn":"它必须有两个操作数，其中之一是隐式的。"},{"key":"C","textEn":"If there are two operands, they must be identical.","textCn":"如果有两个操作数，它们必须相同。"},{"key":"D","textEn":"It may involve two operands or only one operand.","textCn":"它可能涉及两个操作数或仅涉及一个操作数。"}],"answerKey":"D","explanationCn":": 单地址指令（One-address instruction）是指在指令格式中只显式给出一个地址码字段。 1. 它可能只对一个操作数进行单目运算，如取反、加1、减1、自增（如 `INC AC`），此时确实**只有一个操作数**。 2. 它也常常用于双目运算，此时指令只给出第二个操作数的地址，而第一个操作数被默认**隐含在累加器（ACC）**中。比如加法指令 `ADD X` 的功能是 $(ACC) + (X) \\rightarrow ACC$，这里**有两个操作数**。 综上所述，单地址指令可能隐式涉及两个操作数，也可能只涉及一个操作数。故选D。","explanationEn":""},{"id":"coa-ch09-004","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Generally, in a two-address instruction, the physical locations of the operands can be arranged in (). I. A main memory cell and a buffer memory II. Two data registers III. A main memory cell and a data register IV. A data register and a control memory V. A main memory cell and an external memory cell","stemCn":"一般情况下，二地址指令的操作数可分别位于何处？I. 主存单元和缓冲存储器 II. 两个数据寄存器 III. 主存单元和数据寄存器 IV. 数据寄存器和控制存储器 V. 主存单元和外存单元","options":[{"key":"A","textEn":"II, III, IV","textCn":"二、三、四"},{"key":"B","textEn":"II, III","textCn":"二、三"},{"key":"C","textEn":"I, II, III","textCn":"一、二、三"},{"key":"D","textEn":"I, II, III, V","textCn":"一、二、三、五"}],"answerKey":"B","explanationCn":": 指令系统中的操作数必须能被CPU的执行部件（ALU）直接或通过总线快速访问。常见的操作数寻址物理位置包括：**通用数据寄存器（Registers）**以及**主存储器单元（Main Memory）**。 **II (两个数据寄存器)**：即 RR (Register-Register) 型指令，非常普遍。 **III (一个主存单元和一个数据寄存器)**：即 RS (Register-Storage) 型指令，同样属于基本核心寻址。 其他选项中：I 中的高级缓存/缓冲存储器对程序员是硬件透明的，不用来在指令格式中显式作为物理源安排；IV 控制存储器属于微程序控制器内部，不对普通指令开放；V 外存（如磁盘）无法直接参与算术指令流执行。故选B。","explanationEn":""},{"id":"coa-ch09-005","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"When a two-address instruction is used to complete an arithmetic operation, the result is generally stored in ().","stemCn":"当使用二地址指令完成算术运算时，结果一般存放在()中。","options":[{"key":"A","textEn":"The location specified by one of the address codes","textCn":"由地址代码之一指定的位置"},{"key":"B","textEn":"The top of the stack","textCn":"栈顶"},{"key":"C","textEn":"The accumulator (ACC)","textCn":"累加器（ACC）"},{"key":"D","textEn":"None of the above","textCn":"以上都不是"}],"answerKey":"A","explanationCn":": 二地址指令的通用格式为 `OP A1, A2`。它显式给出了两个操作数地址 $A_1$ 和 $A_2$。在绝大多数通用计算机体系结构中，为了节省目标代码空间和减少多余的地址段，运算结果完成之后，通常默认覆盖并存回其中一个地址码所指向的空间（通常是目的操作数地址 $A_1$）。即运算逻辑为：$(A_1) \\text{ OP } (A_2) \\rightarrow A_1$。故选A。","explanationEn":""},{"id":"coa-ch09-006","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"During the process of instruction execution by the CPU, the address of the next instruction to be executed is generally provided by the ().","stemCn":"CPU在执行指令的过程中，下一条要执行的指令的地址一般由()提供。","options":[{"key":"A","textEn":"Address code field of the current instruction","textCn":"当前指令的地址码字段"},{"key":"B","textEn":"Program Counter (PC)","textCn":"程序计数器（PC）"},{"key":"C","textEn":"Compiler","textCn":"编译器"},{"key":"D","textEn":"Programmer","textCn":"程序员"}],"answerKey":"B","explanationCn":": *程序计数器（PC, Program Counter）**是 CPU 内部的关键控制寄存器，用来存放当前正在执行或即将执行的下一条指令在主存中的地址。在顺序执行程序时，每取出一个字节或一条指令，PC 的值会自动加上该指令所占的存储单元数，从而指向下一条相邻指令。故选B。","explanationEn":""},{"id":"coa-ch09-007","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Which of the following statements about instructions is INCORRECT? ()","stemCn":"下列关于指令的说法哪一项不正确？（ ）","options":[{"key":"A","textEn":"For a one-address instruction, its instruction length is always fixed.","textCn":"对于单地址指令，其指令长度始终是固定的。"},{"key":"B","textEn":"To facilitate instruction fetching, the length of an instruction is usually an integer multiple of the memory word length.","textCn":"为了方便取指令，指令的长度通常是存储器字长的整数倍。"},{"key":"C","textEn":"A zero-address instruction may have no operands.","textCn":"零地址指令可以没有操作数。"},{"key":"D","textEn":"A one-address instruction may involve one operand or two operands.","textCn":"一地址指令可以涉及一个操作数或两个操作数。"}],"answerKey":"A","explanationCn":": A 选项错误：指令中含有几个地址码（单地址、双地址）和指令本身的机器物理长度（字长）之间没有绝对的固定死绑定关系。在变长指令系统（如 x86）中，即便同为单地址指令，也会因为寻址方式的不同（变址、间接、立即数大小）导致最终机器码长度不同。 B 选项正确：指令长度设为存储字长的整数倍可以极大地简化控制器的取指硬件逻辑，提高访存对齐效率。 C 选项正确：零地址指令通常分为两类，一类是无需操作数的控制指令（如 `NOP`, `CLI`），另一类是操作数隐含在堆栈顶部的堆栈指令（如 `ADD`）。 D 选项正确：如前面所述，单地址指令可能操作ACC与主存单元（两个操作数），也可能只是对单个寄存器执行取反（一个操作数）。 题干要求选择错误的一项，故选A。","explanationEn":""},{"id":"coa-ch09-008","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"The function of a two-address instruction `OP A1, A2` is $(A_1) \\text{ OP } (A_2) \\rightarrow A_1$. Suppose $A_1$ represents a register address and $A_2$ represents a main memory address. If instructions are fetched from the main memory by default, how many times must the main memory be accessed to complete this instruction? ()","stemCn":"二地址指令‘OP A1, A2’的功能为$(A_1) \\text{ OP } (A_2) \\rightarrow A_1$。假设$A_1$代表寄存器地址，$A_2$代表主存地址。如果默认从主存取指令，那么需要访问主存多少次才能完成这条指令？ ()","options":[{"key":"A","textEn":"5","textCn":"5"},{"key":"B","textEn":"4","textCn":"4"},{"key":"C","textEn":"3","textCn":"3"},{"key":"D","textEn":"2","textCn":"2"}],"answerKey":"D","explanationCn":": 我们来细分整个指令执行周期中的访存（访问主存）次数： 1. **第一步（取指令）**：指令默认存储在主存中，CPU 必须访问一次主存将该指令取出送到指令寄存器（IR）中。**（访存 1 次）** 2. **第二步（取操作数）**： 操作数 1 在 $A_1$（寄存器），取它不需要访问主存。 操作数 2 在 $A_2$（主存），CPU 需要根据 $A_2$ 地址访问一次主存储器读取操作数。**（访存 1 次）** 3. **第三步（执行并写回结果）**：运算完成后，结果写回 $A_1$。由于 $A_1$ 属于 CPU 内部的通用寄存器，写回操作不需要访问主存。**（访存 0 次）** 综上所述，整个过程一共访问主存储器 $1 + 1 + 0 = 2$ 次。故选D。","explanationEn":""},{"id":"coa-ch09-009","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"In a computer, some stack-based zero-address arithmetic instructions do not explicitly provide the addresses of operands in the instruction format. The two operands participating in the operation come from ().","stemCn":"在计算机中，一些基于堆栈的零地址算术指令在指令格式中并未明确提供操作数的地址。参与运算的两个操作数来自()。","options":[{"key":"A","textEn":"Accumulator and Register","textCn":"累加器和寄存器"},{"key":"B","textEn":"The top of the stack and the next-to-top unit of the stack","textCn":"栈顶和次栈顶单元"},{"key":"C","textEn":"The top of the stack and a temporary register","textCn":"栈顶和临时寄存器"},{"key":"D","textEn":"Accumulator and a temporary register","textCn":"累加器和临时寄存器"}],"answerKey":"B","explanationCn":": 堆栈型计算机中的零地址运算指令（例如堆栈加法指令 `ADD`），其操作数都是**隐式寻址**的。执行该指令时，硬件会自动从系统堆栈的顶部弹出（Pop）连续的两个数据作为源操作数。这两个数原本分别存放在**栈顶（Top of the stack）**以及紧随其下的**次栈顶单元（Next-to-top unit of the stack）**。运算得出的结果最后还会被自动压入栈顶。故选B。","explanationEn":""},{"id":"coa-ch09-010","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Which of the following instructions CANNOT be used by an application program? ()","stemCn":"应用程序不能使用以下哪条指令？ ()","options":[{"key":"A","textEn":"Shift instructions","textCn":"移位指令"},{"key":"B","textEn":"Conversion instructions","textCn":"转换指令"},{"key":"C","textEn":"Privileged instructions","textCn":"特权指令"},{"key":"D","textEn":"Conditional branch instructions","textCn":"条件分支指令"}],"answerKey":"C","explanationCn":": 为了保证计算机系统的安全与稳定，防止普通的应用程序破坏操作系统或恶意控制硬件资源，计算机的指令集被划分为： 1. **用户级指令（非特权指令）**：如普通的算术运算、移位、逻辑转换、条件转移指令等，任何普通应用程序（运行在用户态/目态）均可自由使用。 2. **特权指令（Privileged instructions）**：诸如启动I/O设备、修改主存保护键、停机、改变系统工作状态等危及系统全局安全的指令。这类指令只允许操作系统内核（运行在核心态/管态）调用，应用程序绝对无权直接执行。故选C。","explanationEn":""},{"id":"coa-ch09-011","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"The function of program control instructions is to ().","stemCn":"程序控制指令的功能是（）。","options":[{"key":"A","textEn":"Perform arithmetic and logical operations","textCn":"执行算术和逻辑运算"},{"key":"B","textEn":"Transfer data between main memory and I/O devices","textCn":"在主存和I/O设备之间传输数据"},{"key":"C","textEn":"Change data formats","textCn":"更改数据格式"},{"key":"D","textEn":"Change the sequence of program execution","textCn":"改变程序执行顺序"}],"answerKey":"D","explanationCn":": 指令按功能分类中，**程序控制类指令**（如无条件转移 `JMP`、条件转移 `JZ`/`JC`、子程序调用 `CALL` 和返回 `RET`）其核心作用不是为了加工数据，而是为了控制和改写程序计数器（PC）的值，从而打断原本单一的自增顺序，**改变程序执行的先后顺序**，实现分支、循环或函数调用。故选D。","explanationEn":""},{"id":"coa-ch09-012","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Which of the following statements about the instruction system is INCORRECT? ()","stemCn":"下列关于指令系统的说法哪一项不正确？（ ）","options":[{"key":"A","textEn":"The instruction system has nothing to do with machine language.","textCn":"指令系统与机器语言无关。"},{"key":"B","textEn":"The instruction system is the complete set of instructions that a computer's hardware can execute.","textCn":"指令系统是计算机硬件能够执行的完整指令集。"},{"key":"C","textEn":"The instruction system is the interface/boundary between computer software and hardware.","textCn":"指令系统是计算机软件和硬件之间的接口/边界。"},{"key":"D","textEn":"Any program must be translated into a machine language program before it can be executed by the machine hardware.","textCn":"任何程序都必须先翻译成机器语言程序，然后才能被机器硬件执行。"}],"answerKey":"A","explanationCn":": A 选项错误：**机器语言（Machine Language）**就是由无数条机器指令按照特定编码规则组成的。指令系统（ISA）规范了每一条指令的二进制机器码格式，因此指令系统正是机器语言的根本基石，两者紧密相关。 B 选项正确：一个处理器硬件设计完成之后，它能够识别并执行的所有机器指令的集合，就是该硬件的指令系统。 C 选项正确：指令系统是软件（编译器、操作系统、应用软件）能向硬件下达命令的最高官方准则，被称为软硬件的基本分界线或接口。 D 选项正确：计算机硬件直接看懂并执行的只有全由 `0` 和 `1` 组成的机器语言。高级语言（C++, Java, Python等）或者汇编语言在运行之前，必须经过编译、汇编或解释器转换为对应的机器指令流，才能上机运行。 题干要求选择错误的一项，故选A。","explanationEn":""},{"id":"coa-ch09-013","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Data transfer between the memory (main memory) and CPU registers must rely on () instructions.","stemCn":"内存（主存）和CPU寄存器之间的数据传输必须依赖（）指令。","options":[{"key":"A","textEn":"Branch (Jump)","textCn":"分支（跳跃）"},{"key":"B","textEn":"Logical","textCn":"逻辑性"},{"key":"C","textEn":"Transfer (Load/Store)","textCn":"传输（加载/存储）"},{"key":"D","textEn":"I/O","textCn":"输入/输出"}],"answerKey":"C","explanationCn":": 在计算机指令集中，用于在主存储器（Memory）和通用寄存器（Registers）之间进行纯粹数据搬运的指令被称为**数据传送类指令**（Data Transfer Instructions）。 在一些架构中（如 RISC / 汇编中），这种操作被具体实现为 `LOAD`（从主存加载到寄存器）和 `STORE`（从寄存器写入主存）指令。故选C。","explanationEn":""},{"id":"coa-ch09-014","chapterId":"ch09","chapterName":"第九章计算机算数","stemEn":"Among machine instructions, the most fundamental and frequently used instructions should be ().","stemCn":"在机器指令中，最基本、最常用的指令应该是（）。","options":[{"key":"A","textEn":"Conversion instructions","textCn":"转换指令"},{"key":"B","textEn":"Data transfer instructions","textCn":"数据传输指令"},{"key":"C","textEn":"Arithmetic operation instructions","textCn":"算术运算指令"},{"key":"D","textEn":"Logical operation instructions","textCn":"逻辑运算指令"}],"answerKey":"B","explanationCn":": 根据计算机程序运行的统计规律，在一套指令系统执行的所有常规指令流中，**数据传送类指令（Data transfer instructions）** 所占的比例是最高的（通常达到 $30\\% \\sim 50\\%$ 以上）。因为无论是做加减法算术运算，还是做逻辑判断，首先都必须把操作数从主存或外部搬运到 CPU 内部的寄存器中，运行完也需要搬回主存。因此，它是最基本、最核心的指令。故选B。","explanationEn":""},{"id":"coa-ch10-001","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"Among the following addressing modes, which mode requires calculation first and then accesses main memory?","stemCn":"下列寻址方式中，哪种方式需要先计算，然后访问主存？","options":[{"key":"A","textEn":"Relative addressing","textCn":"相对寻址"},{"key":"B","textEn":"Indexed addressing","textCn":"索引寻址"},{"key":"C","textEn":"Indirect addressing","textCn":"间接寻址"},{"key":"D","textEn":"A and B","textCn":"A 和 B"}],"answerKey":"D","explanationCn":"相对寻址和变址寻址都需要先根据指令中的形式地址和某个寄存器的内容进行地址计算，然后再访问主存取得操作数。 - 相对寻址： $$ EA = PC + A $$ - 变址寻址： $$ EA = X + A $$ 其中 $EA$ 表示有效地址，$A$ 表示指令中的形式地址，$X$ 表示变址寄存器内容。 间接寻址虽然也需要得到有效地址，但它通常是先访问主存取出有效地址，再根据有效地址访问操作数，不属于“先计算再访问主存”的典型形式。 因此选 D。","explanationEn":""},{"id":"coa-ch10-002","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"In various addressing modes, the address-code field of an instruction may contain which of the following? I. Register address II. I/O device address III. Memory unit address IV. Immediate value","stemCn":"在不同寻址方式下，指令的地址码字段可能包含哪些内容？I. 寄存器地址 II. I/O 设备地址 III. 存储单元地址 IV. 立即数","options":[{"key":"A","textEn":"I and II","textCn":"I、II"},{"key":"B","textEn":"II and III","textCn":"II、III"},{"key":"C","textEn":"I and III","textCn":"I、III"},{"key":"D","textEn":"I, II, III, and IV","textCn":"I、II、III、IV"}],"answerKey":"D","explanationCn":"指令中的地址码字段并不一定只表示主存地址，它的含义取决于寻址方式和指令类型。 可能情况包括： - 寄存器地址：如寄存器寻址； - 外设地址：如 I/O 指令中指定设备端口； - 存储器单元地址：如直接寻址、间接寻址； - 数值本身：如立即数寻址。 所以 I、II、III、IV 都可能出现，选 D。","explanationEn":""},{"id":"coa-ch10-003","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"Suppose a computer has a main memory space of 4 GB, a word length of 32 bits, uses byte addressing, and adopts a 32-bit fixed-length instruction format. If instructions are stored aligned on word boundaries, then the minimum numbers of bits of the Program Counter (PC) and the Instruction Register (IR) are respectively ( ).","stemCn":"假设一台计算机的主存空间为4GB，字长为32位，采用字节寻址，采用32位定长指令格式。如果指令按字边界对齐存储，则程序计数器 (PC) 和指令寄存器 (IR) 的最小位数分别为 ( )。","options":[{"key":"A","textEn":"30, 30","textCn":"30, 30"},{"key":"B","textEn":"30, 32","textCn":"30, 32"},{"key":"C","textEn":"32, 30","textCn":"32, 30"},{"key":"D","textEn":"32, 32","textCn":"32, 32"}],"answerKey":"B","explanationCn":"主存空间为： $$ 4GB = 2^{32}B $$ 如果按字节编址，完整的字节地址需要 32 位。 但是题目说明指令按字边界对齐存放，字长为 32 位，即： $$ 32bit = 4B $$ 所以指令地址一定是 4 的倍数，低 2 位恒为 0，不需要在 PC 中保存。 可存放指令的位置数为： $$ \\frac{2^{32}B}{4B} = 2^{30} $$ 因此 PC 至少需要： $$ 30 $$ 位。 IR 用来保存当前正在执行的指令，题目给出指令长度为 32 位定长，因此 IR 至少需要： $$ 32 $$ 位。 所以答案为： $$ PC = 30,\\quad IR = 32 $$ 选 B。","explanationEn":""},{"id":"coa-ch10-004","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"Suppose the operand of an instruction uses indexed addressing. The value in the index register is `007CH`, the content at address `007CH` is `0124H`, the formal address given in the instruction is `B000H`, and the content at address `B000H` is `C000H`. What is the effective address of the operand?","stemCn":"假设指令的操作数使用索引寻址。变址寄存器中的值为‘007CH’，地址‘007CH’处的内容为‘0124H’，指令中给出的形式地址为‘B000H’，地址‘B000H’处的内容为‘C000H’。操作数的有效地址是多少？","options":[{"key":"A","textEn":"`B124H`","textCn":"`B124H`"},{"key":"B","textEn":"`C124H`","textCn":"`C124H`"},{"key":"C","textEn":"`B07CH`","textCn":"`B07CH`"},{"key":"D","textEn":"`C07CH`","textCn":"`C07CH`"}],"answerKey":"C","explanationCn":"变址寻址的有效地址计算公式为： $$ EA = A + X $$ 其中： - $A$：指令中给出的形式地址； - $X$：变址寄存器中的内容。 题中： $$ A = B000H $$ $$ X = 007CH $$ 所以： $$ EA = B000H + 007CH = B07CH $$ 题目中给出的 `007CH` 地址内容、`B000H` 地址内容都是干扰信息。 因此有效地址为 `B07CH`，选 C。","explanationEn":""},{"id":"coa-ch10-005","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"The function of an unconditional jump instruction using direct addressing is to send the address code in the instruction to ( ).","stemCn":"使用直接寻址的无条件跳转指令的作用是将指令中的地址码发送到( )。","options":[{"key":"A","textEn":"Program Counter PC","textCn":"程序计数器PC"},{"key":"B","textEn":"Accumulator ACC","textCn":"累加器 ACC"},{"key":"C","textEn":"Instruction Register IR","textCn":"指令寄存器IR"},{"key":"D","textEn":"Memory Address Register MAR","textCn":"内存地址寄存器 MAR"}],"answerKey":"A","explanationCn":"转移指令的作用是改变程序执行顺序。 程序下一条指令的地址由程序计数器 PC 保存，因此无条件转移指令执行时，需要把目标地址送入 PC。 即： $$ PC \\leftarrow 目标地址 $$ 这样 CPU 下一次取指时，就会从新的目标地址开始取指。 所以选 A。","explanationEn":""},{"id":"coa-ch10-006","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"In register indirect addressing, the operand is located in ( ).","stemCn":"在寄存器间接寻址中，操作数位于( )中。","options":[{"key":"A","textEn":"General-purpose register","textCn":"通用寄存器"},{"key":"B","textEn":"Main memory unit","textCn":"主存储单元"},{"key":"C","textEn":"Stack","textCn":"堆"},{"key":"D","textEn":"The instruction itself","textCn":"指令本身"}],"answerKey":"B","explanationCn":"寄存器间接寻址中，寄存器中保存的不是操作数本身，而是操作数所在主存单元的地址。 其含义是： $$ EA = (R) $$ $$ Operand = M[EA] $$ 也就是说，寄存器内容是有效地址，真正的操作数在主存中。 所以选 B。","explanationEn":""},{"id":"coa-ch10-007","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"Among the following addressing modes, which is most suitable for accessing a one-dimensional array sequentially according to subscript order?","stemCn":"下列寻址方式中，哪一种最适合按照下标顺序顺序访问一维数组？","options":[{"key":"A","textEn":"Indexed addressing","textCn":"索引寻址"},{"key":"B","textEn":"Register addressing","textCn":"寄存器寻址"},{"key":"C","textEn":"Direct addressing","textCn":"直接寻址"},{"key":"D","textEn":"Relative addressing","textCn":"相对寻址"}],"answerKey":"A","explanationCn":"数组元素通常连续存放在主存中。 访问数组时，可以把数组首地址作为形式地址，把下标或偏移量放入变址寄存器中，通过变址寻址计算元素地址： $$ EA = A + X $$ 其中： - $A$：数组首地址； - $X$：数组下标对应的偏移量。 这样非常适合顺序访问数组元素。 所以选 A。","explanationEn":""},{"id":"coa-ch10-008","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"Which of the following statements about addressing modes is incorrect?","stemCn":"下列关于寻址模式的表述哪一项是不正确的？","options":[{"key":"A","textEn":"Immediate addressing is faster than register addressing.","textCn":"立即寻址比寄存器寻址更快。"},{"key":"B","textEn":"Direct addressing is faster than register addressing.","textCn":"直接寻址比寄存器寻址更快。"},{"key":"C","textEn":"Register indirect addressing is faster than indexed addressing.","textCn":"寄存器间接寻址比索引寻址更快。"},{"key":"D","textEn":"Indexed addressing is faster than indirect addressing.","textCn":"索引寻址比间接寻址更快。"}],"answerKey":"B","explanationCn":"寄存器寻址的操作数直接在 CPU 内部寄存器中，不需要访问主存，因此速度通常很快。 直接寻址需要根据指令中的地址访问主存取得操作数，因此一般慢于寄存器寻址。 所以 B“直接寻址快于寄存器寻址”是错误的。 其他选项可按一般情况理解： - 立即数寻址：操作数就在指令中，取指时已经取得； - 寄存器间接寻址：寄存器给出主存地址，再访问一次主存； - 变址寻址：需要地址加法计算后访问主存； - 间接寻址：通常需要先访问主存得到有效地址，再访问主存取操作数，访问次数更多。 因此本题选 B。","explanationEn":""},{"id":"coa-ch10-009","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"In order to reduce the number of bits of an address field in an instruction, an effective method is to use ( ).","stemCn":"为了减少指令中地址字段的位数，有效的方法是使用( )。","options":[{"key":"A","textEn":"Immediate addressing","textCn":"立即寻址"},{"key":"B","textEn":"Indexed addressing","textCn":"索引寻址"},{"key":"C","textEn":"Register addressing","textCn":"寄存器寻址"},{"key":"D","textEn":"Direct addressing","textCn":"直接寻址"}],"answerKey":"C","explanationCn":"如果指令直接给出主存地址，需要较长的地址字段。 例如主存地址空间很大时，地址码可能需要十几位、几十位。 而寄存器寻址只需要在指令中指出寄存器编号。 如果 CPU 有 $n$ 个寄存器，则寄存器编号只需要： $$ \\log_2 n $$ 位。 例如 16 个寄存器只需要 4 位寄存器编号。 因此，为了缩短指令中某个地址段的位数，常采用寄存器寻址。 所以选 C。","explanationEn":""},{"id":"coa-ch10-010","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"If the address-code part of an instruction gives the address of the effective address of the operand, then the instruction uses ( ).","stemCn":"如果指令的地址代码部分给出了操作数的有效地址的地址，则该指令使用（）。","options":[{"key":"A","textEn":"Direct addressing","textCn":"直接寻址"},{"key":"B","textEn":"Immediate addressing","textCn":"立即寻址"},{"key":"C","textEn":"Register addressing","textCn":"寄存器寻址"},{"key":"D","textEn":"Indirect addressing","textCn":"间接寻址"}],"answerKey":"D","explanationCn":"题干说“地址码部分给出的是操作数有效地址的地址”，也就是说，指令中的地址字段并不是操作数的有效地址，而是保存有效地址的那个主存单元地址。 间接寻址的过程为： $$ EA = M[A] $$ $$ Operand = M[EA] $$ 其中： - $A$：指令中的地址码； - $M[A]$：地址 $A$ 中存放的内容，即有效地址； - $M[EA]$：真正的操作数。 因此该指令采用间接寻址，选 D。","explanationEn":""},{"id":"coa-ch10-011","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"In ( ) addressing mode, the address field in the instruction gives a memory address, and the referenced register contains a positive offset relative to this address. It can be used to implement user access to array elements.","stemCn":"在( )寻址模式下，指令中的地址字段给出了内存地址，所引用的寄存器包含相对于该地址的正偏移量。它可用于实现用户对数组元素的访问。","options":[{"key":"A","textEn":"Indexed addressing","textCn":"索引寻址"},{"key":"B","textEn":"Base-register addressing","textCn":"基址寄存器寻址"},{"key":"C","textEn":"Relative addressing","textCn":"相对寻址"},{"key":"D","textEn":"All of the above","textCn":"上述所有的"}],"answerKey":"A","explanationCn":"题干描述的是变址寻址。 变址寻址中，指令地址字段通常给出一个基准地址，例如数组首地址；变址寄存器中保存相对于该地址的偏移量，例如数组下标偏移。 有效地址为： $$ EA = A + (X) $$ 这种方式非常适合访问数组元素。 例如： $$ EA = 数组首地址 + 下标偏移量 $$ 因此选 A。","explanationEn":""},{"id":"coa-ch10-012","chapterId":"ch10","chapterName":"第十章指令集：特征与功能","stemEn":"Which of the following factors affects the determination of the number of address bits?","stemCn":"以下哪些因素影响地址位数的确定？","options":[{"key":"A","textEn":"The number of operands","textCn":"操作数的数量"},{"key":"B","textEn":"The number of registers in the register set","textCn":"寄存器集中的寄存器数量"},{"key":"C","textEn":"The address range","textCn":"地址范围"},{"key":"D","textEn":"All of the above","textCn":"上述所有的"}],"answerKey":"D","explanationCn":"地址位数的确定受到多种因素影响： 1. **操作数个数** 指令中需要几个地址字段，会影响每个地址字段可分配的位数。 2. **寄存器组个数** 如果采用寄存器寻址，需要用若干位表示寄存器编号。 若有 $n$ 个寄存器，需要： $$ \\log_2 n $$ 位寄存器编号。 3. **地址范围** 如果需要访问更大的主存地址空间，则地址字段需要更多位。 因此 A、B、C 都会影响地址位数的确定，选 D。","explanationEn":""},{"id":"coa-ch11-001","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Which register in the CPU stores the instruction currently being executed?","stemCn":"CPU中哪个寄存器存放当前正在执行的指令？","options":[{"key":"A","textEn":"Instruction Register (IR)","textCn":"指令寄存器（IR）"},{"key":"B","textEn":"Program Counter (PC)","textCn":"程序计数器（PC）"},{"key":"C","textEn":"Accumulator (ACC)","textCn":"累加器（ACC）"},{"key":"D","textEn":"Memory Address Register (MAR)","textCn":"内存地址寄存器 (MAR)"}],"answerKey":"A","explanationCn":"指令寄存器 IR 用来保存当前正在执行的指令。 CPU 从主存中取出指令后，会把指令送入 IR，然后控制器根据 IR 中的操作码和地址码进行译码与执行。 其他寄存器作用： PC：保存下一条将要取出的指令地址； ACC：累加器，用于保存运算结果或中间结果； MAR：保存即将访问的主存地址。 所以选 A。","explanationEn":""},{"id":"coa-ch11-002","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"When a conditional branch instruction is executed, the condition it depends on comes from ( ).","stemCn":"条件分支指令执行时，其所依赖的条件来自( )。","options":[{"key":"A","textEn":"Instruction Register (IR)","textCn":"指令寄存器（IR）"},{"key":"B","textEn":"Flag Register","textCn":"标志寄存器"},{"key":"C","textEn":"Program Counter (PC)","textCn":"程序计数器（PC）"},{"key":"D","textEn":"Memory Address Register (MAR)","textCn":"内存地址寄存器 (MAR)"}],"answerKey":"B","explanationCn":"条件转移指令是否发生转移，通常取决于标志寄存器中的条件标志位。 例如零标志 ZF、进位标志 CF、符号标志 SF、溢出标志 OF 等。 这些标志位通常由前面的算术或逻辑运算结果产生。 例如： CMP R1, R2 JE target JE 是否跳转，取决于比较后零标志位是否为 1。 因此条件来自标志寄存器，选 B。","explanationEn":""},{"id":"coa-ch11-003","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"The CPU does not include ( ).","stemCn":"CPU不包括( )。","options":[{"key":"A","textEn":"Memory Address Register (MAR)","textCn":"内存地址寄存器 (MAR)"},{"key":"B","textEn":"Instruction Register (IR)","textCn":"指令寄存器（IR）"},{"key":"C","textEn":"I/O logic","textCn":"输入/输出逻辑"},{"key":"D","textEn":"Program Counter (PC)","textCn":"程序计数器（PC）"}],"answerKey":"C","explanationCn":"CPU 内部通常包括运算器、控制器和若干寄存器，例如 PC、IR、MAR、MBR、ACC 等。 I/O 逻辑主要属于 I/O 模块或 I/O 控制器的范围，不是 CPU 的基本组成部分。 所以 CPU 中不包括的是 I/O logic，选 C。","explanationEn":""},{"id":"coa-ch11-004","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"The instruction cycle refers to ( ).","stemCn":"指令周期指( )。","options":[{"key":"A","textEn":"The time for the CPU to fetch one instruction from main memory","textCn":"CPU从主存中取出一条指令的时间"},{"key":"B","textEn":"The time for the CPU to execute one instruction","textCn":"CPU执行一条指令的时间"},{"key":"C","textEn":"The time for the CPU to fetch one instruction from main memory plus the time to execute that instruction","textCn":"CPU从主存中取出一条指令的时间加上执行该指令的时间"},{"key":"D","textEn":"The clock cycle time","textCn":"时钟周期时间"}],"answerKey":"C","explanationCn":"指令周期是指 CPU 完成一条指令所需要的全过程时间。 一条指令通常至少包括： 取指：从主存中取出指令； 译码：分析指令功能； 执行：完成运算、访存或转移等操作。 因此，指令周期可以理解为： 指令周期=取指时间+执行时间 更完整地说，还可能包括间址周期、中断周期等。 所以选 C。","explanationEn":""},{"id":"coa-ch11-005","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"The time when the CPU responds to an interrupt is ( ).","stemCn":"CPU响应中断的时间为( )。","options":[{"key":"A","textEn":"After one instruction finishes execution","textCn":"一条指令执行完毕后"},{"key":"B","textEn":"When an I/O device raises an interrupt","textCn":"当 I/O 设备发出中断时"},{"key":"C","textEn":"At the end of the fetch cycle","textCn":"在获取周期结束时"},{"key":"D","textEn":"At the end of the instruction cycle","textCn":"在指令周期结束时"}],"answerKey":"A","explanationCn":"CPU 通常在一条指令执行结束后才响应中断。 这是因为如果在一条指令执行到一半时响应中断，可能导致指令执行状态不完整，难以恢复现场。 一般过程是： 当前指令执行结束； CPU 检查是否有中断请求； 若允许中断，则保存断点和现场； 转入中断服务程序。 因此选 A。","explanationEn":""},{"id":"coa-ch11-006","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Which of the following does not cause a pipeline stall?","stemCn":"下列哪一项不会导致流水线停顿？","options":[{"key":"A","textEn":"Data forwarding","textCn":"数据转发"},{"key":"B","textEn":"Data hazard","textCn":"数据冒险"},{"key":"C","textEn":"Branch instruction","textCn":"分支指令"},{"key":"D","textEn":"Resource conflict","textCn":"资源冲突"}],"answerKey":"A","explanationCn":"流水线停顿通常由以下因素引起： 数据相关：后一条指令需要前一条指令的结果； 控制相关：例如分支指令导致下一条指令地址不确定； 结构相关：多个阶段争用同一硬件资源。 数据旁路，也叫数据转发，是一种解决数据相关、减少流水线停顿的技术。 它把前面指令刚产生但尚未写回寄存器的结果，直接转发给后续指令使用。 因此数据旁路不会引起流水线停顿，反而用于减少停顿，选 A。","explanationEn":""},{"id":"coa-ch11-007","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Suppose an instruction is completed by three subcomponents: fetch, decode/analyze, and execute, and each subcomponent takes $\\Delta t$. If an ordinary scalar pipeline processor is used, and no hazards are considered, then the total time required to execute 11 consecutive instructions is ( ).","stemCn":"假设一条指令经过取指、译码和执行三个流水段，每段耗时 $\\Delta t$。采用普通标量流水线且不考虑流水线冒险时，执行连续 11 条指令共需多少时间？（ ）","options":[{"key":"A","textEn":"$12\\Delta t$","textCn":"$12\\Delta t$"},{"key":"B","textEn":"$13\\Delta t$","textCn":"$13\\Delta t$"},{"key":"C","textEn":"$16\\Delta t$","textCn":"$16\\Delta t$"},{"key":"D","textEn":"$17\\Delta t$","textCn":"$17\\Delta t$"}],"answerKey":"B","explanationCn":"流水线共有 3 个阶段： k=3 连续执行 11 条指令： n=11 当各段时间均为 $\\Delta t$，且不考虑冲突时，流水线执行时间公式为： T=(k+n−1)Δt 代入： T=(3+11−1)Δt=13Δt 所以选 B。","explanationEn":""},{"id":"coa-ch11-008","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"In a pipeline processor, what type of dependency occurs in the following instruction sequence? ADD R1, R2, R3 ; R2 + R3 -> R1 ADD R4, R1, R5 ; R1 + R5 -> R4","stemCn":"在流水线处理器中，下列指令序列存在何种相关？ADD R1, R2, R3；R2 + R3 -> R1。ADD R4, R1, R5；R1 + R5 -> R4。","options":[{"key":"A","textEn":"Write-after-write dependency","textCn":"写后写相关（WAW）"},{"key":"B","textEn":"Read-after-write dependency","textCn":"写后读相关（RAW）"},{"key":"C","textEn":"Write-after-read dependency","textCn":"读后写相关（WAR）"},{"key":"D","textEn":"Procedural dependency","textCn":"控制相关"}],"answerKey":"B","explanationCn":"第 1 条指令会把结果写入 R1： R1←R2+R3 第 2 条指令需要读取 R1： R4←R1+R5 也就是说，第 2 条指令必须等第 1 条指令把 R1 写好之后才能正确读取 R1。 这是典型的 RAW（Read After Write，先写后读相关），也称真正的数据相关。 所以选 B。","explanationEn":""},{"id":"coa-ch11-009","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"A computer contains the Program Counter (PC), Instruction Register (IR), Memory Buffer Register (MBR), and Memory Address Register (MAR). If the CPU is going to execute the instruction MOV R0, #100, which transfers the value 100 to register R0, what is the first operation the CPU should complete?","stemCn":"计算机包含程序计数器（PC）、指令寄存器（IR）、内存缓冲寄存器（MBR）和内存地址寄存器（MAR）。如果CPU要执行指令MOV R0,#100，将值100传送到寄存器R0，CPU应该完成的第一个操作是什么？","options":[{"key":"A","textEn":"100 -> R0","textCn":"100 -> R0"},{"key":"B","textEn":"100 -> MBR","textCn":"100 -> MBR"},{"key":"C","textEn":"PC -> IR","textCn":"PC -> IR"},{"key":"D","textEn":"PC -> MAR","textCn":"PC -> MAR"}],"answerKey":"D","explanationCn":"CPU 执行任何指令前，首先都要完成取指过程。 取指时，CPU 需要先把 PC 中保存的指令地址送入 MAR，用于访问主存。 第一步是： MAR←PC 然后才会进行主存读操作，把指令取入 MBR，再送入 IR。 因此 CPU 首先要完成的操作是 PC -> MAR，选 D。","explanationEn":""},{"id":"coa-ch11-010","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Which of the following instruction groups contains a write-after-read dependency?","stemCn":"以下哪个指令组包含读后写依赖性？","options":[{"key":"A","textEn":"I1: SUB R1, R2, R3 ; R2 - R3 -> R1 I2: ADD R4, R5, R1 ; R5 + R1 -> R4","textCn":"I1: SUB R1, R2, R3；R2 - R3 -> R1。I2: ADD R4, R5, R1；R5 + R1 -> R4"},{"key":"B","textEn":"I1: STA M, R2      ; R2 -> M I2: ADD R2, R4, R5 ; R4 + R5 -> R2","textCn":"I1: STA M, R2；R2 -> M。I2: ADD R2, R4, R5；R4 + R5 -> R2"},{"key":"C","textEn":"I1: MUL R3, R2, R1 ; R2 × R1 -> R3 I2: SUB R3, R4, R5 ; R4 - R5 -> R3","textCn":"I1: MUL R3, R2, R1；R2 × R1 -> R3。I2: SUB R3, R4, R5；R4 - R5 -> R3"},{"key":"D","textEn":"None of the above","textCn":"以上都不是"}],"answerKey":"B","explanationCn":"先读后写相关，即 WAR（Write After Read），指后一条指令要写入的寄存器，前一条指令还需要先读取它。 如果后一条指令过早写入，就会破坏前一条指令应读取的旧值。 分析 B： I1: STA M, R2 ; R2 -> M I2: ADD R2, R4, R5 ; R4 + R5 -> R2 I1 需要读取 R2，把 R2 的内容存入主存 M。 I2 需要写 R2，把 R4+R5 的结果写入 R2。 因此必须保证 I1 先读 R2，I2 再写 R2，否则 I1 读到的就不是原来的 R2 内容。 所以 B 存在 WAR 相关。 其他选项： A：I1 写 R1，I2 读 R1，是 RAW 相关； C：I1 写 R3，I2 也写 R3，是 WAW 相关； D 错误。","explanationEn":""},{"id":"coa-ch11-011","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"When a conflict occurs in accessing the address of an operand, a ( ) dependency will occur.","stemCn":"当访问操作数地址时发生冲突时，就会产生( )依赖。","options":[{"key":"A","textEn":"Resource dependency","textCn":"资源依赖"},{"key":"B","textEn":"Data dependency","textCn":"数据依赖"},{"key":"C","textEn":"Structural dependency","textCn":"结构依赖性"},{"key":"D","textEn":"Control dependency","textCn":"控制依赖性"}],"answerKey":"B","explanationCn":"如果多条指令对同一个操作数地址进行访问，并且这些访问之间存在先后顺序要求，就会产生数据相关。 数据相关本质上是指指令之间因为读写同一数据对象而产生依赖关系。 常见的数据相关包括： - RAW：Read After Write，先写后读相关； - WAR：Write After Read，先读后写相关； - WAW：Write After Write，先写后写相关。 题干说“对一个操作数地址的访问发生冲突”，本质上是对同一数据或同一数据地址的访问产生冲突，因此属于 **data dependency**，选 B。","explanationEn":""},{"id":"coa-ch11-012","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Generally speaking, in the ( ) stage of a pipeline, ALU operations, Cache access, and register value updates are performed.","stemCn":"一般来说，在流水线的( )阶段，执行ALU操作、Cache访问和寄存器值更新。","options":[{"key":"A","textEn":"Decode","textCn":"解码"},{"key":"B","textEn":"Fetch","textCn":"取指"},{"key":"C","textEn":"Write-back","textCn":"回写"},{"key":"D","textEn":"Execute","textCn":"执行"}],"answerKey":"D","explanationCn":"在流水线中，取指阶段主要负责从存储器中取出指令，译码阶段主要分析指令功能和读取相关信息，写回阶段主要把结果写回寄存器。 而执行阶段是完成指令实际功能的核心阶段，通常包括算术逻辑运算、访存相关操作以及结果更新等实际执行动作。 需要注意：如果采用更细分的五级流水线，Cache 访问通常会被单独划分到访存阶段，寄存器更新也可能放在写回阶段。 但本题按“广义执行阶段”理解，即真正完成指令功能的阶段，因此选择 **execute**。","explanationEn":""},{"id":"coa-ch12-001","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Which of the following is not a main characteristic of RISC machines?","stemCn":"以下哪项不是 RISC 机器的主要特征？","options":[{"key":"A","textEn":"They all have a limited and simple instruction set.","textCn":"它们都有有限且简单的指令集。"},{"key":"B","textEn":"They use a large number of registers or optimize register usage through the compiler.","textCn":"他们使用大量的寄存器或者通过编译器优化寄存器的使用。"},{"key":"C","textEn":"They emphasize optimization of the instruction pipeline.","textCn":"它们强调优化指令流水线。"},{"key":"D","textEn":"The Cache capacity of RISC machines is relatively small.","textCn":"RISC机器的Cache容量相对较小。"}],"answerKey":"D","explanationCn":"RISC 的主要特点包括： - 指令系统精简，指令数量较少； - 指令格式规整，寻址方式较少； - 大多数指令可以在一个时钟周期内完成； - 大量使用寄存器，减少访存次数； - 强调编译优化； - 适合流水线执行。 而 Cache 容量是否较小并不是 RISC 的主要特征。 RISC 机同样需要 Cache 来解决 CPU 与主存速度不匹配的问题，Cache 容量大小取决于具体处理器设计，而不是 RISC 的本质特征。 所以选 D。","explanationEn":""},{"id":"coa-ch12-002","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Which of the following statements about instruction execution characteristics is incorrect?","stemCn":"下列关于指令执行特性的表述哪一项是不正确的？","options":[{"key":"A","textEn":"Branch statements are used at a low frequency in high-level language programs.","textCn":"分支语句在高级语言程序中使用频率较低。"},{"key":"B","textEn":"Procedure calls and returns are among the most time-consuming operations in typical high-level language programs.","textCn":"过程调用和返回是典型高级语言程序中最耗时的操作之一。"},{"key":"C","textEn":"Scalar variables are accessed frequently in high-level language programs.","textCn":"标量变量在高级语言程序中被频繁访问。"},{"key":"D","textEn":"Assignment statements occur with the highest frequency.","textCn":"赋值语句出现的频率最高。"}],"answerKey":"A","explanationCn":"RISC 设计的重要依据之一是对高级语言程序运行特征的统计分析。 一般来说，高级语言程序中赋值语句出现频率很高，标量变量访问也很频繁；过程调用和返回虽然出现频率不一定最高，但往往开销较大。 分支语句并不是低频操作。条件判断、循环控制、函数调用返回等都会引起控制流变化，因此转移类操作在程序中并不少见。 所以 A“高级语言程序中判断语句使用频率较低”是不正确的。","explanationEn":""},{"id":"coa-ch12-003","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Which of the following statements about RISC is correct?","stemCn":"以下关于 RISC 的哪些表述是正确的？","options":[{"key":"A","textEn":"A machine using pipeline technology must be a RISC machine.","textCn":"使用流水线技术的机器一定是RISC机器。"},{"key":"B","textEn":"A RISC machine generally has a compiler with relatively powerful functions.","textCn":"RISC机器一般都有一个功能比较强大的编译器。"},{"key":"C","textEn":"In a RISC machine, all global variables should be placed in registers.","textCn":"在RISC机器中，所有全局变量都应该放在寄存器中。"},{"key":"D","textEn":"A RISC machine must have a large number of physical registers.","textCn":"RISC机器必须有大量的物理寄存器。"}],"answerKey":"B","explanationCn":"RISC 体系结构非常依赖编译器优化。 由于 RISC 指令简单，很多复杂操作需要由编译器用多条简单指令组合实现，因此编译器需要承担更多优化任务，例如寄存器分配、指令调度、流水线相关优化等。 所以 B 正确。 其他选项分析： - A 错误：采用流水线技术的机器不一定是 RISC，CISC 处理器也可以使用流水线。 - C 错误：全局变量不可能全部放入寄存器，寄存器资源有限，而且全局变量可能需要长期保存在内存中。 - D 错误：RISC 通常倾向于使用较多寄存器，但“必须有大量物理寄存器”说法过于绝对。 因此选 B。","explanationEn":""},{"id":"coa-ch12-004","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"A register set with $N$ windows can contain variables of at most ( ) processes at the same time.","stemCn":"$N$ 个窗口的寄存器组最多可以同时包含 ( ) 个进程的变量。","options":[{"key":"A","textEn":"$N$","textCn":"$N$"},{"key":"B","textEn":"$N+1$","textCn":"$N+1$"},{"key":"C","textEn":"$N-1$","textCn":"$N-1$"},{"key":"D","textEn":"$2N$","textCn":"$2N$"}],"answerKey":"C","explanationCn":"RISC 中的寄存器窗口常用于加快过程调用和返回。 相邻过程的寄存器窗口之间通常会有一部分重叠区域，用来传递参数和返回值。 由于寄存器窗口之间存在重叠，并且还需要为当前过程和调用关系保留窗口，因此一个 $N$ 窗口的寄存器组通常最多只能同时容纳： $$ N-1 $$ 个过程的变量。 所以选 C。","explanationEn":""},{"id":"coa-ch12-005","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Which of the following statements about RISC is incorrect?","stemCn":"以下关于 RISC 的描述哪一项是不正确的？","options":[{"key":"A","textEn":"RISC generally adopts a microprogrammed controller.","textCn":"RISC一般采用微程序控制器。"},{"key":"B","textEn":"Most RISC instructions are completed within one clock cycle.","textCn":"大多数 RISC 指令在一个时钟周期内完成。"},{"key":"C","textEn":"RISC has fewer instructions and fewer instruction classes than CISC.","textCn":"RISC 的指令数量和指令类别都比 CISC 少。"},{"key":"D","textEn":"RISC has fewer addressing modes than CISC.","textCn":"RISC 的寻址模式比 CISC 少。"}],"answerKey":"A","explanationCn":"RISC 为了提高执行速度，通常采用**硬布线控制器**，而不是微程序控制器。 硬布线控制速度快，适合简单、规整的 RISC 指令系统。 微程序控制器更常见于复杂指令系统计算机 CISC，因为 CISC 指令复杂，用微程序实现控制逻辑更灵活。 其他选项都是 RISC 的典型特点： - 大多数指令尽量在一个时钟周期完成； - 指令数量和指令种类比 CISC 少； - 寻址方式比 CISC 少。 所以错误的是 A。","explanationEn":""},{"id":"coa-ch12-006","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"The instruction position after a branch instruction is called a ( ).","stemCn":"分支指令之后的指令位置称为( )。","options":[{"key":"A","textEn":"Delayed load","textCn":"延迟加载"},{"key":"B","textEn":"Delayed file","textCn":"延迟文件"},{"key":"C","textEn":"Delay slot","textCn":"延迟槽"},{"key":"D","textEn":"Delayed register","textCn":"延迟寄存器"}],"answerKey":"C","explanationCn":"在某些流水线处理器中，转移指令执行后，转移目标地址并不能立即生效。 为了充分利用这段延迟时间，处理器会规定转移指令后面的一个或多个指令位置仍然会被执行，这些位置称为**延迟槽**。 延迟槽常用于减少分支带来的流水线停顿。 编译器可以尝试把对程序结果没有影响的有用指令放入延迟槽中执行，从而提高流水线效率。 所以选 C。","explanationEn":""},{"id":"coa-ch13-001","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Which of the following statements about superscalar processing is incorrect?","stemCn":"以下关于超标量处理的表述哪一项是不正确的？","options":[{"key":"A","textEn":"A superscalar processor can start multiple pipelines at the same time.","textCn":"超标量处理器可以同时启动多条流水线。"},{"key":"B","textEn":"Superscalar processing can only be used in RISC machines.","textCn":"超标量处理只能在 RISC 机器中使用。"},{"key":"C","textEn":"Instructions in a superscalar processor can be executed in parallel.","textCn":"超标量处理器中的指令可以并行执行。"},{"key":"D","textEn":"Superscalar processing allows instructions to be executed in an order different from the program order.","textCn":"超标量处理允许指令以不同于程序顺序的顺序执行。"}],"answerKey":"B","explanationCn":"超标量技术并不是 RISC 机器专有的。 RISC 指令格式规整、指令简单，确实更适合实现超标量和流水线优化；但 CISC 处理器也可以通过内部译码，把复杂指令转换为较简单的微操作，再采用超标量方式执行。 因此“超标量只能用于 RISC 机”说法错误。 其他选项体现了超标量的常见特点： 超标量处理器通常具有多个功能部件或多条流水线，可以在同一时钟周期发射多条指令；为了提高并行度，也可能采用乱序执行。","explanationEn":""},{"id":"coa-ch13-002","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Which of the following statements about the instruction window is incorrect?","stemCn":"下列关于指令窗口的描述哪一项是不正确的？","options":[{"key":"A","textEn":"The instruction window is an additional pipeline stage.","textCn":"指令窗口是一个附加的流水线阶段。"},{"key":"B","textEn":"The instruction window is a method that uses a certain delay to allow independent instructions to execute earlier.","textCn":"指令窗口是一种利用一定的延迟来让独立指令先执行的方法。"},{"key":"C","textEn":"The use of an instruction window can reduce pipeline stall time to some extent.","textCn":"指令窗口的使用可以在一定程度上减少流水线停顿时间。"},{"key":"D","textEn":"Before the instruction window is full, the CPU can keep fetching and decoding instructions.","textCn":"在指令窗口满之前，CPU可以继续取指和译码指令。"}],"answerKey":"A","explanationCn":"指令窗口不是简单增加的一个流水段，而是用于保存已经取指、译码但尚未发射执行的指令的缓冲结构。 处理器可以在指令窗口中检查指令之间的相关关系、操作数是否就绪、功能部件是否空闲，然后选择满足条件的指令发射执行。 指令窗口的作用主要是支持动态调度和乱序执行，从而减少流水线停顿。 所以 A“指令窗口是一个附加的流水段”不正确。","explanationEn":""},{"id":"coa-ch13-003","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Which of the following issue strategies is not included in superscalar instruction issue strategies?","stemCn":"下列哪一项不属于超标量处理器的指令发射策略？","options":[{"key":"A","textEn":"In-order issue and in-order completion","textCn":"顺序发射、顺序完成"},{"key":"B","textEn":"In-order issue and out-of-order completion","textCn":"顺序发射、乱序完成"},{"key":"C","textEn":"Out-of-order issue and in-order completion","textCn":"乱序发射、顺序完成"},{"key":"D","textEn":"Out-of-order issue and out-of-order completion","textCn":"乱序发射、乱序完成"}],"answerKey":"C","explanationCn":"超标量处理器中常见的指令发射和完成策略包括： 1. **In-order issue, in-order completion** 按程序顺序发射，按程序顺序完成，实现简单，但并行性较低。 2. **In-order issue, out-of-order completion** 按程序顺序发射，但不同指令执行时间不同，因此可以乱序完成。 3. **Out-of-order issue, out-of-order completion** 指令进入指令窗口后，根据操作数和资源是否就绪来乱序发射，并可能乱序完成，能提高并行性。 而“乱序发射、顺序完成”不是超标量中通常列出的主要发射策略。 因此选 C。","explanationEn":""},{"id":"coa-ch13-004","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"For superscalar processors, the instruction window technology cannot solve the problem of ( ).","stemCn":"对于超标量处理器，指令窗口技术无法解决（ ）的问题。","options":[{"key":"A","textEn":"Procedural dependency","textCn":"程序依赖性"},{"key":"B","textEn":"True data dependency","textCn":"真实的数据依赖"},{"key":"C","textEn":"Resource conflict","textCn":"资源冲突"},{"key":"D","textEn":"Output dependency","textCn":"输出依赖性"}],"answerKey":"D","explanationCn":"指令窗口主要用于动态调度。它可以暂存多条指令，并选择已经满足执行条件的指令先执行，从而缓解由于等待、资源安排等造成的流水线停顿。 但是**输出相关**，即 WAW（Write After Write），本质上是两个指令要写同一个逻辑寄存器，要求最终写入顺序不能出错。 例如： I1: R1 <- ... I2: R1 <- ... 如果 I2 先写 R1，I1 后写 R1，就会破坏最终结果。 这种问题通常要靠寄存器重命名来解决，而不是单靠指令窗口解决。 因此选 D。","explanationEn":""},{"id":"coa-ch13-005","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"For superscalar processors, register renaming technology can solve the problem of ( ).","stemCn":"对于超标量处理器，寄存器重命名技术可以解决( )的问题。","options":[{"key":"A","textEn":"Procedural dependency","textCn":"程序依赖性"},{"key":"B","textEn":"Anti-dependency","textCn":"反依赖"},{"key":"C","textEn":"Resource conflict","textCn":"资源冲突"},{"key":"D","textEn":"True data dependency","textCn":"真实的数据依赖"}],"answerKey":"B","explanationCn":"寄存器重命名的主要作用是消除由于使用同一个寄存器名字而产生的假相关。 反相关，即 WAR（Write After Read），表示后一条指令要写某寄存器，而前一条指令还需要读这个寄存器的旧值。 例如： I1: R3 <- R1 + R2 ; 需要先读 R1 I2: R1 <- R4 + R5 ; 后面要写 R1 如果 I2 提前写 R1，就会破坏 I1 应该读取的旧 R1 值。 通过寄存器重命名，可以让 I2 写入另一个物理寄存器，从而消除这种反相关。 注意： 寄存器重命名不能消除真正的数据相关 RAW，因为后一条指令确实需要前一条指令产生的数据。 所以选 B。","explanationEn":""},{"id":"coa-ch13-006","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Which of the following hardware techniques are used by superscalar processors to improve performance?","stemCn":"超标量处理器使用以下哪些硬件技术来提高性能？","options":[{"key":"A","textEn":"Resource duplication","textCn":"资源复制"},{"key":"B","textEn":"Out-of-order issue","textCn":"乱序发射"},{"key":"C","textEn":"Register renaming","textCn":"寄存器重命名"},{"key":"D","textEn":"All of the above","textCn":"上述所有的"}],"answerKey":"D","explanationCn":"超标量处理器为了在一个时钟周期内发射并执行多条指令，需要多种硬件技术配合。 Resource duplication（资源复制）：增加多个功能部件，例如多个 ALU，使多条指令能够并行执行。 Out-of-order issue（乱序发射）：让已经准备好的指令先执行，不必严格等待前面的阻塞指令。 Register renaming（寄存器重命名）：消除 WAR、WAW 等假相关，提高乱序执行的安全性和并行度。 因此 A、B、C 都是超标量处理器常用的性能提升技术，选 D。","explanationEn":""},{"id":"coa-ch14-001","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"In a single-bus CPU, which of the following is correct?","stemCn":"在单总线 CPU 中，以下哪项是正确的？","options":[{"key":"A","textEn":"The ALU has only one input connected to the bus, while the other input must be connected to the bus through a register.","textCn":"ALU 只有一个输入连接到总线，而另一输入必须通过寄存器连接到总线。"},{"key":"B","textEn":"Both input ports of the ALU are connected to the bus, but the output port must be connected to the bus through a register.","textCn":"ALU 的两个输入端口都连接到总线，但输出端口必须通过寄存器连接到总线。"},{"key":"C","textEn":"One input port of the ALU is connected to the bus, and its output port can also be connected to the bus.","textCn":"ALU的一个输入端口连接到总线，其输出端口也可以连接到总线。"},{"key":"D","textEn":"Both input ports and the output port of the ALU can be connected to the bus.","textCn":"ALU 的输入端口和输出端口都可以连接到总线。"}],"answerKey":"A","explanationCn":"在单总线结构中，同一时刻总线上通常只能传送一个数据。如果 ALU 的两个输入端都直接连接到同一条总线，那么同一时刻无法同时从总线上取得两个操作数。 因此常见做法是： 一个操作数可以直接来自总线； 另一个操作数需要先送入暂存寄存器，再作为 ALU 的另一个输入。 所以正确答案是 A。","explanationEn":""},{"id":"coa-ch14-002","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"Compared with a datapath that does not use an internal CPU bus, a datapath that uses an internal CPU bus has which of the following characteristics?","stemCn":"与不使用内部CPU总线的数据路径相比，使用内部CPU总线的数据路径具有以下哪些特征？","options":[{"key":"A","textEn":"The former has higher performance.","textCn":"前者性能更高。"},{"key":"B","textEn":"The latter has more serious data conflict problems.","textCn":"后者存在更严重的数据冲突问题。"},{"key":"C","textEn":"The former has a large amount of hardware and is difficult to implement.","textCn":"前者硬件量大，实现难度大。"},{"key":"D","textEn":"None of the above statements is correct.","textCn":"上述说法均不正确。"}],"answerKey":"D","explanationCn":"采用 CPU 内部总线的数据通路可以减少部件之间的直接连线，使硬件结构更简单，但由于多个部件共享总线，可能会限制并行传送能力。 不采用内部总线的数据通路往往需要更多专用连线，硬件复杂度更高，但可能具有更好的并行性。 选项 A、B、C 的说法都不准确或表述混乱，因此选择 D。","explanationEn":""},{"id":"coa-ch14-003","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"The function of the CPU read/write control signal is to determine which of the following?","stemCn":"CPU读/写控制信号的作用是确定下列哪项？","options":[{"key":"A","textEn":"The direction of data flow on the data bus.","textCn":"数据总线上数据流的方向。"},{"key":"B","textEn":"The read/write type of memory operation.","textCn":"内存操作的读/写类型。"},{"key":"C","textEn":"The direction in which information flows into or out of memory.","textCn":"信息流入或流出内存的方向。"},{"key":"D","textEn":"All of the above.","textCn":"上述所有的。"}],"answerKey":"D","explanationCn":"CPU 的读/写控制信号用于说明当前总线操作是读操作还是写操作。 如果是读操作，数据通常从存储器或 I/O 设备流向 CPU； 如果是写操作，数据通常从 CPU 流向存储器或 I/O 设备。 因此它既决定数据总线上的数据流向，也决定存储器操作类型，还决定信息是流入还是流出存储器，所以选 D。","explanationEn":""},{"id":"coa-ch14-004","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"In a controller implemented by combinational logic, the formation of micro-operation control signals is related to which of the following?","stemCn":"在组合逻辑实现的控制器中，微操作控制信号的形成与以下哪项有关？","options":[{"key":"A","textEn":"Instruction opcode and address code.","textCn":"指令操作码和地址码。"},{"key":"B","textEn":"Instruction opcode signal, timing, and flags.","textCn":"指令操作码信号、时序和标志。"},{"key":"C","textEn":"Opcode and condition code.","textCn":"操作码和条件码。"},{"key":"D","textEn":"Status information and conditions.","textCn":"状态信息和条件。"}],"answerKey":"B","explanationCn":"组合逻辑控制器又称硬布线控制器，其控制信号通常由以下信息共同决定： 指令操作码：决定当前是什么指令； 时序信号：决定当前处于哪个节拍或周期； 状态标志：决定是否满足某些条件，例如是否溢出、是否为零、是否有中断等。 因此微操作控制信号的形成与“指令译码信号、时钟/时序信号和标志”有关，答案选 B。","explanationEn":""},{"id":"coa-ch14-005","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"Compared with a microprogrammed controller, the characteristic of a hardwired controller is which of the following?","stemCn":"与微程序控制器相比，硬连线控制器的特点是以下哪一项？","options":[{"key":"A","textEn":"Instruction execution speed is fast, and instruction functions are easy to modify and extend.","textCn":"指令执行速度快，指令功能易于修改和扩展。"},{"key":"B","textEn":"Instruction execution speed is fast, but instruction functions are difficult to modify and extend.","textCn":"指令执行速度快，但指令功能难以修改和扩展。"},{"key":"C","textEn":"Instruction execution speed is slow, and instruction functions are easy to modify and extend.","textCn":"指令执行速度慢，指令功能易于修改和扩展。"},{"key":"D","textEn":"Instruction execution speed is slow, and instruction functions are difficult to modify and extend.","textCn":"指令执行速度慢，指令功能难以修改和扩展。"}],"answerKey":"B","explanationCn":"硬布线控制器用组合逻辑电路直接产生控制信号，不需要逐条读取微指令，因此执行速度较快。 但是它的控制逻辑固定在硬件电路中，如果要修改或扩展指令功能，就需要改动硬件设计，因此修改和扩展比较困难。 微程序控制器则相反：速度相对较慢，但通过修改微程序可以比较方便地扩展或修改控制功能。 所以答案选 B。","explanationEn":""},{"id":"coa-ch14-006","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"The purpose of the indirect cycle is to do which of the following?","stemCn":"间接循环的目的是执行以下哪项操作？","options":[{"key":"A","textEn":"Fetch the effective address of the operand.","textCn":"获取操作数的有效地址。"},{"key":"B","textEn":"Fetch the operand.","textCn":"获取操作数。"},{"key":"C","textEn":"Fetch the instruction address.","textCn":"获取指令地址。"},{"key":"D","textEn":"Fetch the instruction.","textCn":"获取指令。"}],"answerKey":"A","explanationCn":"间址周期出现在间接寻址方式中。 指令中的地址字段并不是操作数的真实地址，而是存放操作数地址的地址。 例如： Instruction address field = A Memory[A] = EA Memory[EA] = Operand 间址周期的作用就是根据指令地址字段 A，从存储器中取出真正的操作数地址 EA，也就是有效地址。 所以答案选 A。","explanationEn":""},{"id":"coa-ch14-007","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"After the interrupt cycle, the program counter PC points to which of the following?","stemCn":"中断周期后，程序计数器PC指向以下哪一个？","options":[{"key":"A","textEn":"The address of the data to be processed.","textCn":"要处理的数据的地址。"},{"key":"B","textEn":"The address of the user instruction to return to after the interrupt.","textCn":"中断后返回的用户指令的地址。"},{"key":"C","textEn":"The first address of the interrupt service routine.","textCn":"中断服务程序的首地址。"},{"key":"D","textEn":"None of the above.","textCn":"以上都不是。"}],"answerKey":"C","explanationCn":"中断周期的主要任务包括： 保存断点，也就是保存原程序下一条要执行的指令地址； 根据中断类型找到中断服务程序入口地址； 将中断服务程序入口地址送入 PC。 因此中断周期结束后，PC 指向的是中断服务程序的首地址，CPU 接下来会去执行中断服务程序。 所以答案选 C。","explanationEn":""},{"id":"coa-ch14-008","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"Which of the following statements is correct?","stemCn":"下列说法是正确的？","options":[{"key":"A","textEn":"The execution cycle of an addition instruction must access memory.","textCn":"加法指令的执行周期必须访问内存。"},{"key":"B","textEn":"The execution cycle of an addition instruction must not access memory.","textCn":"加法指令的执行周期不得访问存储器。"},{"key":"C","textEn":"If the address code of an addition instruction gives a memory address, then this instruction must access memory during the execution cycle.","textCn":"如果加法指令的地址码给出了内存地址，则该指令必须在执行周期内访问内存。"},{"key":"D","textEn":"If the address code of an addition instruction gives a memory address, then this instruction does not need to access memory during the execution cycle.","textCn":"如果加法指令的地址码给出了内存地址，则该指令在执行周期内不需要访问内存。"}],"answerKey":"C","explanationCn":"加法指令是否需要在执行周期访问存储器，取决于操作数的位置。 如果操作数在寄存器中，例如： ADD R1, R2 执行周期可以只在 CPU 内部完成，不一定访存。 但如果指令地址码给出的是存储器地址，例如： ADD A 则需要从存储器地址 A 中取出操作数，再进行加法运算，因此执行周期一定要访存。 所以答案选 C。","explanationEn":""},{"id":"coa-ch14-009","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"After the indirect cycle, what is stored in the memory buffer register MBR?","stemCn":"间接循环结束后，内存缓冲寄存器MBR中存储了什么？","options":[{"key":"A","textEn":"The address of the operand.","textCn":"操作数的地址。"},{"key":"B","textEn":"The operand.","textCn":"操作数。"},{"key":"C","textEn":"The instruction.","textCn":"指令。"},{"key":"D","textEn":"The instruction address.","textCn":"指令地址。"}],"answerKey":"A","explanationCn":"间址周期的作用是取得操作数的有效地址，而不是取得操作数本身。 典型过程可以理解为： Ad(IR) -> MAR M(MAR) -> MBR MBR -> address field of IR 其中 M(MAR) 读出的内容是操作数的有效地址，所以 MBR 中保存的是操作数的地址。 因此答案选 A。","explanationEn":""},{"id":"coa-ch14-010","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"After the fetch cycle, what is stored in the memory address register MAR?","stemCn":"取指周期结束后，存储器地址寄存器MAR中存储了什么？","options":[{"key":"A","textEn":"The address of the operand.","textCn":"操作数的地址。"},{"key":"B","textEn":"The operand.","textCn":"操作数。"},{"key":"C","textEn":"The instruction.","textCn":"指令。"},{"key":"D","textEn":"The instruction address.","textCn":"指令地址。"}],"answerKey":"D","explanationCn":"取指周期的基本过程通常是： PC -> MAR M(MAR) -> MDR/MBR MDR/MBR -> IR PC + 1 -> PC MAR 的作用是保存当前要访问的存储单元地址。 在取指周期中，CPU 要访问的是“指令所在的存储单元”，所以 MAR 中保存的是指令地址。 因此答案选 D。","explanationEn":""},{"id":"coa-ch15-001","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"In a microprogrammed control unit, which field can form the microprogram entry address?","stemCn":"在微程序控制单元中，哪个字段可以构成微程序入口地址？","options":[{"key":"A","textEn":"Address code field of machine instruction","textCn":"机器指令的地址码字段"},{"key":"B","textEn":"Microaddress field of microinstruction","textCn":"微指令的微地址域"},{"key":"C","textEn":"Operation code field of machine instruction","textCn":"机器指令操作码字段"},{"key":"D","textEn":"Micro-operation code field of microinstruction","textCn":"微指令微操作码域"}],"answerKey":"C","explanationCn":"微程序入口地址通常由机器指令的操作码字段决定，用于在控制存储器中选择对应的微程序起始位置。","explanationEn":""},{"id":"coa-ch15-002","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"The control storage in a microprogrammed control unit belongs to which part?","stemCn":"微程序控制单元中的控制存储器属于哪一部分？","options":[{"key":"A","textEn":"Main memory","textCn":"主存储器"},{"key":"B","textEn":"Secondary storage","textCn":"辅助存储器"},{"key":"C","textEn":"Cache","textCn":"缓存"},{"key":"D","textEn":"CPU","textCn":"CPU（中央处理器）"}],"answerKey":"D","explanationCn":"控制存储器属于CPU内部的一部分，用于存储微指令，因此正确选项为 CPU。","explanationEn":""},{"id":"coa-ch15-003","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"In a microprogrammed control unit, the relationship between machine instructions and microinstructions is:","stemCn":"在微程序控制单元中，机器指令和微指令之间的关系为：","options":[{"key":"A","textEn":"Each machine instruction is executed by one microinstruction","textCn":"每条机器指令由一条微指令执行"},{"key":"B","textEn":"Each machine instruction is interpreted by a sequence of microinstructions","textCn":"每个机器指令都由一系列微指令解释"},{"key":"C","textEn":"A program of multiple machine instructions can be executed by one microprogram","textCn":"一个微程序可以执行多条机器指令组成的程序"},{"key":"D","textEn":"Each machine instruction is executed by multiple microprograms","textCn":"每条机器指令由多个微程序执行"}],"answerKey":"B","explanationCn":"微程序控制器通过微指令序列解释和执行每条机器指令，因此每条机器指令对应一组微指令。","explanationEn":""},{"id":"coa-ch15-004","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"Compared with horizontal microinstructions, vertical microinstructions:","stemCn":"与水平微指令相比，垂直微指令：","options":[{"key":"A","textEn":"Complete one or fewer micro-operations per vertical microinstruction","textCn":"每条垂直微指令完成一个或更少的微操作"},{"key":"B","textEn":"Complete only one micro-operation per horizontal microinstruction","textCn":"每条水平微指令仅完成一个微操作"},{"key":"C","textEn":"Both complete one micro-operation per instruction","textCn":"两者都完成每条指令的一个微操作"},{"key":"D","textEn":"Both complete multiple micro-operations per instruction","textCn":"两者都完成每条指令的多个微操作"}],"answerKey":"A","explanationCn":"垂直微指令（vertical microinstruction）通常字段较窄，一次只能完成一个或少数微操作，而水平微指令可以并行控制多个微操作，因此正确选项是 A。","explanationEn":""},{"id":"coa-ch15-005","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"Assume a computer uses a microprogrammed control unit. Its instruction set contains 32 machine instructions, and a common fetch cycle microprogram contains 2 microinstructions. If each machine instruction on average corresponds to 4 microinstructions and each microinstruction has a lower address field, what is the minimum number of bits required for the address field in the microinstruction?","stemCn":"假设计算机采用微程序控制单元，指令集包含 32 条机器指令，公共取指微程序包含 2 条微指令，每条机器指令平均对应 4 条微指令。若每条微指令都有下址字段，该字段至少需要多少位？","options":[{"key":"A","textEn":"5","textCn":"5"},{"key":"B","textEn":"6","textCn":"6"},{"key":"C","textEn":"8","textCn":"8"},{"key":"D","textEn":"9","textCn":"9"}],"answerKey":"C","explanationCn":"微指令地址位数计算公式： \\[ \\text{Address bits} = \\lceil \\log_2(\\text{Total microinstructions}) \\rceil \\] 总微指令数 = fetch周期微指令 + 各指令微指令 = 2 + (32 × 4) = 130 \\[ \\log_2 130 \\approx 7.02 \\implies \\text{向上取整} = 8 \\text{位} \\] 因此微指令地址字段至少需要 8 位。","explanationEn":""},{"id":"coa-ch15-006","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"Which unit holds the address of the microinstruction to be read next?","stemCn":"哪个单元保存接下来要读取的微指令的地址？","options":[{"key":"A","textEn":"Control storage","textCn":"控制存储"},{"key":"B","textEn":"Control address register","textCn":"控制地址寄存器"},{"key":"C","textEn":"Control word","textCn":"控制字"},{"key":"D","textEn":"Control buffer register","textCn":"控制缓冲寄存器"}],"answerKey":"B","explanationCn":"控制地址寄存器（Control Address Register, CAR）存放下一条待取微指令的地址，用于从控制存储器中取微指令。","explanationEn":""},{"id":"coa-ch16-001","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"For the symmetric multiprocessor system SMP, the meaning of \"symmetric\" here is ( ). Options:","stemCn":"对于对称多处理器系统SMP，这里的“对称”的含义是（ ）。选项：","options":[{"key":"A","textEn":"All processors have symmetric physical locations.","textCn":"所有处理器都有对称的物理位置。"},{"key":"B","textEn":"All processors have symmetric internal structures.","textCn":"所有处理器都具有对称的内部结构。"},{"key":"C","textEn":"All processors run the same program at the same time.","textCn":"所有处理器同时运行相同的程序。"},{"key":"D","textEn":"All processors can undertake the same functions and have basically the same access time to the shared memory.","textCn":"所有处理器都可以承担相同的功能，并且对共享内存的访问时间基本相同。"}],"answerKey":"D","explanationCn":"SMP的核心特征是“对称性”：系统中所有处理器地位完全平等，都可以执行操作系统内核代码和用户程序，对共享内存（通常通过总线或交叉开关访问）的访问延迟基本一致（Uniform Memory Access）。A选项物理位置对称不是本质；B选项内部结构对称也不准确（不同CPU可能有细微差异）；C选项同时运行相同程序是SIMD而非SMP的定义。因此D正确，体现了SMP的“对称”本质。","explanationEn":""},{"id":"coa-ch16-002","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"For SMP systems, which of the following internal organization hardware has the lowest cost, but the system efficiency is generally also relatively low? Options:","stemCn":"对于SMP系统，以下哪种内部组织硬件成本最低，但系统效率一般也比较低？选项：","options":[{"key":"A","textEn":"Time-shared bus","textCn":"分时共享总线"},{"key":"B","textEn":"Multi-port memory","textCn":"多端口存储器"},{"key":"C","textEn":"Central control unit","textCn":"中央控制单元"},{"key":"D","textEn":"Internal interconnection network","textCn":"内部互连网络"}],"answerKey":"A","explanationCn":"*分时复用总线（Time-shared Bus）** 实现简单、硬件成本最低，只需一根共享总线即可连接所有处理器和内存。但缺点明显：所有访问必须串行化，总线成为瓶颈，随着处理器增多，争用严重，导致效率低下。B多端口内存成本高但并行性好；C中央控制单元有单点故障风险；D内部互联网络（如交叉开关）成本高但可实现高并行。因此A符合“成本最低、效率较低”的描述。","explanationEn":""},{"id":"coa-ch16-003","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"Among the following statements about lightweight applications of clusters, which one is incorrect ( ). Options:","stemCn":"下列关于集群轻量级应用的说法，错误的是（ ）。选项：","options":[{"key":"A","textEn":"The cluster adopts passive backup, a kind of cold backup: one server handles the user load, while the other does not handle any user load, so the system overhead is zero.","textCn":"集群采用被动备份，是一种冷备份，即让两台服务器，一台承担用户负载，另一台机器不承担用户负载，系统开销为零。"},{"key":"B","textEn":"As a peer-to-peer server, the cluster lets two machines bear equal work, and at the same time performs data backup, so when one machine fails, the other can fully take over the work being processed.","textCn":"作为对等式服务器集群，两台机器分担工作并同时备份数据，因此一台故障时另一台可以接管其工作。"},{"key":"C","textEn":"As a server connecting disks, in addition to communication links between nodes, there are line connections between disks. After one machine fails, another machine can take over its disk through cluster configuration.","textCn":"作为连接磁盘的服务器，除了节点之间的通信链路外，磁盘之间还有线路连接。当一台机器出现故障后，另一台机器可以通过集群配置来接管其磁盘。"},{"key":"D","textEn":"When the cluster acts as a server sharing disks, compared to a server connecting disks, the service takeover speed is much higher.","textCn":"当集群作为共享磁盘的服务器时，相比于连接磁盘的服务器，服务接管速度要高得多。"}],"answerKey":"A","explanationCn":"被动式备份（Passive Standby）确实属于冷备份，但**系统开销不是零**——备用机需要保持运行、监控心跳、同步部分状态，存在硬件资源占用和潜在切换延迟。A选项“系统开销是零”的表述错误。B描述了对等式（Active-Active）集群；C、D描述了共享磁盘集群（Shared Disk）的容错机制，正确。因此A是错误的说法。","explanationEn":""},{"id":"coa-ch16-004","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"Among the following statements about NUMA systems, which one is incorrect ( ). Options:","stemCn":"下列有关 NUMA 系统的说法中，错误的是（ ）。选项：","options":[{"key":"A","textEn":"Non-cache-coherent NUMA systems are actually similar to cluster systems.","textCn":"非缓存一致性 NUMA 系统实际上类似于集群系统。"},{"key":"B","textEn":"Each node in a NUMA system has local memory, but all local memories form a shared global memory, which is uniformly addressed logically, and each node can access all memory spaces.","textCn":"NUMA系统中的每个节点都有本地内存，但所有本地内存形成共享的全局内存，逻辑上统一寻址，每个节点都可以访问所有内存空间。"},{"key":"C","textEn":"The operating system of a NUMA system is also built on top of the operating systems of each node, and tasks are similar to cluster systems.","textCn":"NUMA系统的操作系统也是构建在各个节点的操作系统之上，任务与集群系统类似。"},{"key":"D","textEn":"Since different nodes have different physical locations for memory, the real access time of each node in a NUMA system will be different.","textCn":"由于不同节点的内存物理位置不同，因此NUMA系统中每个节点的实际访问时间会有所不同。"}],"answerKey":"C","explanationCn":"NUMA系统是**紧耦合共享内存系统**，操作系统是一个统一的OS（通常支持NUMA-aware调度），而非每个节点独立OS（那是集群的特征）。C选项错误描述了集群的松耦合模型。A正确（CC-NUMA与集群有相似性）；B描述了NUMA的全局共享地址空间；D描述了非一致访问的本质。因此C错误。","explanationEn":""}],"tf":[{"id":"coa-ch01-tf-001","chapterId":"ch01","chapterName":"第一章简介","stemEn":"Determining the number of bits used to represent different types of data belongs to the scope of computer architecture.","stemCn":"确定用于表示不同类型数据的位数属于计算机体系结构的范围。","answer":"T","explanationCn":"不同类型数据的表示位数属于程序员可见的属性，例如字长、数据类型长度等，因此属于计算机体系结构的范畴。","explanationEn":""},{"id":"coa-ch01-tf-002","chapterId":"ch01","chapterName":"第一章简介","stemEn":"The definition of the interface between the computer and peripheral devices belongs to the scope of computer organization.","stemCn":"计算机与外围设备之间接口的定义属于计算机组成的范围。","answer":"T","explanationCn":"计算机与外部设备之间的接口定义涉及系统内部部件如何连接、如何传递信号和数据，属于计算机组成的范畴。","explanationEn":""},{"id":"coa-ch01-tf-003","chapterId":"ch01","chapterName":"第一章简介","stemEn":"The relationship between microarchitecture and computer organization is not close.","stemCn":"微体系结构和计算机组成之间的关系并不密切。","answer":"F","explanationCn":"微体系结构和计算机组成关系非常密切。体系结构更偏向程序员可见的功能属性，而微体系结构和组成更关注这些功能在硬件层面如何实现。","explanationEn":""},{"id":"coa-ch01-tf-004","chapterId":"ch01","chapterName":"第一章简介","stemEn":"A certain computer architecture may exist for many years, and computers belonging to this architecture may have multiple models. The organization of these different models may change as technology evolves.","stemCn":"某种计算机体系结构可能沿用多年，采用它的计算机可能有多种型号。随着技术发展，不同型号的具体组成可能发生变化。","answer":"T","explanationCn":"一种体系结构可以长期保持稳定，例如保持相同的指令系统和程序兼容性；但具体型号的计算机可以采用不同的组成和实现技术。因此，体系结构可以稳定存在，而计算机组成会随着技术发展不断变化。","explanationEn":""},{"id":"coa-ch01-tf-005","chapterId":"ch01","chapterName":"第一章简介","stemEn":"When data is transferred from a remote device to a local device, or from a local device to a remote device, this process is called data transmission.","stemCn":"当数据从远程设备传输到本地设备，或者从本地设备传输到远程设备时，这个过程称为数据传输。","answer":"F","explanationCn":"按照本章概念，数据传送是计算机的基本功能之一，其中本地设备与远程设备之间的数据交换通常称为数据通信，而不是简单称为数据传输。因此该说法错误。","explanationEn":""},{"id":"coa-ch03-tf-001","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"In synchronous communication, the clock signal used for synchronization is provided independently by each device connected to the bus.","stemCn":"在同步通信中，用于同步的时钟信号由连接到总线的每个设备独立提供。","answer":"F","explanationCn":"同步通信方式中，各部件必须按照统一的时钟节拍进行通信。同步时钟通常由总线控制逻辑或系统统一提供，而不是由总线上各设备自行提供，否则不同设备之间无法保持统一的时序关系。","explanationEn":""},{"id":"coa-ch03-tf-002","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"In centralized bus arbitration methods, the required number of control lines from few to many is: daisy-chain arbitration, counter-polling arbitration, and independent-request arbitration.","stemCn":"在集中式总线仲裁方法中，所需控制线数量从少到多依次为：菊花链仲裁、计数器轮询仲裁、独立请求仲裁。","answer":"T","explanationCn":"集中式总线仲裁常见方式包括链式查询、计数器轮询和独立请求。链式查询所需控制线最少；计数器轮询需要设备编号相关的控制线；独立请求方式每个设备通常都有独立请求线，因此控制线最多。所以该说法正确。","explanationEn":""},{"id":"coa-ch03-tf-003","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"At a certain moment, the bus may allow multiple pairs of master and slave modules to communicate at the same time.","stemCn":"在某一时刻，总线可以允许多对主从模块同时通信。","answer":"F","explanationCn":"总线是共享传输介质，同一时刻通常只能允许一个主模块占用总线，并与一个或多个从模块进行通信。如果多个主模块同时使用总线，会造成总线冲突。","explanationEn":""},{"id":"coa-ch03-tf-004","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"Asynchronous timing allows multiple modules with large speed differences to be connected together and work cooperatively.","stemCn":"异步时序允许多个速度差异较大的模块连接在一起并协同工作。","answer":"T","explanationCn":"异步通信不依赖统一的时钟信号，而是通过应答、握手等信号来协调通信。因此，它适合速度差异较大的模块之间进行数据交换。","explanationEn":""},{"id":"coa-ch03-tf-005","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"In a system bus, the address lines and data bus can be multiplexed.","stemCn":"在系统总线中，地址线和数据总线可以复用。","answer":"T","explanationCn":"地址线和数据线可以采用分时复用方式，即在不同时间段传输地址信息和数据信息。这样可以减少总线引脚数量和信号线数量，但通常会增加控制复杂度。","explanationEn":""},{"id":"coa-ch03-tf-006","chapterId":"ch03","chapterName":"第三章计算机功能与互连的顶层视图","stemEn":"A computer system contains different types of buses, and these buses provide communication paths for components at different levels of the hierarchical structure of the computer system.","stemCn":"计算机系统包含不同类型的总线，这些总线为计算机系统分层结构的不同级别的组件提供通信路径。","answer":"T","explanationCn":"计算机系统中通常存在多种总线，例如片内总线、系统总线、外部总线等。它们连接的部件层次不同，作用也不同，但本质上都是为不同层次的部件提供通信通路。因此该说法正确。","explanationEn":""},{"id":"coa-ch04-tf-001","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"Main memory uses associative access to access stored data.","stemCn":"主存储器使用关联访问来访问存储的数据。","answer":"F","explanationCn":"主存通常采用**按地址访问**的方式，即 CPU 给出地址，主存根据地址找到对应存储单元并读写数据。 关联访问是按照“内容”进行查找，常见于相联存储器或 Cache 标记比较等场景，不是普通主存的基本访问方式。 因此该说法错误。","explanationEn":""},{"id":"coa-ch04-tf-002","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"The data in Cache will always remain consistent with the data in main memory.","stemCn":"Cache中的数据将始终与主存中的数据保持一致。","answer":"F","explanationCn":"Cache 中的数据是主存中部分数据的副本，但二者并不一定始终完全一致。 例如采用**写回法**时，CPU 修改 Cache 中的数据后，可能暂时不立即写回主存，此时 Cache 和主存的数据就可能不一致。 只有在采用适当的写策略和一致性维护机制时，才能保证或恢复 Cache 与主存的一致性。 因此该说法错误。","explanationEn":""},{"id":"coa-ch04-tf-003","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"Generally speaking, L1 Cache uses a split Cache organization, while L2 Cache uses a unified Cache organization.","stemCn":"一般来说，L1 Cache采用分离式Cache组织，而L2 Cache采用统一Cache组织。","answer":"T","explanationCn":"一般情况下，一级 Cache 常分为**指令 Cache** 和 **数据 Cache**，即 split Cache。这样可以让取指令和访问数据并行进行，减少资源冲突。 二级 Cache 通常采用统一 Cache，即指令和数据共用同一个 Cache 空间。 因此该说法正确。","explanationEn":""},{"id":"coa-ch04-tf-004","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"The larger the Cache line size is, the higher the Cache hit rate will be.","stemCn":"Cache line size越大，Cache命中率越高。","answer":"F","explanationCn":"Cache 行越大，确实可以更好地利用**空间局部性**，因为一次调入的数据块中可能包含后续要访问的数据。 但是 Cache 行并不是越大越好。行太大时，在 Cache 总容量不变的情况下，Cache 行数会减少，可能导致更多冲突失效和容量失效；同时一次缺失时需要从主存调入更多数据，缺失代价也会变大。 因此 Cache 行大小增大不一定会使命中率持续升高，该说法错误。","explanationEn":""},{"id":"coa-ch04-tf-005","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"The larger the Cache capacity is, the higher the Cache hit rate will be.","stemCn":"Cache容量越大，Cache命中率越高。","answer":"T","explanationCn":"一般来说，在其他条件相同的情况下，Cache 容量越大，能够保存的主存块越多，数据被替换出去的概率越小，因此容量失效和部分冲突失效会减少，命中率通常会提高。 不过实际提升会有边际递减，即容量增加到一定程度后，命中率提升会变得不明显。 因此该说法正确。","explanationEn":""},{"id":"coa-ch04-tf-006","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"The length of data transferred by the system each time must be equal to the number of bits in one word or in one addressable unit.","stemCn":"系统每次传输的数据长度必须等于一个字或一个可寻址单元中的位数。","answer":"F","explanationCn":"系统每次传送数据的长度不一定必须等于一个字的位数，也不一定必须等于一个可寻址单元的位数。 在实际计算机系统中，数据传送单位可能是： - 字节（Byte） - 字（Word） - 双字 - 存储块 - Cache 行 - 总线一次能够传送的数据宽度 例如 Cache 和主存之间通常按**块**传送，而 CPU 和寄存器之间可能按字或双字传送。 所以“每次传送数据长度必须等于一个字或一个可寻址单元的位数”说法过于绝对，错误。","explanationEn":""},{"id":"coa-ch04-tf-007","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"In the write-back policy, write updates occur only in the Cache.","stemCn":"在回写策略中，写更新仅发生在Cache中。","answer":"F","explanationCn":"写回策略下，CPU 对数据进行写操作时，通常先只修改 Cache 中的副本，并设置修改位。 但是这并不表示写更新永远只发生在 Cache 中。 当被修改过的 Cache 块需要被替换时，系统必须把该块写回主存，以保证主存中的数据最终正确。 因此： - 写操作刚发生时：可能只更新 Cache； - 被替换或需要保持一致性时：仍然要写回主存。 所以“写更新只会发生在 Cache 中”说法不严谨，错误。","explanationEn":""},{"id":"coa-ch04-tf-008","chapterId":"ch04","chapterName":"第四章高速缓存","stemEn":"Cache is a type of internal memory.","stemCn":"高速缓存是一种内部存储器。","answer":"T","explanationCn":"Cache 是位于 CPU 和主存之间的高速小容量存储器，用来保存主存中近期可能被访问的数据副本。 它属于计算机存储层次中的高速内部存储部件，因此可以看作一种内存。 但需要注意，Cache 不是主存容量的一部分，它只是主存内容的高速副本。","explanationEn":""},{"id":"coa-ch05-tf-001","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"All semiconductor memories use random access to read and write data.","stemCn":"所有半导体存储器都使用随机存取来读取和写入数据。","answer":"T","explanationCn":"半导体存储器通常通过地址译码选择具体的存储单元，因此可以直接访问任意地址单元，而不需要像磁带那样从头顺序查找。 所以从存取方式上看，半导体存储器一般属于**随机存取存储器**，该说法正确。","explanationEn":""},{"id":"coa-ch05-tf-002","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Generally speaking, SRAM is faster and is suitable for Cache, while DRAM is cheaper and is suitable for main memory.","stemCn":"一般来说，SRAM速度较快，适合做Cache，而DRAM价格较便宜，适合做主存。","answer":"T","explanationCn":"SRAM 使用触发器保存数据，速度快，不需要刷新，但单元结构复杂、成本高、集成度较低，因此常用于 Cache。 DRAM 使用电容保存数据，结构简单、集成度高、成本低，但需要刷新，速度相对 SRAM 慢，因此常用于主存。 所以该说法正确。","explanationEn":""},{"id":"coa-ch05-tf-003","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Both RAM and ROM are volatile and must be powered by a DC power supply to retain data.","stemCn":"RAM 和 ROM 都是易失性存储器，必须靠直流电源（DC）供电才能保留数据。","answer":"F","explanationCn":"RAM 一般是易失性存储器，断电后数据会丢失。 ROM 是只读存储器，通常属于非易失性存储器，断电后仍能保存原有数据。 因此“RAM 和 ROM 都是易失的”这一说法错误。","explanationEn":""},{"id":"coa-ch05-tf-004","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"In memory expansion, bit expansion is used to expand the number of storage words of the whole memory.","stemCn":"在存储器扩展中，采用位扩展来扩展整个存储器的存储字数。","answer":"F","explanationCn":"存储器扩展主要有两类： 1. **位扩展**：扩展每个存储单元的字长，也就是增加数据位数。 例如用两个 `8K × 4-bit` 芯片组成一个 `8K × 8-bit` 存储器。 2. **字扩展**：扩展存储单元的个数，也就是增加地址范围。 例如用多个 `8K × 8-bit` 芯片组成一个 `32K × 8-bit` 存储器。 题干说“位扩展用于扩展存储字数”，实际上这是**字扩展**的作用，所以错误。","explanationEn":""},{"id":"coa-ch05-tf-005","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"Flash memory uses electrical erasing and writing, and it can support byte-level erasing and writing.","stemCn":"闪存采用电擦除和写入，可以支持字节级擦除和写入。","answer":"F","explanationCn":"Flash 闪存可以进行电擦写，但它通常是**按块擦除**，而不是按字节擦除。 支持字节级擦写的是 EEPROM，而 Flash 的典型特点是擦除单位较大，通常以块或扇区为单位。 因此“Flash 支持字节级擦写”说法错误。","explanationEn":""},{"id":"coa-ch05-tf-006","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"The advantage of RAM is that data or programs can permanently exist in main memory and do not need to be loaded from auxiliary storage devices.","stemCn":"RAM的优点是数据或程序可以永久存在于主存中，不需要从辅助存储设备加载。","answer":"F","explanationCn":"RAM 是易失性存储器，断电后其中的数据和程序会丢失。 程序和数据不能永久保存在 RAM 中，通常需要存放在硬盘、SSD 等辅存设备中，运行时再装入主存。 因此该说法错误。","explanationEn":""},{"id":"coa-ch05-tf-007","chapterId":"ch05","chapterName":"第五章内部存储器","stemEn":"The SRAM on CDRAM can be used as a cache to support serial access to data blocks.","stemCn":"CDRAM上的SRAM可以用作缓存，支持对数据块的串行访问。","answer":"T","explanationCn":"CDRAM 是带有 Cache 结构的 DRAM，其中集成的 SRAM 可以作为高速缓冲区。 当访问连续数据块时，可以先把数据块调入 SRAM 缓存，再支持较快的串行访问。 因此该说法正确。","explanationEn":""},{"id":"coa-ch06-tf-001","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Hard disks, floppy disks, and optical disks all use contact-type magnetic heads.","stemCn":"硬盘、软盘、光盘均采用接触式磁头。","answer":"F","explanationCn":"该说法错误。软盘通常采用接触式磁头，但硬盘的磁头一般是悬浮在高速旋转的盘片表面上方工作的，并不是接触式读写；光盘则使用激光进行读写，不使用磁头。因此不能说硬盘、软盘和光盘都采用接触式磁头。","explanationEn":""},{"id":"coa-ch06-tf-002","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"The smaller the magnetic head of a disk is, the narrower the track becomes, and the higher the data density of the disk becomes.","stemCn":"磁盘的磁头越小，磁道就越窄，磁盘的数据密度就越高。","answer":"T","explanationCn":"磁头越小，能够读写的磁道宽度就可以越窄。磁道越窄，在同样大小的盘面上就可以安排更多磁道，因此磁道密度提高，磁盘的数据存储密度也会增大。所以该说法正确。","explanationEn":""},{"id":"coa-ch06-tf-003","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"All magnetic disks and optical disks organize their tracks or optical tracks in concentric circles.","stemCn":"所有磁盘和光盘都将其轨道或光轨组织在同心圆中。","answer":"F","explanationCn":"磁盘通常采用同心圆方式组织磁道，每一圈是一个磁道。 但光盘不一定采用同心圆结构，很多光盘采用的是从内向外连续展开的螺旋形光道。因此不能说所有磁盘和光盘都采用同心圆方式组织磁道或光道。","explanationEn":""},{"id":"coa-ch06-tf-004","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"Generally speaking, both magnetic disks and optical disks rotate with constant angular velocity (CAV) to scan all data bits.","stemCn":"一般来说，磁盘和光盘都以恒定角速度（CAV）旋转来扫描所有数据位。","answer":"F","explanationCn":"磁盘一般采用恒定角速度 CAV，即盘片转速保持不变。这样外圈线速度大，内圈线速度小。 但光盘常见方式不完全相同，例如 CD 等光盘常采用恒定线速度 CLV 或类似方式，使读写位置处的数据通过速度保持相对稳定。 因此不能说磁盘和光盘都采用 CAV 扫描所有数据位，该说法错误。","explanationEn":""},{"id":"coa-ch06-tf-005","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"All RAID levels contain redundant information used to improve the reliability of the disk system.","stemCn":"所有RAID级别都包含用于提高磁盘系统可靠性的冗余信息。","answer":"F","explanationCn":"并不是所有 RAID 级别都包含冗余信息。 例如 RAID 0 只进行数据条带化，主要目的是提高并行读写性能，并不提供冗余保护。如果其中一块磁盘损坏，数据可能无法恢复。 而 RAID 1、RAID 5、RAID 6 等才通过镜像或奇偶校验等方式提供可靠性。因此该说法错误。","explanationEn":""},{"id":"coa-ch06-tf-006","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"During disk reading or writing, the magnetic head rotates while the platter below it remains stationary.","stemCn":"在磁盘读取或写入过程中，磁头旋转，而其下方的盘片保持静止。","answer":"F","explanationCn":"该说法正好相反。磁盘读写时，是盘片高速旋转，磁头一般不随盘片旋转。 磁头通过沿半径方向移动来定位到不同磁道，然后等待目标扇区旋转到磁头下方进行读写。 因此“磁头旋转而盘片静止”是错误的。","explanationEn":""},{"id":"coa-ch06-tf-007","chapterId":"ch06","chapterName":"第六章外部存储器","stemEn":"RAID consists of a group of physical disk drives, and this group of disks is viewed by the operating system as a single logical disk.","stemCn":"RAID 由一组物理磁盘驱动器组成，操作系统将这组磁盘视为单个逻辑磁盘。","answer":"T","explanationCn":"RAID 将多个物理磁盘组合起来，通过条带化、镜像、奇偶校验等技术提高性能或可靠性。 对操作系统来说，这组物理磁盘通常表现为一个逻辑磁盘，因此操作系统可以像访问一个普通磁盘一样访问 RAID 阵列。 所以该说法正确。","explanationEn":""},{"id":"coa-ch07-tf-001","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"A disk belongs to external storage, so it has no relationship with the I/O system.","stemCn":"磁盘属于外部存储，与I/O系统没有关系。","answer":"F","explanationCn":"磁盘虽然属于外部存储器，但它本质上也是一种外部设备。CPU 不能像访问寄存器或主存那样直接访问磁盘，而必须通过 I/O 控制器、设备驱动、总线以及相应的 I/O 操作完成数据交换。 因此，磁盘和 I/O 系统关系非常密切，该说法错误。","explanationEn":""},{"id":"coa-ch07-tf-002","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"In DMA mode, since the CPU does not need to participate in the specific data transfer operation, it has relatively high transfer efficiency.","stemCn":"在DMA模式下，由于CPU不需要参与具体的数据传输操作，因此具有相对较高的传输效率。","answer":"T","explanationCn":"DMA，即 Direct Memory Access，直接存储器访问。 在 DMA 方式下，数据可以在外设和主存之间直接传送，CPU 只需要在传送开始前进行初始化设置，在传送结束后处理中断即可，不需要逐字节或逐字地参与数据搬运。 因此 DMA 减少了 CPU 干预，提高了数据传送效率，该说法正确。","explanationEn":""},{"id":"coa-ch07-tf-003","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"Interrupt-driven I/O has a higher data transfer rate than programmed I/O.","stemCn":"中断驱动的 I/O 比编程 I/O 具有更高的数据传输速率。","answer":"F","explanationCn":"中断驱动式 I/O 的主要优点是减少 CPU 的无效等待，使 CPU 不必一直查询设备状态。 但它并不一定提高数据传输率，因为每次数据传送仍然需要 CPU 参与，并且还会引入中断响应、中断处理和现场恢复等开销。 程序式 I/O 和中断驱动式 I/O 的区别主要在于 CPU 是否需要持续轮询，而不是一定谁的数据传输率更高。 因此该说法错误。","explanationEn":""},{"id":"coa-ch07-tf-004","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"An I/O module can connect to only one I/O device.","stemCn":"一个 I/O 模块只能连接一个 I/O 设备。","answer":"F","explanationCn":"一个 I/O 模块可以连接一个或多个 I/O 设备。 例如一个磁盘控制器可以控制多个磁盘，一个 USB 控制器也可以通过集线器连接多个 USB 设备。 I/O 模块的作用是作为 CPU、主存与外设之间的接口，并不限制只能连接一个设备。 因此该说法错误。","explanationEn":""},{"id":"coa-ch07-tf-005","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"In a system with I/O channels, the I/O program is still specifically executed by the CPU.","stemCn":"在有I/O通道的系统中，I/O程序仍然由CPU专门执行。","answer":"F","explanationCn":"I/O 通道是一种专门负责 I/O 操作的处理部件。 在具有 I/O 通道的系统中，CPU 只需要启动通道，并指定通道程序的位置，之后由 I/O 通道执行通道程序并控制具体的 I/O 操作。 CPU 不再亲自执行具体的 I/O 程序，因此该说法错误。","explanationEn":""},{"id":"coa-ch07-tf-006","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"An I/O module must be able to recognize the unique address of each peripheral device connected to it.","stemCn":"I/O 模块必须能够识别与其连接的每个外围设备的唯一地址。","answer":"T","explanationCn":"I/O 模块通常连接一个或多个外部设备。为了让 CPU 能够准确访问某一个具体设备，I/O 模块必须能够识别其所连接设备的唯一地址。 当 CPU 发出 I/O 地址或设备地址后，I/O 模块根据地址选择对应的外设进行数据传送或控制操作。 因此该说法正确。","explanationEn":""},{"id":"coa-ch07-tf-007","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"In all cases, the processor must periodically check the status of the I/O module until the operation is completed.","stemCn":"在所有情况下，处理器必须定期检查 I/O 模块的状态，直到操作完成。","answer":"F","explanationCn":"该说法只适用于**程序查询方式 I/O**。 在程序查询方式中，CPU 需要不断读取 I/O 模块的状态寄存器，检查设备是否就绪或操作是否完成。 但并不是所有 I/O 方式都需要 CPU 定时检查状态： - **中断驱动 I/O**：设备完成准备或操作后主动向 CPU 发中断请求； - **DMA 方式**：数据块传送由 DMA 控制器完成，CPU 不需要持续检查； - **I/O 通道方式**：通道可独立执行 I/O 程序，CPU 干预更少。 所以“在所有情况下都需要处理器定时检查”说法错误。","explanationEn":""},{"id":"coa-ch07-tf-008","chapterId":"ch07","chapterName":"第七章输入输出","stemEn":"A disadvantage of memory-mapped I/O is that valuable memory address space may be easily exhausted.","stemCn":"内存映射 I/O 的缺点是宝贵的内存地址空间可能很容易耗尽。","answer":"T","explanationCn":"存储映射式 I/O 把 I/O 设备寄存器映射到主存地址空间中，CPU 可以使用普通访存指令访问 I/O 设备。 这种方式的优点是编程方便、指令统一，但缺点是 I/O 地址会占用一部分主存地址空间。 如果系统地址空间有限，而 I/O 设备很多，就可能导致可用于主存的地址空间减少，甚至出现地址资源紧张的问题。 因此该说法正确。","explanationEn":""},{"id":"coa-ch11-tf-001","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"When executing a branch instruction, the value of the Program Counter (PC) must be changed to the branch target address.","stemCn":"当执行分支指令时，程序计数器（PC）的值必须更改为分支目标地址。","answer":"F","explanationCn":"转移指令不一定都会真正改变 PC 为转移目标地址。 如果是**无条件转移指令**，执行时通常会把目标地址送入 PC；但如果是**条件转移指令**，只有当条件满足时才会转移，条件不满足时，PC 仍然指向顺序执行的下一条指令。 因此，“执行转移指令时一定修改 PC 为转移目标地址”说法过于绝对，错误。","explanationEn":""},{"id":"coa-ch11-tf-002","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Some operations during instruction execution are the same or similar.","stemCn":"指令执行过程中的一些操作是相同或相似的。","answer":"T","explanationCn":"不同指令虽然功能不同，但在执行过程中往往包含一些相同或相似的基本操作。 例如大多数指令都需要经历取指、译码、形成地址、读取操作数、执行运算、写回结果等步骤。 正因为这些操作具有重复性和规律性，CPU 才能采用统一的控制流程和流水线技术来提高执行效率。","explanationEn":""},{"id":"coa-ch11-tf-003","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"In a computer, the length of a clock cycle is fixed, while the instruction cycle lengths of different instructions may be different.","stemCn":"在计算机中，时钟周期的长度是固定的，而不同指令的指令周期长度可能不同。","answer":"T","explanationCn":"时钟周期由 CPU 的主频决定，在同一台计算机中通常是固定的。 但不同指令的复杂程度不同，所需的机器周期或时钟周期数可能不同。 例如简单寄存器加法指令可能只需要较少周期，而访存指令、乘除法指令、转移指令可能需要更多周期。 因此，时钟周期固定，但指令周期可以不同。","explanationEn":""},{"id":"coa-ch11-tf-004","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"Pipeline technology in the CPU constructs a processor based on spatial parallelism.","stemCn":"CPU中的流水线技术构建了一个基于空间并行的处理器。","answer":"F","explanationCn":"流水线技术主要依据的是**时间并行性**，也称时间重叠。 它把一条指令的执行过程划分为多个阶段，使多条指令在不同阶段上重叠执行。 例如当第 1 条指令在执行阶段时，第 2 条指令可以在译码阶段，第 3 条指令可以在取指阶段。 空间并行性通常是指增加多个处理部件或多个处理器同时工作，例如多核、多处理器等。 因此，CPU 流水线主要不是依据空间并行性，而是依据时间并行性，该说法错误。","explanationEn":""},{"id":"coa-ch11-tf-005","chapterId":"ch11","chapterName":"第十一章指令集：寻址方式与指令格式","stemEn":"When instructions flow through an ordinary pipeline in order, among RAW, WAR, and WAW, generally only RAW hazards may occur.","stemCn":"当指令按顺序流经普通流水线时，在RAW、WAR和WAW中，通常只可能发生RAW危险。","answer":"T","explanationCn":"普通按序流水线中，指令按顺序进入流水线，并且通常按顺序完成写回。 在这种情况下，最常见的数据相关是 **RAW（Read After Write，先写后读相关）**，也叫真正的数据相关。 例如： I1: ADD R1, R2, R3 ; R2 + R3 -> R1 I2: ADD R4, R1, R5 ; R1 + R5 -> R4 I2 要读取 R1，但 R1 是 I1 的结果。如果 I1 还没写回，I2 就去读 R1，就会产生 RAW 相关。 而 WAR 和 WAW 通常发生在乱序执行或乱序写回的情况下，普通按序流水线一般不容易出现。 因此该说法正确。","explanationEn":""},{"id":"coa-ch12-tf-001","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"RISC machines must use pipeline technology.","stemCn":"RISC机器必须使用流水线技术。","answer":"T","explanationCn":"在本章教材语境中，RISC 机通常与流水线技术紧密结合。 RISC 指令格式规整、指令长度较统一、寻址方式较少、操作较简单，这些特点非常适合流水线处理。 通过流水线，可以让多条指令在取指、译码、执行、访存、写回等阶段重叠执行，从而提高指令吞吐率。 因此本题判断为正确。","explanationEn":""},{"id":"coa-ch12-tf-002","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"The main goal of RISC is to reduce the number of instructions.","stemCn":"RISC的主要目标是减少指令数量。","answer":"F","explanationCn":"RISC 的核心目标不是单纯减少“程序中的指令条数”，而是通过简化指令系统、规整指令格式、减少寻址方式、加强寄存器使用和优化流水线，使每条指令执行得更快、更容易并行。 RISC 的思想是： 复杂操作可以由多条简单指令组合完成，但每条简单指令执行速度快、控制逻辑简单、流水线效率高。 所以 RISC 并不一定让程序总指令条数减少，有时反而会增加指令条数。 因此该说法错误。","explanationEn":""},{"id":"coa-ch12-tf-003","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Early computer instructions were relatively simple, so RISC technology made computer architecture return to the level of early computers.","stemCn":"早期的计算机指令相对简单，因此RISC技术使计算机架构回归到早期计算机的水平。","answer":"F","explanationCn":"RISC 虽然强调“精简指令集”，但它并不是简单地退回到早期计算机水平。 早期计算机指令简单，主要是因为硬件资源有限、体系结构尚不成熟。 而 RISC 是在对程序执行特征、编译优化、流水线技术、寄存器组织等深入研究基础上形成的体系结构思想。 RISC 的“简单”是为了提高执行效率、优化流水线和降低控制复杂度，而不是技术倒退。 因此该说法错误。","explanationEn":""},{"id":"coa-ch12-tf-004","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"The use of a large register file makes it unnecessary for RISC machines to use Cache organizations.","stemCn":"大寄存器文件的使用使得RISC机器没有必要使用Cache组织。","answer":"F","explanationCn":"大寄存器组可以减少对主存的访问次数，因为更多临时变量、局部变量和参数可以保存在寄存器中。 但是寄存器数量再多，也不可能完全替代 Cache。 Cache 的作用是缓解 CPU 与主存之间的速度差异，保存近期可能访问的主存数据和指令副本。 RISC 机虽然大量使用寄存器，但仍然需要 Cache 来提高指令访问和数据访问速度。 因此“大寄存器组使 RISC 不再需要 Cache”是错误的。","explanationEn":""},{"id":"coa-ch12-tf-005","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Graph coloring is essentially a time-multiplexing technique that allocates physical registers to different symbolic register variables at different times.","stemCn":"图形着色本质上是一种时间复用技术，它在不同时间将物理寄存器分配给不同的符号寄存器变量。","answer":"T","explanationCn":"图染色技术常用于编译器的寄存器分配。 程序中的变量可以看作“符号寄存器变量”，如果两个变量的生命周期不重叠，它们就可以使用同一个物理寄存器。 图染色的基本思想是： - 把变量之间的冲突关系表示成图； - 如果两个变量不能使用同一个寄存器，就在它们之间连边； - 给图中的结点染色，每种颜色对应一个物理寄存器。 这样就可以在不同时间把同一个物理寄存器分配给不同变量，本质上体现了寄存器资源的分时复用。 因此该说法正确。","explanationEn":""},{"id":"coa-ch12-tf-006","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"The addresses used by register sets are much shorter than Cache and memory addresses.","stemCn":"寄存器组使用的地址比Cache和内存地址短得多。","answer":"T","explanationCn":"寄存器数量远少于 Cache 或主存中的存储单元数量，因此寄存器编号所需的位数很少。 例如，如果 CPU 有 32 个寄存器，则寄存器编号只需要： $$ \\log_2 32 = 5 $$ 位。 而主存地址可能需要 32 位、64 位甚至更多。 因此寄存器组所使用的地址，也就是寄存器编号，确实比 Cache 和内存地址短得多。 该说法正确。","explanationEn":""},{"id":"coa-ch12-tf-007","chapterId":"ch12","chapterName":"第十二章CPU结构与功能","stemEn":"Almost all RISC instructions use simple register addressing.","stemCn":"几乎所有 RISC 指令都使用简单的寄存器寻址。","answer":"T","explanationCn":"RISC 的一个重要特点是大量使用寄存器操作。 算术逻辑运算通常在寄存器之间进行，而不是直接对主存操作。 访存一般只由专门的 Load/Store 指令完成。 因此，RISC 中大量指令都会使用简单的寄存器寻址方式，这有利于： - 缩短指令格式； - 简化译码； - 提高执行速度； - 便于流水线设计。 所以该说法正确。","explanationEn":""},{"id":"coa-ch13-tf-001","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Superpipelining is equivalent to dividing the pipeline into more stages, thereby increasing the number of instructions that can be executed in parallel within each clock cycle.","stemCn":"超级流水线相当于将流水线划分为更多级，从而增加了每个时钟周期内可以并行执行的指令数量。","answer":"T","explanationCn":"超级流水线的基本思想是把原来的流水段进一步细分，使每个流水段完成的工作更少，从而可以缩短流水线的时钟周期，提高流水线的工作频率。 流水段变多后，同一时间处在流水线中的指令数也会增加，因此可以提高指令级并行程度。 所以该说法正确。","explanationEn":""},{"id":"coa-ch13-tf-002","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"A superscalar processor must be a processor that uses pipeline technology.","stemCn":"超标量处理器一定是采用流水线技术的处理器。","answer":"T","explanationCn":"超标量处理器的核心思想是在一个时钟周期内同时发射多条指令，并让它们进入多个功能部件或多条流水线并行执行。 如果没有流水线技术，处理器很难在高效率下同时组织多条指令的取指、译码、执行和写回。 因此，超标量处理器通常一定建立在流水线技术基础上。 所以该说法正确。","explanationEn":""},{"id":"coa-ch13-tf-003","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Since the degrees of superpipelining and superscalar processing can be the same, their essence is the same.","stemCn":"由于超流水线和超标量处理的程度可以相同，因此它们的本质是相同的。","answer":"F","explanationCn":"超级流水线和超标量都能提高指令级并行性，但二者本质不同。 - **Superpipelining（超级流水线）**：把流水线划分得更细，提高时钟频率，使指令更密集地进入流水线。 - **Superscalar（超标量）**：在一个时钟周期内同时发射多条指令，依靠多个功能部件或多条流水线并行执行。 即使二者的“度”相同，例如都能体现为某种程度上的并行能力，它们提高性能的方式仍然不同。 所以该说法错误。","explanationEn":""},{"id":"coa-ch13-tf-004","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"During superscalar execution, instructions generally undergo register renaming first and then enter the instruction window for analysis.","stemCn":"超标量执行时，指令一般先进行寄存器重命名，然后进入指令窗口进行分析。","answer":"T","explanationCn":"超标量处理器为了支持乱序发射和乱序执行，通常需要先进行寄存器重命名。 寄存器重命名可以消除由于重复使用同一寄存器名而产生的假相关，例如： - WAR：Write After Read，反相关； - WAW：Write After Write，输出相关。 完成寄存器重命名后，指令进入指令窗口，由硬件检查操作数是否就绪、功能部件是否可用，并决定哪些指令可以发射执行。 所以该说法正确。","explanationEn":""},{"id":"coa-ch13-tf-005","chapterId":"ch13","chapterName":"第十三章精简指令集计算机","stemEn":"Register renaming and instruction window technology can solve all problems caused by dependencies.","stemCn":"寄存器重命名和指令窗口技术可以解决所有由依赖引起的问题。","answer":"F","explanationCn":"寄存器重命名和指令窗口确实可以解决或缓解很多相关问题，但不能解决所有相关问题。 寄存器重命名主要解决的是**名相关**，包括： - WAR：反相关； - WAW：输出相关。 指令窗口可以通过动态调度，让已经准备好的指令提前执行，从而减少等待时间。 但是对于真正的数据相关，也就是 RAW： $$ 后续指令需要读取前面指令产生的结果 $$ 这种依赖不能简单消除，只能等待前一条指令产生结果后再执行。 此外，内存访问相关、控制相关、资源冲突等问题也不一定能完全由寄存器重命名和指令窗口解决。 因此该说法错误。","explanationEn":""},{"id":"coa-ch14-tf-001","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"The output signals of the control unit include control signals inside the CPU and control signals sent to the control bus.","stemCn":"控制单元的输出信号包括CPU内部的控制信号和发送到控制总线的控制信号。","answer":"T","explanationCn":"控制单元（Control Unit, CU）的任务是根据指令、时序信号和状态信息产生控制信号。这些控制信号一部分用于 CPU 内部，例如控制寄存器之间的数据传送、ALU 运算、程序计数器 PC 更新等；另一部分用于 CPU 外部，例如通过控制总线发出读/写、中断响应等控制信号。因此该说法正确。","explanationEn":""},{"id":"coa-ch14-tf-002","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"In the instruction cycle of every instruction, the fetch cycle, indirect cycle, execution cycle, and interrupt cycle must all be included.","stemCn":"每条指令的指令周期中都必须包含取指周期、间接周期、执行周期和中断周期。","answer":"F","explanationCn":"不是每条指令都一定包含所有周期。 一条指令通常一定需要**取指周期（fetch cycle）**和**执行周期（execution cycle）**，但： - **间址周期（indirect cycle）**只有在指令使用间接寻址时才需要； - **中断周期（interrupt cycle）**只有在执行完指令后检测到中断请求，并且允许响应中断时才进入。 所以“所有指令都一定包含取指、间址、执行、中断周期”是错误的。","explanationEn":""},{"id":"coa-ch14-tf-003","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"The controller not only needs to care about what the data or result currently being processed is, but also needs to care about the properties of the result, such as overflow and sign, and then control the next step accordingly.","stemCn":"控制器不仅需要关心当前正在处理的数据或结果是什么，还需要关心结果的属性，例如溢出和符号，然后相应地控制下一步。","answer":"F","explanationCn":"控制器主要根据**指令操作码、时序信号、状态标志**等产生控制信号。 它通常不直接关心“数据本身是什么”，而是关心运算后形成的**状态标志**，例如： - 零标志 `Z` - 符号标志 `S` - 进位标志 `C` - 溢出标志 `V` 这些状态标志会影响后续控制，例如条件转移指令是否跳转。 题干中说控制器还要关心“数据或结果本身是什么”，这个表述不严谨，因此判错。","explanationEn":""},{"id":"coa-ch14-tf-004","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"The basic task of the controller is to arrange and execute micro-operations.","stemCn":"控制器的基本任务是安排和执行微操作。","answer":"T","explanationCn":"控制器的核心功能就是按照指令执行过程的要求，在合适的时刻发出控制信号，使各个部件完成相应的微操作。 例如取指周期中可能包括： PC -> MAR M(MAR) -> MDR MDR -> IR PC + 1 -> PC 这些都是微操作。控制器要安排这些微操作的先后顺序，并控制它们正确执行，所以该说法正确。","explanationEn":""},{"id":"coa-ch14-tf-005","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"A micro-operation is the simplest or most primitive operation in a CPU.","stemCn":"微操作是CPU中最简单或最原始的操作。","answer":"T","explanationCn":"微操作是 CPU 内部能够直接完成的基本操作，通常不能再继续分解成更小的控制步骤。 例如： PC -> MAR MDR -> IR R1 + R2 -> R3 这些都属于微操作。 一条机器指令的执行过程通常由多个微操作组成，因此该说法正确。","explanationEn":""},{"id":"coa-ch14-tf-006","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"The operations “read a word from memory” and “increment PC by 1” cannot be performed at the same time, because they interfere with each other.","stemCn":"“从内存中读取一个字”和“PC加1”操作不能同时执行，因为它们会互相干扰。","answer":"F","explanationCn":"“从内存读取字”和“PC 自增 1”通常可以并行进行，因为它们使用的硬件资源不同。 例如在取指周期中： M(MAR) -> MDR PC + 1 -> PC 读取存储器使用的是 MAR、MDR、存储器和总线； PC 自增主要使用 PC 及加法逻辑。 如果数据通路允许，这两个微操作可以安排在同一个节拍中完成，并不会必然相互干扰。 所以该说法错误。","explanationEn":""},{"id":"coa-ch14-tf-007","chapterId":"ch14","chapterName":"第十四章指令级并行性和超标量处理","stemEn":"In order to perform its function, the control unit must have inputs that can determine the system state and outputs that can control the behavior of the entire system.","stemCn":"为了执行其功能，控制单元必须具有可以确定系统状态的输入和可以控制整个系统行为的输出。","answer":"T","explanationCn":"控制单元要完成控制任务，必须具备两类基本信息： 输入信息：用于判断当前系统状态，例如指令操作码、时序信号、状态标志、中断请求等； 输出信息：用于控制 CPU 和系统其他部件的动作，例如寄存器装入、ALU 运算、存储器读写、总线控制等。 因此，控制单元必须能够根据输入状态产生对应的控制输出，从而控制整个系统的运行。 所以该说法正确。","explanationEn":""},{"id":"coa-ch15-tf-001","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"The key components of a microprogrammed control unit include: control storage, control address register, control buffer register, and sequencer.","stemCn":"微程序控制单元的关键部件包括：控制存储器、控制地址寄存器、控制缓冲寄存器和定序器。","answer":"T","explanationCn":"微程序控制器的主要组成部分包括控制存储器（存放微指令）、控制地址寄存器（指向下一条微指令地址）、控制缓冲寄存器（暂存微指令）以及排序单元（用于确定微指令执行顺序），因此此说法正确。","explanationEn":""},{"id":"coa-ch15-tf-002","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"The speed of a microprogrammed control unit is slower than that of a hardwired control unit mainly because of the added time to fetch microinstructions from memory.","stemCn":"微程序控制单元的速度比硬连线控制单元慢，主要是因为从存储器获取微指令的时间增加了。","answer":"F","explanationCn":"微程序控制器确实通常比硬布线控制器慢，但主要原因不是简单的存储访问时间，而是微程序控制器通过微指令序列实现控制逻辑，其速度受微指令字长、微指令执行周期以及解码逻辑影响，而不仅仅是从主存取微指令的时间。因此原命题错误。","explanationEn":""},{"id":"coa-ch15-tf-003","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"The purpose of using a microprogrammed control unit is to simplify the design complexity of the controller.","stemCn":"使用微程序控制单元的目的是简化控制器的设计复杂性。","answer":"T","explanationCn":"微程序控制器通过用可编程的微指令代替复杂逻辑电路，极大地降低了控制器设计的复杂度，因此该说法正确。","explanationEn":""},{"id":"coa-ch15-tf-004","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"A compatible microinstruction means several microinstructions can be mutually replaced.","stemCn":"兼容微指令是指多个微指令可以相互替换。","answer":"F","explanationCn":"兼容性微指令并不意味着多条微指令可以互换，而是指不同微指令可以在同一控制器中顺利执行而不冲突，因此此说法错误。","explanationEn":""},{"id":"coa-ch15-tf-005","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"Only processors using a microprogrammed control unit are called microprocessors.","stemCn":"只有使用微程序控制单元的处理器才称为微处理器。","answer":"F","explanationCn":"微处理器的定义与是否使用微程序控制器无关，关键是处理器内部集成了CPU核心并可执行指令集，因此该命题错误。","explanationEn":""},{"id":"coa-ch15-tf-006","chapterId":"ch15","chapterName":"第十五章控制单元操作","stemEn":"The microprogrammed control unit's CU is a relatively complex logic circuit.","stemCn":"微程序控制单元的CU是一个相对复杂的逻辑电路。","answer":"F","explanationCn":"微程序控制器本身逻辑简单，复杂的控制逻辑通过存储的微指令实现，因此 CU 并不复杂，此说法错误。","explanationEn":""},{"id":"coa-ch16-tf-001","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"According to the communication method between processors, NUMA systems belong to distributed memory systems.","stemCn":"根据处理器之间的通信方式，NUMA系统属于分布式内存系统。","answer":"F","explanationCn":"NUMA（Non-Uniform Memory Access，非一致内存访问）系统虽然每个节点有本地内存，且访问本地内存和远程内存的延迟不同，但其本质上仍然属于**共享内存多处理机系统（Shared Memory Multiprocessor）**，而不是严格意义上的分布式存储系统。分布式存储系统（如集群系统中的典型分布式内存）通常指每个节点有独立的地址空间，节点间通过消息传递通信，没有全局共享的物理内存。NUMA系统通过硬件（目录或互联网络）实现了全局地址空间的共享，只是访问时间不一致。因此该说法错误。NUMA是SMP的扩展，但属于集中式或分布式目录管理的共享内存架构。","explanationEn":""},{"id":"coa-ch16-tf-002","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"For SMP systems, the failure of any single processor will not cause the entire system to crash.","stemCn":"对于SMP系统来说，任何一个处理器的故障都不会导致整个系统崩溃。","answer":"T","explanationCn":"SMP（Symmetric Multi-Processing，对称多处理）系统具有高可用性设计。系统中的多个处理器地位对称，当某个处理器发生故障时，其他处理器可以继续工作，操作系统会将故障处理器隔离（通过热插拔、故障恢复机制或资源重分配），系统整体不会崩溃。这体现了SMP的容错能力。当然，极端情况下（如所有处理器共享的关键资源完全失效）可能影响系统，但单个处理器故障一般不会导致整个系统崩溃。该特性是SMP相对于单处理器系统的重要优势之一。","explanationEn":""},{"id":"coa-ch16-tf-003","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"For SMP systems, the more processors there are, the higher the performance will definitely be.","stemCn":"对于SMP系统来说，处理器越多，性能肯定越高。","answer":"F","explanationCn":"SMP系统中处理器数量增加并不一定线性提升性能。主要受限于**总线带宽、内存争用、Cache一致性开销、Amhdal定律（串行部分限制）**以及软件并行度等因素。随着处理器增多，互联网络（如总线）的竞争加剧，Cache一致性协议（如MESI）的通信开销显著上升，可能出现“扩展性墙”。实际性能通常先上升后趋于平缓甚至下降。因此“一定也越高”的说法错误，需要结合具体工作负载和系统设计评估。","explanationEn":""},{"id":"coa-ch16-tf-004","chapterId":"ch16","chapterName":"第十六章多处理器与集群","stemEn":"If multiple computers are only connected through a network, then it is a cluster system.","stemCn":"如果多台计算机仅通过网络连接，那么它就是集群系统。","answer":"F","explanationCn":"集群系统（Cluster）是指一组通过高速网络互联的独立计算机，它们作为一个单一系统对外提供服务，具有高可用性、可扩展性和负载均衡等特性。但“仅通过网络连接”不够充分，还需要满足**松耦合、统一管理系统、共享资源或任务分配机制**等条件。单纯的网络连接（如多台独立PC通过局域网互联）只是分布式系统或网络，并非集群。集群通常还需要专用软件（如负载均衡器、故障转移机制）和硬件支持（如共享存储）。该说法过于宽泛，因此错误。","explanationEn":""}],"terms":[]},{"id":"os","name":"Operating Systems","chapters":[{"id":"ch01","name":"introduction"},{"id":"ch02","name":"operating-system structures"},{"id":"ch03","name":"Operating System Structure"},{"id":"ch04","name":"processes"},{"id":"ch05","name":"threads"},{"id":"ch06","name":"process scheduling"},{"id":"ch07","name":"synchronization"},{"id":"ch08","name":"deadlocks"},{"id":"ch09","name":"memory management"},{"id":"ch10","name":"virtual memory"},{"id":"ch11","name":"File System"},{"id":"ch12","name":"Secondary Storage"},{"id":"ch13","name":"I/O Systems"}],"mcq":[{"id":"os-ch01-001","chapterId":"ch01","chapterName":"introduction","stemEn":"An operating system is software that manages ().","stemCn":"操作系统是对（）进行管理的软件。","options":[{"key":"A","textEn":"Software","textCn":"软件"},{"key":"B","textEn":"Hardware","textCn":"硬件"},{"key":"C","textEn":"Computer resources","textCn":"计算机资源"},{"key":"D","textEn":"Application programs","textCn":"应用程序"}],"answerKey":"C","explanationCn":"操作系统的核心作用是管理和控制计算机系统中的各种资源，包括处理器、存储器、设备和文件等，因此应选计算机资源。","explanationEn":""},{"id":"os-ch01-002","chapterId":"ch01","chapterName":"introduction","stemEn":"An operating system is a kind of ().","stemCn":"操作系统是一种（）。","options":[{"key":"A","textEn":"Software package","textCn":"软件包"},{"key":"B","textEn":"Application software","textCn":"应用软件"},{"key":"C","textEn":"General-purpose software","textCn":"通用软件"},{"key":"D","textEn":"System software","textCn":"系统软件"}],"answerKey":"D","explanationCn":"操作系统直接管理硬件资源，并为应用程序提供运行环境和系统服务，属于系统软件而不是应用软件。","explanationEn":""},{"id":"os-ch01-003","chapterId":"ch01","chapterName":"introduction","stemEn":"Which of the following is not a basic characteristic of multiprogramming?","stemCn":"下列选项中，不属于多道程序设计的基本特征是（）。","options":[{"key":"A","textEn":"Intermittence","textCn":"间断性"},{"key":"B","textEn":"Multiplicity","textCn":"多道性"},{"key":"C","textEn":"Sequentiality","textCn":"顺序性"},{"key":"D","textEn":"Unpredictability","textCn":"无序性"}],"answerKey":"C","explanationCn":"多道程序设计强调多个程序并发执行，具有多道性、间断性和无序性等特点。顺序性更符合单道程序顺序执行的特征，不属于多道程序设计的基本特征。","explanationEn":""},{"id":"os-ch01-004","chapterId":"ch01","chapterName":"introduction","stemEn":"The key technique for improving CPU utilization is ().","stemCn":"提高 CPU 利用率的关键技术是（）。","options":[{"key":"A","textEn":"Swapping technology","textCn":"交换技术"},{"key":"B","textEn":"Virtualization technology","textCn":"虚拟技术"},{"key":"C","textEn":"Multiprogramming technology","textCn":"多道程序设计技术"},{"key":"D","textEn":"Offline technology","textCn":"脱机技术"}],"answerKey":"C","explanationCn":"多道程序设计使多个作业同时进入内存，当一个程序等待 I/O 时，CPU 可以转去执行其他程序，从而显著提高 CPU 利用率。","explanationEn":""},{"id":"os-ch01-005","chapterId":"ch01","chapterName":"introduction","stemEn":"The two most basic characteristics of a modern operating system are ().","stemCn":"现代操作系统中最基本的两个特征是（）。","options":[{"key":"A","textEn":"Virtualization and uncertainty","textCn":"虚拟和不确定"},{"key":"B","textEn":"Sharing and virtualization","textCn":"共享和虚拟"},{"key":"C","textEn":"Concurrency and uncertainty","textCn":"并发和不确定"},{"key":"D","textEn":"Concurrency and sharing","textCn":"并发和共享"}],"answerKey":"D","explanationCn":"现代操作系统的基本特征包括并发、共享、虚拟和异步，其中并发和共享是两个最基本的特征，二者也是操作系统资源管理的基础。","explanationEn":""},{"id":"os-ch02-001","chapterId":"ch02","chapterName":"operating-system structures","stemEn":"The instructions executed by a processor are divided into two categories. One category is called privileged instructions, which are allowed to be used only by ().","stemCn":"处理器执行的指令被分为两类，其中有一类称为特权指令，它只允许（）使用。","options":[{"key":"A","textEn":"Target programs","textCn":"目标程序"},{"key":"B","textEn":"Associated users","textCn":"联机用户"},{"key":"C","textEn":"Operators","textCn":"操作员"},{"key":"D","textEn":"Operating system","textCn":"操作系统"}],"answerKey":"D","explanationCn":"特权指令涉及 I/O、状态切换、中断控制等核心资源操作，只能在核心态由操作系统执行，普通用户程序不能直接使用。","explanationEn":""},{"id":"os-ch02-002","chapterId":"ch02","chapterName":"operating-system structures","stemEn":"The interface provided by an operating system to programmers is ().","stemCn":"操作系统提供给编程人员的接口是（）。","options":[{"key":"A","textEn":"Library functions","textCn":"库函数"},{"key":"B","textEn":"System calls","textCn":"系统调用"},{"key":"C","textEn":"Subprograms","textCn":"子程序"},{"key":"D","textEn":"High-level languages","textCn":"高级语言"}],"answerKey":"B","explanationCn":"系统调用是操作系统向程序员提供的编程接口，应用程序通过系统调用请求内核完成文件、进程、设备等系统服务。","explanationEn":""},{"id":"os-ch02-003","chapterId":"ch02","chapterName":"operating-system structures","stemEn":"After an interrupt occurs, the program that enters interrupt processing belongs to ().","stemCn":"在中断发生后，进入中断处理的程序属于（）。","options":[{"key":"A","textEn":"Neither an application program nor an operating system program","textCn":"既不是应用程序，也不是操作系统程序"},{"key":"B","textEn":"Operating system program","textCn":"操作系统程序"},{"key":"C","textEn":"It may be an application program or an operating system program","textCn":"可能是应用程序，也可能是操作系统程序"},{"key":"D","textEn":"User program","textCn":"用户程序"}],"answerKey":"B","explanationCn":"中断处理程序在核心态执行，属于操作系统内核的一部分，用于响应和处理硬件或软件中断。","explanationEn":""},{"id":"os-ch02-004","chapterId":"ch02","chapterName":"operating-system structures","stemEn":"Which of the following instructions must be executed in kernel mode?","stemCn":"下列必须在核心态下执行的指令是（）。","options":[{"key":"A","textEn":"Fetch data from memory","textCn":"从内存中取数"},{"key":"B","textEn":"Write the result of an operation into memory","textCn":"将运算结果装入内存"},{"key":"C","textEn":"I/O operation","textCn":"I/O 操作"},{"key":"D","textEn":"Arithmetic operation","textCn":"算术运算"}],"answerKey":"C","explanationCn":"I/O 操作会直接访问外部设备和系统资源，属于特权操作，必须在核心态下由操作系统执行。","explanationEn":""},{"id":"os-ch02-005","chapterId":"ch02","chapterName":"operating-system structures","stemEn":"The purpose of a system call is ().","stemCn":"系统调用的目的是（）。","options":[{"key":"A","textEn":"To request system services","textCn":"请求系统服务"},{"key":"B","textEn":"To release system resources","textCn":"释放系统资源"},{"key":"C","textEn":"To apply for system resources","textCn":"申请系统资源"},{"key":"D","textEn":"To terminate system services","textCn":"中止系统服务"}],"answerKey":"A","explanationCn":"系统调用的本质是用户程序向操作系统内核请求服务，例如文件操作、进程控制和设备访问等。","explanationEn":""},{"id":"os-ch04-001","chapterId":"ch04","chapterName":"processes","stemEn":"A process is ().","stemCn":"一个进程是（）。","options":[{"key":"A","textEn":"An independent program plus a data set","textCn":"一个独立的程序 + 数据集"},{"key":"B","textEn":"A program executed by a coprocessor","textCn":"由协处理器执行的一个程序"},{"key":"C","textEn":"An independent program","textCn":"一个独立的程序"},{"key":"D","textEn":"A combination of a PCB structure, a program, and data","textCn":"PCB 结构与程序和数据的组合"}],"answerKey":"D","explanationCn":"进程不是单纯的程序，而是程序的一次执行过程，通常由程序段、数据段和进程控制块 PCB 共同组成。","explanationEn":""},{"id":"os-ch04-002","chapterId":"ch04","chapterName":"processes","stemEn":"The essential difference between a process and a program is ().","stemCn":"进程与程序的根本区别是（）。","options":[{"key":"A","textEn":"Whether it has the three states: ready, running, and waiting","textCn":"是不是具有就绪、运行和等待三种状态"},{"key":"B","textEn":"Whether it is loaded into memory","textCn":"是不是被调入到内存"},{"key":"C","textEn":"Whether it occupies the processor","textCn":"是不是占有处理器"},{"key":"D","textEn":"The difference between static and dynamic","textCn":"静态和动态的区别"}],"answerKey":"D","explanationCn":"程序是静态的指令集合，进程是程序在数据集上的一次动态执行过程，因此二者的根本区别是静态与动态的区别。","explanationEn":""},{"id":"os-ch04-003","chapterId":"ch04","chapterName":"processes","stemEn":"The operating system controls and manages concurrently executing processes according to ().","stemCn":"操作系统是根据（）来对并发执行的进程进行控制和管理的。","options":[{"key":"A","textEn":"Basic states of a process","textCn":"进程的基本状态"},{"key":"B","textEn":"Multiprogramming","textCn":"多道程序设计"},{"key":"C","textEn":"Priority of a process","textCn":"进程的优先权"},{"key":"D","textEn":"Process control block","textCn":"进程控制块"}],"answerKey":"D","explanationCn":"PCB 是进程存在的唯一标志，保存进程状态、调度信息和资源信息，操作系统通过 PCB 控制和管理进程。","explanationEn":""},{"id":"os-ch04-004","chapterId":"ch04","chapterName":"processes","stemEn":"Which of the following descriptions about processes best matches the operating system's understanding of a process?","stemCn":"下列几种关于进程的叙述，（）是最符合操作系统对进程的理解。","options":[{"key":"A","textEn":"A process is the running procedure of a program on a data set","textCn":"进程是程序在一个数据集合上的运行过程"},{"key":"B","textEn":"A process is an independent unit for resource allocation and scheduling by the system","textCn":"进程是系统进行资源分配和调度的一个独立单元"},{"key":"C","textEn":"A process can be described by a program, data, and a PCB","textCn":"进程可以由程序、数据和 PCB 描述"},{"key":"D","textEn":"A process is a complete program in a multiprogramming environment","textCn":"进程是在多程序环境中的完整的程序"}],"answerKey":"D","explanationCn":"进程不是静态的完整程序，而是程序的一次动态执行过程，并带有相应数据和 PCB。因此 D 把进程简单理解为完整程序，不符合操作系统对进程的准确理解。","explanationEn":""},{"id":"os-ch04-005","chapterId":"ch04","chapterName":"processes","stemEn":"The same program is created multiple times and runs on different data sets, forming () processes.","stemCn":"同一程序经过多次创建，运行在不同的数据集上，形成了（）的进程。","options":[{"key":"A","textEn":"Synchronous","textCn":"同步"},{"key":"B","textEn":"Identical","textCn":"相同"},{"key":"C","textEn":"Mutually exclusive","textCn":"互斥"},{"key":"D","textEn":"Different","textCn":"不同"}],"answerKey":"D","explanationCn":"即使执行的是同一个程序，只要创建次数不同或运行数据不同，就会形成不同的进程，每个进程都有独立的 PCB 和运行状态。","explanationEn":""},{"id":"os-ch04-006","chapterId":"ch04","chapterName":"processes","stemEn":"The communication mechanism for message passing between processes requires two communication primitives. They are ().","stemCn":"用信箱实现进程间互通消息的通信机制要有两个通信原语，它们是（）。","options":[{"key":"A","textEn":"Ready primitive and receive primitive","textCn":"就绪原语和接收原语"},{"key":"B","textEn":"Send primitive and receive primitive","textCn":"发送原语和接收原语"},{"key":"C","textEn":"Send primitive and execute primitive","textCn":"发送原语和执行原语"},{"key":"D","textEn":"Ready primitive and execute primitive","textCn":"就绪原语和执行原语"}],"answerKey":"B","explanationCn":"消息传递通信的基本操作是发送消息和接收消息，因此需要发送原语和接收原语。","explanationEn":""},{"id":"os-ch04-007","chapterId":"ch04","chapterName":"processes","stemEn":"When (), a process changes from the running state to the ready state.","stemCn":"当（）时，进程从执行状态转变为就绪状态。","options":[{"key":"A","textEn":"The process is selected by the scheduler","textCn":"进程被调度程序选中"},{"key":"B","textEn":"The time slice expires","textCn":"时间片到"},{"key":"C","textEn":"The process waits for an event","textCn":"等待某一事件"},{"key":"D","textEn":"The waited event occurs","textCn":"等待的事件发生"}],"answerKey":"B","explanationCn":"运行进程的时间片用完后会失去 CPU，但它仍具备运行条件，因此从执行状态转为就绪状态。","explanationEn":""},{"id":"os-ch04-008","chapterId":"ch04","chapterName":"processes","stemEn":"After a process is created, all created PCBs are linked into a sequence. This sequence is called ().","stemCn":"进程创建后，所有创建完成的 PCB 被链接成一个序列，这个序列称为（）。","options":[{"key":"A","textEn":"Ready queue","textCn":"就绪队列"},{"key":"B","textEn":"Running queue","textCn":"运行队列"},{"key":"C","textEn":"Job queue","textCn":"作业队列"},{"key":"D","textEn":"Blocked queue","textCn":"阻塞队列"}],"answerKey":"A","explanationCn":"进程创建完成并具备运行条件后，其 PCB 会进入就绪队列，等待处理器调度。","explanationEn":""},{"id":"os-ch04-009","chapterId":"ch04","chapterName":"processes","stemEn":"A long-term job scheduler controls ().","stemCn":"长（作业）调度程序控制（）。","options":[{"key":"A","textEn":"The degree of multiprogramming","textCn":"多道程序的道数"},{"key":"B","textEn":"The number of processes in the waiting queue","textCn":"等待队列中进程的个数"},{"key":"C","textEn":"The number of ready processes","textCn":"就绪进程的个数"},{"key":"D","textEn":"The execution time of a process","textCn":"进程执行的时间"}],"answerKey":"A","explanationCn":"长程调度决定哪些作业进入内存并成为进程，因此直接影响系统中同时存在的进程数量，也就是多道程序的道数。","explanationEn":""},{"id":"os-ch04-010","chapterId":"ch04","chapterName":"processes","stemEn":"In a single-processor system, if there are 10 processes at the same time, the maximum number of processes in the ready queue is ().","stemCn":"在单处理器系统中，如果同时存在 10 个进程，则处于就绪队列中的进程最多有（）个。","options":[{"key":"A","textEn":"10","textCn":"10"},{"key":"B","textEn":"1","textCn":"1"},{"key":"C","textEn":"8","textCn":"8"},{"key":"D","textEn":"9","textCn":"9"}],"answerKey":"D","explanationCn":"单处理器系统中同一时刻最多只有 1 个进程处于运行状态。若 10 个进程都不阻塞，则除正在运行的 1 个外，最多有 9 个处于就绪队列。","explanationEn":""},{"id":"os-ch05-001","chapterId":"ch05","chapterName":"threads","stemEn":"If a process has 100 threads, and all these threads are user-level threads, then the time slice occupied by each thread in system scheduling time is ().","stemCn":"若某一进程拥有 100 个线程，这些线程都属于用户级线程，则每一个线程在系统调度时间上占用的时间片是（）。","options":[{"key":"A","textEn":"1","textCn":"1"},{"key":"B","textEn":"1/100","textCn":"1/100"},{"key":"C","textEn":"100","textCn":"100"},{"key":"D","textEn":"0","textCn":"0"}],"answerKey":"B","explanationCn":"用户级线程对操作系统内核不可见，系统调度的对象仍是进程。该进程获得一个时间片后，100 个用户级线程在进程内部共享这个时间片，所以每个线程平均占 1/100。","explanationEn":""},{"id":"os-ch05-002","chapterId":"ch05","chapterName":"threads","stemEn":"In a many-to-one thread model, when one thread of a multithreaded process is blocked, ().","stemCn":"在多对一的线程模型中，当一个多线程进程的某个线程被阻塞后（）。","options":[{"key":"A","textEn":"The entire process will be blocked","textCn":"整个进程都将被阻塞"},{"key":"B","textEn":"The blocked thread will never be able to execute","textCn":"该阻塞线程将永远不可能在执行"},{"key":"C","textEn":"Other threads of the process can still continue running","textCn":"该进程的其他线程仍可继续运行"},{"key":"D","textEn":"The blocked thread will be revoked","textCn":"该阻塞线程将被撤销"}],"answerKey":"A","explanationCn":"多对一模型中多个用户级线程映射到一个内核线程，内核只能看到整个进程。若其中一个线程执行阻塞系统调用，整个进程都会被阻塞。","explanationEn":""},{"id":"os-ch05-003","chapterId":"ch05","chapterName":"threads","stemEn":"Which of the following statements is correct?","stemCn":"下面的叙述中，正确的是（）。","options":[{"key":"A","textEn":"Threads in the same process or in different processes can only execute serially","textCn":"同一进程或不同进程内的线程都只能串行执行"},{"key":"B","textEn":"Threads in the same process can only execute serially, while threads in different processes can execute concurrently","textCn":"同一进程内的线程只能串行执行，不同进程的线程可并发执行"},{"key":"C","textEn":"Threads in the same process or in different processes can execute concurrently","textCn":"同一进程或不同进程内的线程都可以并发执行"},{"key":"D","textEn":"Threads in the same process can execute concurrently, while threads in different processes can only execute serially","textCn":"同一进程内的线程可并发执行，不同进程的线程只能串行执行"}],"answerKey":"C","explanationCn":"线程是 CPU 调度和执行的基本单位。同一进程内的多个线程可以并发执行，不同进程中的线程也可以并发执行。","explanationEn":""},{"id":"os-ch05-004","chapterId":"ch05","chapterName":"threads","stemEn":"Which of the following statements is correct?","stemCn":"下面说法正确的是（）。","options":[{"key":"A","textEn":"Regardless of whether there are threads in the system, a process is an independent unit that owns resources","textCn":"不管系统中是否有线程，进程都是拥有资源的独立单位"},{"key":"B","textEn":"In a system that introduces threads, a process is still the basic unit of resource scheduling and allocation","textCn":"在引入线程的系统中，进程仍是资源调度和分派的基本单位"},{"key":"C","textEn":"A thread is the unit of resource allocation, and a process is the unit of scheduling and dispatching","textCn":"线程是资源分配的单位，进程是调度和分派的单位"},{"key":"D","textEn":"Whether the system-supported thread is a user-level thread or not, its switching requires kernel support","textCn":"不论是系统支持的线程还是用户级线程，其切换都需要内核的支持"}],"answerKey":"A","explanationCn":"进程是资源拥有和资源分配的基本单位，线程是处理器调度和分派的基本单位。用户级线程的切换可在用户态完成，不一定需要内核支持。","explanationEn":""},{"id":"os-ch05-005","chapterId":"ch05","chapterName":"threads","stemEn":"The main purpose of introducing threads is ().","stemCn":"引入线程的主要目的是（）。","options":[{"key":"A","textEn":"To achieve resource sharing","textCn":"实现资源共享"},{"key":"B","textEn":"To improve concurrency and reduce overhead","textCn":"提高并发程度同时降低开销"},{"key":"C","textEn":"To execute more tasks","textCn":"执行更多任务"},{"key":"D","textEn":"To speed up computation","textCn":"加快运算速度"}],"answerKey":"B","explanationCn":"线程作为轻量级执行单位，可以在同一进程内并发执行，并共享进程资源。相比创建和切换进程，线程的创建、撤销和切换开销更小。","explanationEn":""},{"id":"os-ch06-001","chapterId":"ch06","chapterName":"process scheduling","stemEn":"In a multiprogramming system on a single processor, when a process occupies the processor and how long it occupies the processor are determined by ().","stemCn":"在单处理器的多进程系统中，进程什么时候占用处理器以及决定占用时间的长短是由（）决定的。","options":[{"key":"A","textEn":"What function the process completes","textCn":"进程完成什么功能"},{"key":"B","textEn":"Process characteristics and process scheduling strategy","textCn":"进程特点和进程调度策略"},{"key":"C","textEn":"The total running time required by the process","textCn":"进程总共需要运行的时间"},{"key":"D","textEn":"The code length of the process","textCn":"进程相应的代码长度"}],"answerKey":"B","explanationCn":"进程能否占用 CPU 以及占用多久，主要取决于进程自身特点和系统采用的调度策略，例如时间片、优先级等。","explanationEn":""},{"id":"os-ch06-002","chapterId":"ch06","chapterName":"process scheduling","stemEn":"Which scheduling algorithm is favorable to CPU-bound jobs but unfavorable to I/O-bound jobs?","stemCn":"（）有利于 CPU 繁忙型的作业，而不利于 I/O 繁忙型的作业。","options":[{"key":"A","textEn":"First-Come, First-Served scheduling algorithm","textCn":"先来先服务调度算法"},{"key":"B","textEn":"Short job/process first algorithm","textCn":"短作业（进程）优先算法"},{"key":"C","textEn":"Priority scheduling algorithm","textCn":"优先权调度算法"},{"key":"D","textEn":"Round-robin scheduling algorithm","textCn":"时间片轮转调度算法"}],"answerKey":"A","explanationCn":"先来先服务算法容易让长时间占用 CPU 的作业先运行，CPU 繁忙型作业受益，而 I/O 繁忙型作业可能长期等待。","explanationEn":""},{"id":"os-ch06-003","chapterId":"ch06","chapterName":"process scheduling","stemEn":"The purpose of the round-robin scheduling algorithm is ().","stemCn":"时间片轮转调度算法是为了（）。","options":[{"key":"A","textEn":"Make the system more efficient","textCn":"使系统变得高效"},{"key":"B","textEn":"Let processes with higher priorities get timely responses","textCn":"优先级较高的进程得到及时响应"},{"key":"C","textEn":"Let multiple terminals get timely responses from the system","textCn":"多个终端能够得到系统及时响应"},{"key":"D","textEn":"Let the process requiring the least CPU time run first","textCn":"需要 CPU 时间最少的进程最先做"}],"answerKey":"C","explanationCn":"时间片轮转主要用于分时系统，使多个交互用户或终端能够轮流获得 CPU，从而得到较及时的响应。","explanationEn":""},{"id":"os-ch06-004","chapterId":"ch06","chapterName":"process scheduling","stemEn":"The priority whose value is determined when a process is created and does not change during the whole running time is ().","stemCn":"（）优先级是在创建进程时确定的，确定之后在整个运行期间不再改变。","options":[{"key":"A","textEn":"Static","textCn":"静态"},{"key":"B","textEn":"Short job","textCn":"短作业"},{"key":"C","textEn":"Dynamic","textCn":"动态"},{"key":"D","textEn":"First-Come, First-Served","textCn":"先来先服务"}],"answerKey":"A","explanationCn":"静态优先级在进程创建时确定，运行过程中保持不变；动态优先级会随等待时间、运行情况等因素变化。","explanationEn":""},{"id":"os-ch06-005","chapterId":"ch06","chapterName":"process scheduling","stemEn":"When CPU is allocated by the round-robin scheduling algorithm, after a running process uses up one time slice, its state becomes ().","stemCn":"采用时间片轮转调度算法分配 CPU 时，当处于运行状态的进程用完一个时间片后，它的状态是（）状态。","options":[{"key":"A","textEn":"Running","textCn":"运行"},{"key":"B","textEn":"Terminated","textCn":"消亡"},{"key":"C","textEn":"Blocked","textCn":"阻塞"},{"key":"D","textEn":"Ready","textCn":"就绪"}],"answerKey":"D","explanationCn":"时间片用完后，进程只是暂时失去 CPU，并没有等待事件，因此会从运行态转入就绪态，等待下一次调度。","explanationEn":""},{"id":"os-ch06-006","chapterId":"ch06","chapterName":"process scheduling","stemEn":"Among the following scheduling algorithms, which scheduling algorithm is absolutely preemptive?","stemCn":"下列调度算法中，（）调度算法是绝对可抢占的。","options":[{"key":"A","textEn":"First-Come, First-Served","textCn":"先来先服务"},{"key":"B","textEn":"Round-robin","textCn":"时间片轮转"},{"key":"C","textEn":"Shortest process first","textCn":"短进程优先"},{"key":"D","textEn":"Priority","textCn":"优先级"}],"answerKey":"B","explanationCn":"时间片轮转规定进程时间片用完后必须让出 CPU，因此天然具有抢占性。","explanationEn":""},{"id":"os-ch06-007","chapterId":"ch06","chapterName":"process scheduling","stemEn":"Among the following options, the reasonable time to lower a process priority is ().","stemCn":"下列选项中，降低进程优先级的合理时机是（）。","options":[{"key":"A","textEn":"The process changes from ready state to running state","textCn":"进程从就绪状态转为运行状态"},{"key":"B","textEn":"The process stays in the ready queue for a long time","textCn":"进程长期处于就绪队列"},{"key":"C","textEn":"The process has just completed an I/O operation and enters the ready queue","textCn":"进程刚完成 I/O 操作，进入就绪队列"},{"key":"D","textEn":"The process has used up its time slice","textCn":"进程时间片用完"}],"answerKey":"D","explanationCn":"进程用完时间片说明它已经获得了一段 CPU 服务，适当降低其优先级可以让其他进程获得运行机会。","explanationEn":""},{"id":"os-ch06-008","chapterId":"ch06","chapterName":"process scheduling","stemEn":"There are 4 jobs arriving at the same time, and each job has an execution time of 2 hours. They run on one processor in a single-channel manner. The average turnaround time is ().","stemCn":"设有 4 个作业同时到达，每个作业的执行时间均为 2h，它们在一台处理器上按单道方式运行，则平均周转时间为（）。","options":[{"key":"A","textEn":"2.5 h","textCn":"2.5h"},{"key":"B","textEn":"5 h","textCn":"5h"},{"key":"C","textEn":"8 h","textCn":"8h"},{"key":"D","textEn":"1 h","textCn":"1h"}],"answerKey":"B","explanationCn":"4 个作业完成时间分别为 2h、4h、6h、8h，平均周转时间为 (2+4+6+8)/4=5h。","explanationEn":""},{"id":"os-ch06-009","chapterId":"ch06","chapterName":"process scheduling","stemEn":"Assuming all processes in the system arrive at the same time, the scheduling algorithm that minimizes the average waiting time is ().","stemCn":"假设系统中所有的进程都是同时到达，则使进程平均等待时间最短的是（）调度算法。","options":[{"key":"A","textEn":"Priority","textCn":"优先级"},{"key":"B","textEn":"Round-robin","textCn":"时间片轮转"},{"key":"C","textEn":"First-Come, First-Served","textCn":"先来先服务"},{"key":"D","textEn":"Shortest job first","textCn":"短作业优先"}],"answerKey":"D","explanationCn":"当所有进程同时到达时，短作业优先会先执行运行时间短的作业，因此可以使平均等待时间最短。","explanationEn":""},{"id":"os-ch06-010","chapterId":"ch06","chapterName":"process scheduling","stemEn":"Which of the following criteria for selecting a process scheduling algorithm is incorrect?","stemCn":"下面关于选择进程调度算法的准则中不正确的是（）。","options":[{"key":"A","textEn":"Appropriately increase the waiting time of processes in the ready queue","textCn":"适当增加进程在就绪队列的等待时间"},{"key":"B","textEn":"Improve system throughput as much as possible","textCn":"尽可能提高系统的吞吐量"},{"key":"C","textEn":"Respond to interactive user requests as quickly as possible","textCn":"尽快响应交互式用户的请求"},{"key":"D","textEn":"Improve CPU utilization as much as possible","textCn":"尽量提高 CPU 利用率"}],"answerKey":"A","explanationCn":"调度算法通常追求减少等待时间、提高吞吐量、改善响应时间和提高 CPU 利用率。增加就绪队列等待时间不是正确准则。","explanationEn":""},{"id":"os-ch07-001","chapterId":"ch07","chapterName":"synchronization","stemEn":"Which of the following statements about a critical section is correct?","stemCn":"下列对临界区的论述中，正确的是（）。","options":[{"key":"A","textEn":"A critical section is the section of code in a process used to access shared resources.","textCn":"临界区是指进程中用于访问共享资源的那段代码"},{"key":"B","textEn":"A critical section is the section of code in a process used to implement process synchronization.","textCn":"临界区是指进程中用于实现进程同步的那段代码"},{"key":"C","textEn":"A critical section is the section of code in a process used to implement process mutual exclusion.","textCn":"临界区是指进程中用于实现进程互斥的那段代码"},{"key":"D","textEn":"A critical section is the section of code in a process used to implement process communication.","textCn":"临界区是指进程中用于实现进程通信的那段代码"}],"answerKey":"A","explanationCn":"临界区是进程中访问临界资源或共享资源的代码段。互斥、同步是对临界区访问进行控制的手段，不是临界区本身的定义。","explanationEn":""},{"id":"os-ch07-002","chapterId":"ch07","chapterName":"synchronization","stemEn":"If the initial value of a semaphore is 3, and after multiple P/V operations its current value is -1, this indicates that the number of processes waiting to enter the critical section is ().","stemCn":"若一个信号量的初值为 3，经过多次 P/V 操作以后当前值为 -1，此表示等待进入临界区的进程数是（）。","options":[{"key":"A","textEn":"4","textCn":"4"},{"key":"B","textEn":"3","textCn":"3"},{"key":"C","textEn":"1","textCn":"1"},{"key":"D","textEn":"2","textCn":"2"}],"answerKey":"C","explanationCn":"记录型信号量为负数时，其绝对值表示等待该资源的进程数。当前值为 -1，说明有 1 个进程正在等待。","explanationEn":""},{"id":"os-ch07-003","chapterId":"ch07","chapterName":"synchronization","stemEn":"For a semaphore K associated with a resource, the initial value is 3 and the current value is 1. If M denotes the number of available instances of the resource and N denotes the number of processes waiting for the resource, then M and N are respectively ().","stemCn":"设与某资源关联的信号量 K 初值为 3，当前值为 1。若 M 表示该资源的可用个数，N 表示等待该资源的进程数，则 M、N 分别是（）。","options":[{"key":"A","textEn":"1, 0","textCn":"1、0"},{"key":"B","textEn":"1, 2","textCn":"1、2"},{"key":"C","textEn":"0, 1","textCn":"0、1"},{"key":"D","textEn":"2, 0","textCn":"2、0"}],"answerKey":"A","explanationCn":"信号量当前值为正数时，表示当前可用资源数。K=1 说明还有 1 个资源可用，没有进程等待该资源。","explanationEn":""},{"id":"os-ch07-004","chapterId":"ch07","chapterName":"synchronization","stemEn":"A P operation may lead to ().","stemCn":"P 操作可能导致（）。","options":[{"key":"A","textEn":"Creation of a new process","textCn":"新进程创建"},{"key":"B","textEn":"Termination of a process","textCn":"进程结束"},{"key":"C","textEn":"Blocking of a process","textCn":"进程阻塞"},{"key":"D","textEn":"A process becoming ready","textCn":"进程就绪"}],"answerKey":"C","explanationCn":"P 操作用于申请资源，若申请后信号量小于 0，说明资源不足，当前进程会进入阻塞状态。","explanationEn":""},{"id":"os-ch07-005","chapterId":"ch07","chapterName":"synchronization","stemEn":"When a V operation wakes up a waiting process, the awakened process becomes in the () state.","stemCn":"用 V 操作唤醒一个等待进程时，被唤醒进程的变为（）状态。","options":[{"key":"A","textEn":"Ready","textCn":"就绪"},{"key":"B","textEn":"Waiting","textCn":"等待"},{"key":"C","textEn":"Completed","textCn":"完成"},{"key":"D","textEn":"Running","textCn":"运行"}],"answerKey":"A","explanationCn":"V 操作释放资源并可能唤醒等待进程。被唤醒的进程只是具备运行条件，还需等待 CPU 调度，因此进入就绪状态。","explanationEn":""},{"id":"os-ch07-006","chapterId":"ch07","chapterName":"synchronization","stemEn":"When semaphores are used to implement mutual exclusion, the initial value of the mutex semaphore is ().","stemCn":"在用信号量机制实现互斥时，互斥信号量的初值为（）。","options":[{"key":"A","textEn":"3","textCn":"3"},{"key":"B","textEn":"0","textCn":"0"},{"key":"C","textEn":"1","textCn":"1"},{"key":"D","textEn":"2","textCn":"2"}],"answerKey":"C","explanationCn":"互斥信号量用于控制同一时刻只有一个进程进入临界区，因此初值应为 1，表示最初临界区可被一个进程进入。","explanationEn":""},{"id":"os-ch07-007","chapterId":"ch07","chapterName":"synchronization","stemEn":"There are three processes sharing the same program segment, and at most two processes are allowed to enter this segment each time. If the PV operation synchronization mechanism is used, the possible range of semaphore S is ().","stemCn":"有三个进程共享同一程序段，而每次只允许两个进程进入该程序段，若用 PV 操作同步机制，则信号量 S 的取值范围是（）。","options":[{"key":"A","textEn":"3, 2, 1, 0","textCn":"3，2，1，0"},{"key":"B","textEn":"1, 0, -1, -2","textCn":"1，0，-1，-2"},{"key":"C","textEn":"2, 1, 0, -1, -2","textCn":"2，1，0，-1，-2"},{"key":"D","textEn":"2, 1, 0, -1","textCn":"2，1，0，-1"}],"answerKey":"D","explanationCn":"每次最多允许两个进程进入，因此信号量初值为 2。三个进程竞争时，最多有一个进程等待，所以最小值为 -1，取值范围为 2、1、0、-1。","explanationEn":""},{"id":"os-ch07-008","chapterId":"ch07","chapterName":"synchronization","stemEn":"For two concurrent processes, a mutex semaphore has an initial value of 1. If mutex = 0, then ().","stemCn":"对于两个并发进程，设互斥信号量为 mutex，初值为 1，若 mutex = 0，则（）。","options":[{"key":"A","textEn":"One process is in the critical section and the other process is waiting to enter.","textCn":"表示有一个进程进入临界区，另一个进程等待进入"},{"key":"B","textEn":"Two processes are in the critical section.","textCn":"表示有两个进程进入临界区"},{"key":"C","textEn":"No process is in the critical section.","textCn":"表示没有进程进入临界区"},{"key":"D","textEn":"One process is in the critical section.","textCn":"表示有一个进程进入临界区"}],"answerKey":"D","explanationCn":"互斥信号量初值为 1，执行一次 P 操作后变为 0，表示已有一个进程进入临界区。若还有进程等待，信号量会继续变为负数。","explanationEn":""},{"id":"os-ch07-009","chapterId":"ch07","chapterName":"synchronization","stemEn":"After executing a P operation on semaphore S, the condition for making a process enter the waiting queue is ().","stemCn":"对信号量 S 执行 P 操作后，使进程进入等待队列的条件是（）。","options":[{"key":"A","textEn":"S.value > 0","textCn":"S.value > 0"},{"key":"B","textEn":"S.value < 0","textCn":"S.value < 0"},{"key":"C","textEn":"S.value <= 0","textCn":"S.value <= 0"},{"key":"D","textEn":"S.value >= 0","textCn":"S.value >= 0"}],"answerKey":"B","explanationCn":"记录型信号量的 P 操作先使 S.value 减 1，若结果小于 0，说明资源不足，进程进入等待队列。","explanationEn":""},{"id":"os-ch07-010","chapterId":"ch07","chapterName":"synchronization","stemEn":"In an operating system, the reason for synchronizing concurrent processes is ().","stemCn":"在操作系统中，要对并发进程进行同步的原因是（）。","options":[{"key":"A","textEn":"Processes have structural properties.","textCn":"进程具有结构性"},{"key":"B","textEn":"Processes must finish within a limited time.","textCn":"进程必须在有限的时间内完成"},{"key":"C","textEn":"Concurrent processes are asynchronous.","textCn":"并发进程是异步的"},{"key":"D","textEn":"Processes have dynamic properties.","textCn":"进程具有动态性"}],"answerKey":"C","explanationCn":"并发进程的执行速度和推进顺序具有不确定性，即异步性。为了保证相关操作按正确次序执行，需要进行进程同步。","explanationEn":""},{"id":"os-ch08-001","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Which of the following situations may lead to deadlock?","stemCn":"下列情况可能导致死锁的是（）。","options":[{"key":"A","textEn":"Multiple processes compete for resources and circular waiting occurs.","textCn":"多个进程竞争资源出现了循环等待"},{"key":"B","textEn":"Multiple processes compete to use shared devices.","textCn":"多个进程竞争使用共享型的设备"},{"key":"C","textEn":"A process enters an infinite loop.","textCn":"一个进程进入死循环"},{"key":"D","textEn":"A process releases resources.","textCn":"进程释放资源"}],"answerKey":"A","explanationCn":"死锁的典型表现是多个进程互相等待对方占有的资源，形成循环等待。共享型设备竞争或进程死循环本身不一定构成死锁。","explanationEn":""},{"id":"os-ch08-002","chapterId":"ch08","chapterName":"deadlocks","stemEn":"In an operating system, deadlock refers to ().","stemCn":"在操作系统中，死锁出现是指（）。","options":[{"key":"A","textEn":"A serious failure occurs in the computer system.","textCn":"计算机系统发生重大故障"},{"key":"B","textEn":"The number of resources is far less than the number of processes.","textCn":"资源个数远远小于进程数"},{"key":"C","textEn":"Several processes wait indefinitely for other processes to release the resources they occupy because of competing for resources.","textCn":"若干进程因竞争资源而无限等待其他进程释放已占有的资源"},{"key":"D","textEn":"The resources requested by processes at the same time exceed the total number of resources.","textCn":"进程同时申请的资源数超过资源总数"}],"answerKey":"C","explanationCn":"死锁是指一组进程因互相等待对方释放资源而长期阻塞，若无外力干预无法继续推进。","explanationEn":""},{"id":"os-ch08-003","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Allocating all resources at once can prevent deadlock because it destroys which of the four necessary conditions for deadlock?","stemCn":"一次分配所有资源的方法可以预防死锁的发生，它破坏的死锁四个必要条件中的（）。","options":[{"key":"A","textEn":"Mutual exclusion","textCn":"互斥"},{"key":"B","textEn":"Circular wait","textCn":"环路等待"},{"key":"C","textEn":"No preemption","textCn":"非剥夺"},{"key":"D","textEn":"Hold and wait","textCn":"请求并保持"}],"answerKey":"D","explanationCn":"一次性分配所有资源要求进程在运行前申请完所需资源，运行中不再边占有边等待新资源，因此破坏了请求并保持条件。","explanationEn":""},{"id":"os-ch08-004","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Deadlock avoidance is implemented by taking measures based on ().","stemCn":"死锁的避免是根据（）采取措施实现的。","options":[{"key":"A","textEn":"Allocating enough system resources","textCn":"配置足够的系统资源"},{"key":"B","textEn":"Destroying one of the four necessary conditions for deadlock","textCn":"破坏死锁的四个必要条件之一"},{"key":"C","textEn":"Making the process execution order reasonable","textCn":"使进程的推进顺序合理"},{"key":"D","textEn":"Preventing the system from entering an unsafe state","textCn":"防止系统进入不安全状态"}],"answerKey":"D","explanationCn":"死锁避免不是直接破坏必要条件，而是在资源分配前判断系统是否会进入不安全状态，从而避免可能导致死锁的分配。","explanationEn":""},{"id":"os-ch08-005","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Which of the following descriptions about a resource-allocation graph is correct?","stemCn":"以下有关资源分配图的描述中正确的是（）。","options":[{"key":"A","textEn":"Directed edges include allocation edges from processes to resource classes and request edges from resource classes to processes.","textCn":"有向边包括进程指向资源类的分配边和资源类指向进程申请边两类"},{"key":"B","textEn":"Circular nodes represent resource classes.","textCn":"圆圈节点表示资源类"},{"key":"C","textEn":"Rectangular boxes represent processes, and dots inside them represent processes requesting the same type of resource.","textCn":"矩形框表示进程，其中圆点表示申请同一类资源的各个进程"},{"key":"D","textEn":"A resource-allocation graph is a directed graph used to represent the state between system resources and processes at a certain time.","textCn":"资源分配图是一个有向图，用于表示某时刻系统资源与进程之间的状态"}],"answerKey":"D","explanationCn":"资源分配图用有向图描述进程与资源之间的申请和分配关系。通常圆圈表示进程，矩形表示资源类，边的方向也有固定含义。","explanationEn":""},{"id":"os-ch08-006","chapterId":"ch08","chapterName":"deadlocks","stemEn":"The relationship between deadlock and a safe state is ().","stemCn":"死锁与安全状态的关系是（）。","options":[{"key":"A","textEn":"An unsafe state is a deadlock state.","textCn":"不安全状态就是死锁状态"},{"key":"B","textEn":"A safe state may become a deadlock state.","textCn":"安全状态有可能成为死锁状态"},{"key":"C","textEn":"A deadlock state must be an unsafe state.","textCn":"死锁状态一定是不安全状态"},{"key":"D","textEn":"A deadlock state may be a safe state.","textCn":"死锁状态有可能是安全状态"}],"answerKey":"C","explanationCn":"死锁状态一定是不安全状态，但不安全状态不一定已经发生死锁，它只是可能发展为死锁。","explanationEn":""},{"id":"os-ch08-007","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Among the following solutions to deadlock, which belongs to deadlock avoidance?","stemCn":"在下列死锁的解决方法中，属于死锁避免策略的是（）。","options":[{"key":"A","textEn":"Resource ordered allocation method","textCn":"资源有序分配法"},{"key":"B","textEn":"Deadlock detection method","textCn":"死锁检测法"},{"key":"C","textEn":"Destroying the non-preemption condition","textCn":"破坏不可剥夺条件"},{"key":"D","textEn":"Banker's algorithm","textCn":"银行家算法"}],"answerKey":"D","explanationCn":"银行家算法在资源分配前进行安全性检查，避免系统进入不安全状态，因此属于死锁避免方法。","explanationEn":""},{"id":"os-ch08-008","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Which of the following is usually not used to recover from deadlock?","stemCn":"解除死锁通常不采用的方法是（）。","options":[{"key":"A","textEn":"Preempt resources from deadlocked processes.","textCn":"从死锁进程处抢夺资源"},{"key":"B","textEn":"Preempt resources from non-deadlocked processes.","textCn":"从非死锁进程处抢夺资源"},{"key":"C","textEn":"Terminate all deadlocked processes.","textCn":"终止所有死锁进程"},{"key":"D","textEn":"Terminate one deadlocked process.","textCn":"终止一个死锁进程"}],"answerKey":"C","explanationCn":"解除死锁常用资源剥夺或终止进程等方法，但通常不直接终止所有死锁进程，因为代价过大，实际可逐个终止或选择性恢复。","explanationEn":""},{"id":"os-ch08-009","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Among the four necessary conditions for deadlock, the one that cannot be destroyed is ().","stemCn":"死锁的四个必要条件中，无法破坏的是（）。","options":[{"key":"A","textEn":"No preemption","textCn":"非剥夺"},{"key":"B","textEn":"Mutual exclusion","textCn":"互斥"},{"key":"C","textEn":"Hold and wait","textCn":"请求并保持"},{"key":"D","textEn":"Circular wait","textCn":"环路等待"}],"answerKey":"B","explanationCn":"许多资源本身具有互斥使用特性，例如打印机等独占设备，这一条件通常无法从根本上破坏。","explanationEn":""},{"id":"os-ch08-010","chapterId":"ch08","chapterName":"deadlocks","stemEn":"If three concurrent processes in a system each require four identical resources, the minimum number of resources that guarantees no deadlock is ().","stemCn":"某系统中有三个并发进程都需要四个同类资源，该系统不会发生死锁的最少资源是（）。","options":[{"key":"A","textEn":"9","textCn":"9"},{"key":"B","textEn":"12","textCn":"12"},{"key":"C","textEn":"11","textCn":"11"},{"key":"D","textEn":"10","textCn":"10"}],"answerKey":"D","explanationCn":"若有 n 个进程，每个最多需要 m 个同类资源，则避免死锁的最少资源数为 n(m-1)+1。本题为 3×(4-1)+1=10。","explanationEn":""},{"id":"os-ch09-001","chapterId":"ch09","chapterName":"memory management","stemEn":"The process of converting logical addresses used in a job space into physical memory addresses is called ().","stemCn":"把作业空间中使用的逻辑地址变为内存中物理地址称为（）。","options":[{"key":"A","textEn":"Physicalization","textCn":"物理化"},{"key":"B","textEn":"Logicalization","textCn":"逻辑化"},{"key":"C","textEn":"Relocation","textCn":"重定位"},{"key":"D","textEn":"Loading","textCn":"加载"}],"answerKey":"C","explanationCn":"重定位就是把程序中的逻辑地址转换为内存中的物理地址，使程序能够在实际内存位置运行。","explanationEn":""},{"id":"os-ch09-002","chapterId":"ch09","chapterName":"memory management","stemEn":"Memory protection needs to be completed by () to ensure that a process space is not illegally accessed.","stemCn":"内存保护需要由（）完成，以保证进程空间不被非法访问。","options":[{"key":"A","textEn":"Operating system","textCn":"操作系统"},{"key":"B","textEn":"Hardware mechanism","textCn":"硬件机构"},{"key":"C","textEn":"Operating system or hardware mechanism independently","textCn":"操作系统或者硬件机构独立完成"},{"key":"D","textEn":"Cooperation between operating system and hardware mechanism","textCn":"操作系统和硬件机构合作"}],"answerKey":"D","explanationCn":"内存保护既需要操作系统设置访问权限和边界信息，也需要硬件在地址访问时进行检查，因此通常由二者配合完成。","explanationEn":""},{"id":"os-ch09-003","chapterId":"ch09","chapterName":"memory management","stemEn":"Dynamic relocation is performed during the () of a job.","stemCn":"动态重定位是在作业的（）中进行的。","options":[{"key":"A","textEn":"Compilation process","textCn":"编译过程"},{"key":"B","textEn":"Linking process","textCn":"链接过程"},{"key":"C","textEn":"Loading process","textCn":"装入过程"},{"key":"D","textEn":"Execution process","textCn":"执行过程"}],"answerKey":"D","explanationCn":"动态重定位是在程序执行时才把逻辑地址转换为物理地址，通常依靠重定位寄存器等硬件支持完成。","explanationEn":""},{"id":"os-ch09-004","chapterId":"ch09","chapterName":"memory management","stemEn":"Which storage management method does not produce external fragmentation?","stemCn":"不会产生外碎片的存储管理是（）。","options":[{"key":"A","textEn":"None of them","textCn":"都不会"},{"key":"B","textEn":"Segmented storage management","textCn":"分段式存储管理"},{"key":"C","textEn":"Dynamic partition allocation management","textCn":"动态分区分配管理"},{"key":"D","textEn":"Paged storage management","textCn":"分页式存储管理"}],"answerKey":"D","explanationCn":"分页以固定大小的页框为单位离散分配，不要求连续内存，因此不会产生外部碎片，但可能产生页内碎片。","explanationEn":""},{"id":"os-ch09-005","chapterId":"ch09","chapterName":"memory management","stemEn":"In partition management, when the best-fit allocation algorithm is used, idle partitions are registered in the free partition table in the order of ().","stemCn":"分区管理中采用“最佳适应”分配算法时，把空闲区按（）次序登记在空闲区表中。","options":[{"key":"A","textEn":"Increasing length","textCn":"长度递增"},{"key":"B","textEn":"Decreasing length","textCn":"长度递减"},{"key":"C","textEn":"Decreasing address","textCn":"地址递减"},{"key":"D","textEn":"Increasing address","textCn":"地址递增"}],"answerKey":"A","explanationCn":"最佳适应算法每次选择能满足要求的最小空闲分区，因此空闲区表通常按分区长度递增排列，便于快速找到最合适的空闲区。","explanationEn":""},{"id":"os-ch09-006","chapterId":"ch09","chapterName":"memory management","stemEn":"Pages in a paging system are perceived by ().","stemCn":"分页系统中的页面是被（）感知的。","options":[{"key":"A","textEn":"Operating system","textCn":"操作系统所感知的"},{"key":"B","textEn":"Compiler system","textCn":"编译系统所感知的"},{"key":"C","textEn":"Linker loader","textCn":"链接装配程序所感知的"},{"key":"D","textEn":"User","textCn":"用户所感知的"}],"answerKey":"A","explanationCn":"分页是操作系统和硬件进行内存管理的方式，对用户通常是透明的，用户并不直接感知页的划分。","explanationEn":""},{"id":"os-ch09-007","chapterId":"ch09","chapterName":"memory management","stemEn":"For relocatable storage management, it should ().","stemCn":"对重定位存储管理方式，应（）。","options":[{"key":"A","textEn":"Set two relocation registers for each program","textCn":"为每道程序设置两个重定位寄存器"},{"key":"B","textEn":"Set one relocation register in the whole system","textCn":"在整个系统中设置一个重定位寄存器"},{"key":"C","textEn":"Set one relocation register for each program and its data","textCn":"为每道程序和数据都设置一个重定位寄存器"},{"key":"D","textEn":"Set one relocation register for each program","textCn":"为每道程序设置一个重定位寄存器"}],"answerKey":"B","explanationCn":"CPU 同一时刻只执行一个进程的指令，系统只需设置一个重定位寄存器，在进程切换时重新装入对应的重定位值即可。","explanationEn":""},{"id":"os-ch09-008","chapterId":"ch09","chapterName":"memory management","stemEn":"In paged storage management, memory is allocated ().","stemCn":"在分页存储管理中，内存的分配是（）。","options":[{"key":"A","textEn":"Allocated according to the size of logical records","textCn":"以逻辑记录大小进行分配"},{"key":"B","textEn":"Allocated according to the size of the job","textCn":"以作业的大小分配"},{"key":"C","textEn":"Allocated in units of page frames","textCn":"以页框为单位进行分配"},{"key":"D","textEn":"Allocated according to physical segments","textCn":"以物理段进行分配"}],"answerKey":"C","explanationCn":"分页管理中逻辑地址按页划分，物理内存按页框划分，内存分配以页框为基本单位。","explanationEn":""},{"id":"os-ch09-009","chapterId":"ch09","chapterName":"memory management","stemEn":"In segmented storage management, ().","stemCn":"在分段存储管理方式中，（）。","options":[{"key":"A","textEn":"Every segment has equal length","textCn":"每段是等长的"},{"key":"B","textEn":"Segments must be non-contiguous","textCn":"段与段之间必定不连续"},{"key":"C","textEn":"Segments must be contiguous","textCn":"段与段之间必定连续"},{"key":"D","textEn":"Storage is allocated in units of segments, and each segment is a contiguous storage area","textCn":"以段为单位，每段是一个连续存储区"}],"answerKey":"D","explanationCn":"分段管理以逻辑段为单位分配内存，每个段内部必须连续，但不同段之间不要求连续。","explanationEn":""},{"id":"os-ch09-010","chapterId":"ch09","chapterName":"memory management","stemEn":"A computer using dynamic partition storage management has a main memory capacity of 55 MB, initially empty. Using the best-fit algorithm, the allocation and release sequence is: allocate 15 MB, allocate 30 MB, release 15 MB, allocate 8 MB, allocate 6 MB. At this time, the size of the largest free partition in main memory is ().","stemCn":"某基于动态分区存储管理的计算机，其主存容量为55MB（初始为空），采用最佳适配（Best Fit）算法，分配和释放的顺序为：分配15MB，分配30MB，释放15MB，分配8MB，分配6MB，此时主存中最大空闲分区的大小是（）。","options":[{"key":"A","textEn":"9 MB","textCn":"9MB"},{"key":"B","textEn":"15 MB","textCn":"15MB"},{"key":"C","textEn":"10 MB","textCn":"10MB"},{"key":"D","textEn":"7 MB","textCn":"7MB"}],"answerKey":"A","explanationCn":"初始55MB，分配15MB和30MB后剩10MB；释放15MB后有15MB和10MB两个空闲区。最佳适应分配8MB选10MB区剩2MB，再分配6MB选15MB区剩9MB，所以最大空闲区为9MB。","explanationEn":""},{"id":"os-ch10-001","chapterId":"ch10","chapterName":"virtual memory","stemEn":"Which of the following statements about conventional memory is correct?","stemCn":"下列关于常规存储器的论述中，正确的论述是（）。","options":[{"key":"A","textEn":"Before running, the program must be fully loaded into memory, and it must remain in memory throughout execution.","textCn":"作业在运行前，必须全部装入内存，且在运行过程中也一直驻留内存"},{"key":"B","textEn":"Before running, the job does not have to be fully loaded into memory, but it must remain in memory throughout execution.","textCn":"作业在运行前，不必全部装入内存，但在运行过程中必须一直驻留内存"},{"key":"C","textEn":"Before running, the job does not have to be fully loaded into memory, and it does not have to remain in memory throughout execution.","textCn":"作业在运行前，不必全部装入内存，且在运行过程中也不必一直驻留内存"},{"key":"D","textEn":"Before running, the job must be fully loaded into memory, but it does not have to remain in memory throughout execution.","textCn":"作业在运行前，必须全部装入内存，但在运行过程中不必一直驻留内存"}],"answerKey":"A","explanationCn":"常规存储管理要求作业运行前全部装入内存，并且运行期间通常一直驻留内存，这也是虚拟存储技术要突破的限制。","explanationEn":""},{"id":"os-ch10-002","chapterId":"ch10","chapterName":"virtual memory","stemEn":"To make the virtual memory system effectively play its expected role, the running program should have which characteristic?","stemCn":"为使虚存系统有效地发挥其预期的作用，所运行的程序应具有的特性是（）。","options":[{"key":"A","textEn":"The program should not contain too many I/O operations.","textCn":"该程序不应含有过多的I/O操作"},{"key":"B","textEn":"The program should not have too much instruction correlation.","textCn":"该程序的指令相关性不应过多"},{"key":"C","textEn":"The size of the program should not exceed the actual memory capacity.","textCn":"该程序的大小不应超过实际的内存容量"},{"key":"D","textEn":"The program should have good locality.","textCn":"该程序应具有较好的局部性"}],"answerKey":"D","explanationCn":"虚拟存储依赖程序局部性原理，若程序在一段时间内集中访问少量页面，就能减少缺页次数并提高运行效率。","explanationEn":""},{"id":"os-ch10-003","chapterId":"ch10","chapterName":"virtual memory","stemEn":"Which of the following is the difference between demand paging storage management and basic paging storage management?","stemCn":"（）是请求分页存储管理方式和基本分页存储管理方式的区别。","options":[{"key":"A","textEn":"Address relocation","textCn":"地址重定向"},{"key":"B","textEn":"The job does not have to be loaded into a contiguous area.","textCn":"不必将作业装入连续区域"},{"key":"C","textEn":"The whole job does not have to be loaded into memory.","textCn":"不必将作业全部装入内存"},{"key":"D","textEn":"Using TLB technology.","textCn":"采用 TLB（快表）技术"}],"answerKey":"C","explanationCn":"基本分页通常要求作业全部装入内存后运行，而请求分页允许只装入当前需要的页面，缺页时再调入。","explanationEn":""},{"id":"os-ch10-004","chapterId":"ch10","chapterName":"virtual memory","stemEn":"The basis of a virtual memory management system is the program's () theory.","stemCn":"虚拟存储管理系统的基础是程序的（）理论。","options":[{"key":"A","textEn":"Dynamic property","textCn":"动态性"},{"key":"B","textEn":"Global property","textCn":"全局性"},{"key":"C","textEn":"Virtual property","textCn":"虚拟性"},{"key":"D","textEn":"Locality","textCn":"局部性"}],"answerKey":"D","explanationCn":"虚拟存储管理建立在程序局部性原理之上，即程序在一段时间内往往集中访问有限的代码和数据区域。","explanationEn":""},{"id":"os-ch10-005","chapterId":"ch10","chapterName":"virtual memory","stemEn":"In the page table of demand paging management, several additional items such as the modified bit and the access bit are added for reference by ().","stemCn":"在请求分页管理的页表中增加了若干项信息，其中修改位和访问位供（）参考。","options":[{"key":"A","textEn":"Program access","textCn":"程序访问"},{"key":"B","textEn":"Page allocation","textCn":"分配页面"},{"key":"C","textEn":"Replacement algorithm","textCn":"置换算法"},{"key":"D","textEn":"Page loading","textCn":"调入页面"}],"answerKey":"C","explanationCn":"访问位反映页面是否近期被访问，修改位反映页面是否被写过，这些信息常用于页面置换算法选择淘汰页面。","explanationEn":""},{"id":"os-ch10-006","chapterId":"ch10","chapterName":"virtual memory","stemEn":"In a virtual paging storage management system, if the page accessed by a process is not in main memory and there is no available frame in main memory, the correct processing sequence is ().","stemCn":"在虚拟分页存储管理系统中，若进程访问的页面不在主存，且主存中没有可用的空闲帧时，系统正确的处理顺序为（）。","options":[{"key":"A","textEn":"Decide the page to be eliminated → page-in → page fault interrupt → page-out","textCn":"决定淘汰页→页面调入→缺页中断→页面调出"},{"key":"B","textEn":"Decide the page to be eliminated → page-out → page fault interrupt → page-in","textCn":"决定淘汰页→页面调出→缺页中断→页面调入"},{"key":"C","textEn":"Page fault interrupt → decide the page to be eliminated → page-out → page-in","textCn":"缺页中断→决定淘汰页→页面调出→页面调入"},{"key":"D","textEn":"Page fault interrupt → decide the page to be eliminated → page-in → page-out","textCn":"缺页中断→决定淘汰页→页面调入→页面调出"}],"answerKey":"C","explanationCn":"访问页面不在内存时先产生缺页中断；若无空闲页框，需要先按置换算法确定淘汰页并调出，再把所需页面调入内存。","explanationEn":""},{"id":"os-ch10-007","chapterId":"ch10","chapterName":"virtual memory","stemEn":"The main cause of thrashing in a system is ().","stemCn":"系统产生抖动主要原因是（）。","options":[{"key":"A","textEn":"The memory space is too small.","textCn":"内存空间太小"},{"key":"B","textEn":"The CPU runs too slowly.","textCn":"CPU运行速度太慢"},{"key":"C","textEn":"The CPU scheduling algorithm is unreasonable.","textCn":"CPU调度算法不合理"},{"key":"D","textEn":"The page replacement algorithm is unreasonable.","textCn":"页面置换算法不合理"}],"answerKey":"D","explanationCn":"抖动是由于页面频繁调入调出导致的，直接原因通常是页面置换策略或驻留集分配不当，使进程缺页率过高。","explanationEn":""},{"id":"os-ch10-008","chapterId":"ch10","chapterName":"virtual memory","stemEn":"When a page fault occurs during process execution, after the operating system handles it, the process should execute which instruction?","stemCn":"进程在执行中发生了缺页中断，经操作系统处理后，应让其执行（）指令。","options":[{"key":"A","textEn":"The instruction after the interrupted instruction","textCn":"被中断的后一条"},{"key":"B","textEn":"The first instruction at startup","textCn":"启动时的那一条"},{"key":"C","textEn":"The instruction before the interrupted instruction","textCn":"被中断的前一条"},{"key":"D","textEn":"The interrupted instruction","textCn":"被中断的那一条"}],"answerKey":"D","explanationCn":"缺页中断发生时，导致中断的指令尚未成功完成；页面调入后应重新执行被中断的那条指令。","explanationEn":""},{"id":"os-ch10-009","chapterId":"ch10","chapterName":"virtual memory","stemEn":"Considering page replacement algorithms, if the system has m physical frames allocated, initially all empty, and the page reference string has length p containing n distinct page numbers, regardless of the algorithm used, the number of page faults will not be less than ().","stemCn":"考虑页面置换算法，系统有m个物理块供调度，初始时全空，页面引用串长度为p，包含了n个不同的页号，无论用什么算法，缺页次数不会少于（）。","options":[{"key":"A","textEn":"min(m, n)","textCn":"min(m, n)"},{"key":"B","textEn":"m","textCn":"m"},{"key":"C","textEn":"p","textCn":"p"},{"key":"D","textEn":"n","textCn":"n"}],"answerKey":"D","explanationCn":"引用串中有n个不同页号，每个不同页面第一次被访问时必然不在内存中，因此至少会产生n次缺页。","explanationEn":""},{"id":"os-ch10-010","chapterId":"ch10","chapterName":"virtual memory","stemEn":"A virtual memory system uses paged memory management and the LRU page replacement algorithm. Given the page reference string 1, 8, 1, 7, 8, 2, 7, 2, 1, 8, 3, 8, 2, 1, 3, 1, 7, 1, 3, 7, and assuming memory capacity is 4 pages and is initially empty, the number of page faults is ().","stemCn":"某虚拟存储器系统采用页式内存管理，使用LRU页面替换算法，考虑页面访问地址序列：1 8 1 7 8 2 7 2 1 8 3 8 2 1 3 1 7 1 3 7，假定内存容量为4个页面，开始时是空的，则缺页次数是（）。","options":[{"key":"A","textEn":"6","textCn":"6"},{"key":"B","textEn":"7","textCn":"7"},{"key":"C","textEn":"4","textCn":"4"},{"key":"D","textEn":"5","textCn":"5"}],"answerKey":"A","explanationCn":"内存初始为空，前面依次装入1、8、7、2产生4次缺页；之后访问3时淘汰最近最久未使用的7，第17次再访问7时淘汰8，共产生6次缺页。","explanationEn":""},{"id":"os-ch11-001","chapterId":"ch11","chapterName":"File System","stemEn":"From the user's perspective, the purpose of introducing a file system into an operating system is to ____.","stemCn":"从用户的观点看，操作系统中引入文件系统的目的是（）。","options":[{"key":"A","textEn":"Implement file access by name","textCn":"实现对文件的按名存取"},{"key":"B","textEn":"Protect user data","textCn":"保护用户数据"},{"key":"C","textEn":"Save user and system files and data","textCn":"保存用户和系统文件及数据"},{"key":"D","textEn":"Implement virtual storage","textCn":"实现虚拟存储"}],"answerKey":"A","explanationCn":"从用户角度看，文件系统最直接的作用是通过文件名来访问文件，使用户不必关心文件在磁盘上的具体物理位置。","explanationEn":""},{"id":"os-ch11-002","chapterId":"ch11","chapterName":"File System","stemEn":"In a file system, the proper place to store file access control information is ____.","stemCn":"文件系统中，文件访问控制信息存储的合理位置是（）。","options":[{"key":"A","textEn":"File allocation table","textCn":"文件分配表"},{"key":"B","textEn":"File control block","textCn":"文件控制块"},{"key":"C","textEn":"User password table","textCn":"用户口令表"},{"key":"D","textEn":"System registry table","textCn":"系统注册表"}],"answerKey":"B","explanationCn":"文件控制块 FCB 保存文件的相关属性和管理信息，其中可以包含访问权限、访问控制等信息。","explanationEn":""},{"id":"os-ch11-003","chapterId":"ch11","chapterName":"File System","stemEn":"Among the following file physical structures, the one suitable for random access and easy file expansion is ____.","stemCn":"下列文件物理结构中，适合随机访问且易于文件扩展的是（）。","options":[{"key":"A","textEn":"Linked structure with fixed-length disk blocks","textCn":"链接结构且磁盘块定长"},{"key":"B","textEn":"Indexed structure","textCn":"索引结构"},{"key":"C","textEn":"Linked structure with variable-length disk blocks","textCn":"链接结构且磁盘块变长"},{"key":"D","textEn":"Contiguous structure","textCn":"连续结构"}],"answerKey":"B","explanationCn":"索引结构通过索引块记录文件各数据块的位置，既能随机访问，又便于增加新的数据块。连续结构随机访问方便但扩展困难，链接结构易扩展但不便随机访问。","explanationEn":""},{"id":"os-ch11-004","chapterId":"ch11","chapterName":"File System","stemEn":"On a disk, the physical file structure most likely to cause storage fragmentation is ____.","stemCn":"在磁盘上，最容易导致存储碎片发生的物理文件结构是（）。","options":[{"key":"A","textEn":"Sequential structure","textCn":"顺序结构"},{"key":"B","textEn":"Implicit linked structure","textCn":"隐式链接"},{"key":"C","textEn":"Indexed structure","textCn":"索引结构"},{"key":"D","textEn":"Explicit linked structure","textCn":"显示链接"}],"answerKey":"A","explanationCn":"顺序结构要求文件占用连续磁盘空间，文件增删后容易产生外部碎片。链接结构和索引结构可以离散分配，通常不易产生这种外部碎片。","explanationEn":""},{"id":"os-ch11-005","chapterId":"ch11","chapterName":"File System","stemEn":"A file system uses two-level indexed allocation. If each disk block is 1 KB and each block number occupies 4 B, the maximum size of a single file in this system is ____.","stemCn":"文件系统采用两级索引分配方式，如果每个磁盘块的大小为1KB，每个盘块号占4B，则该系统中，单个文件的最大长度是（）。","options":[{"key":"A","textEn":"128 MB","textCn":"128MB"},{"key":"B","textEn":"64 MB","textCn":"64MB"},{"key":"C","textEn":"32 MB","textCn":"32MB"},{"key":"D","textEn":"None of the above","textCn":"以上答案都不对"}],"answerKey":"B","explanationCn":"一个索引块可存放 1KB/4B=256 个盘块号。两级索引可定位 256×256 个数据块，每块 1KB，所以最大文件长度为 256×256×1KB=64MB。","explanationEn":""},{"id":"os-ch11-006","chapterId":"ch11","chapterName":"File System","stemEn":"When a file system creates a file, it establishes a ____ for it.","stemCn":"文件系统在创建一个文件时，为它建立一个（）。","options":[{"key":"A","textEn":"Logical space","textCn":"逻辑空间"},{"key":"B","textEn":"Directory file","textCn":"目录文件"},{"key":"C","textEn":"File directory entry","textCn":"文件目录项"},{"key":"D","textEn":"Logical structure","textCn":"逻辑结构"}],"answerKey":"C","explanationCn":"创建文件时，系统需要为该文件建立目录项，也就是记录文件名、位置、属性等信息的 FCB 或目录记录。","explanationEn":""},{"id":"os-ch11-007","chapterId":"ch11","chapterName":"File System","stemEn":"The purpose of using a multi-level directory structure in a file system is to ____.","stemCn":"文件系统采用多级目录结构的目的是（）。","options":[{"key":"A","textEn":"Reduce system overhead","textCn":"减少系统开销"},{"key":"B","textEn":"Shorten transfer time","textCn":"缩短传送时间"},{"key":"C","textEn":"Save storage space","textCn":"节省存储空间"},{"key":"D","textEn":"Resolve naming conflicts","textCn":"解决命名冲突"}],"answerKey":"D","explanationCn":"多级目录允许不同目录下存在同名文件，通过路径区分文件，从而解决命名冲突问题。","explanationEn":""},{"id":"os-ch11-008","chapterId":"ch11","chapterName":"File System","stemEn":"The information stored in a file directory is ____.","stemCn":"文件目录存放的信息是（）。","options":[{"key":"A","textEn":"The directory entries of all subdirectory files and data files in this directory","textCn":"该目录中所有子目录文件和数据文件的目录"},{"key":"B","textEn":"The data information stored in a certain file","textCn":"某一文件存放的数据信息"},{"key":"C","textEn":"The file directory of a certain file","textCn":"某一文件的文件目录"},{"key":"D","textEn":"All data file directories in this directory","textCn":"该目录中所有数据文件目录"}],"answerKey":"A","explanationCn":"文件目录本质上是目录项的有序集合，其中既可以包含子目录的目录项，也可以包含普通数据文件的目录项。","explanationEn":""},{"id":"os-ch11-009","chapterId":"ch11","chapterName":"File System","stemEn":"A bitmap can be used for ____.","stemCn":"位示图可用于（）。","options":[{"key":"A","textEn":"File security","textCn":"文件的保密"},{"key":"B","textEn":"Searching file directories","textCn":"文件目录的查找"},{"key":"C","textEn":"Management of disk space","textCn":"磁盘空间的管理"},{"key":"D","textEn":"Management of memory space","textCn":"内存空间的管理"}],"answerKey":"C","explanationCn":"位示图常用于记录磁盘块的空闲或占用状态，因此可用于磁盘空间管理。","explanationEn":""},{"id":"os-ch11-010","chapterId":"ch11","chapterName":"File System","stemEn":"In a file system, each FCB occupies 64 B, each disk block is 1 KB, and a single-level directory is used. If the file directory contains 3200 directory entries, the average number of disk accesses needed to find a file is ____.","stemCn":"一个文件系统中，其FCB占64B，一个盘块大小为1KB，采用一级目录。假定文件目录中有3200个目录项。则查找一个文件平均需要（）次访问磁盘。","options":[{"key":"A","textEn":"100","textCn":"100"},{"key":"B","textEn":"50","textCn":"50"},{"key":"C","textEn":"200","textCn":"200"},{"key":"D","textEn":"54","textCn":"54"}],"answerKey":"A","explanationCn":"一个盘块可存放 1KB/64B=16 个目录项，3200 个目录项共占 200 个目录块。一级目录顺序查找时平均访问一半目录块，所以平均访问 100 次。","explanationEn":""},{"id":"os-ch12-001","chapterId":"ch12","chapterName":"Secondary Storage","stemEn":"The read/write unit of a disk is ( ).","stemCn":"磁盘的读写单位是（ ）。","options":{"A":{"textEn":"Sector","textCn":"扇区"},"B":{"textEn":"Byte","textCn":"字节"},"C":{"textEn":"Cluster","textCn":"簇"},"D":{"textEn":"Block","textCn":"块"}},"answerKey":"A","explanationCn":"磁盘进行物理读写时通常以扇区为基本单位，扇区是磁盘上能够独立读写的最小物理单位。","explanationEn":""},{"id":"os-ch12-002","chapterId":"ch12","chapterName":"Secondary Storage","stemEn":"Among the following algorithms, which one may cause starvation?","stemCn":"以下算法中，（ ）可能出现“饥饿”现象。","options":{"A":{"textEn":"First-Come, First-Served","textCn":"先来先服务"},"B":{"textEn":"Circular SCAN algorithm","textCn":"循环扫描算法"},"C":{"textEn":"Shortest Seek Time First","textCn":"最短寻找时间优先"},"D":{"textEn":"LOOK algorithm","textCn":"LOOK算法"}},"answerKey":"C","explanationCn":"最短寻找时间优先总是优先处理距离当前磁头最近的请求，若附近请求不断到来，远处请求可能长期得不到服务，从而产生饥饿现象。","explanationEn":""},{"id":"os-ch12-003","chapterId":"ch12","chapterName":"Secondary Storage","stemEn":"Assume the disk head is currently at track 10 and moving in the direction of increasing track numbers. Given the request queue 35, 45, 12, 68, 110, 180, 170, 195, the track access sequence obtained by the SCAN scheduling algorithm is ( ).","stemCn":"假设磁头当前位于第10道，正在向磁道序号增加的方向移动。现有一个磁道访问请求序列为35，45，12，68，110，180，170，195，采用SCAN调度算法得到的磁道访问序列是（ ）。","options":{"A":{"textEn":"12, 35, 45, 68, 110, 170, 180, 195","textCn":"12,35,45,68,110,170,180,195"},"B":{"textEn":"10, 68, 45, 35, 12, 170, 180, 195","textCn":"10,68,45,35,12,170,180,195"},"C":{"textEn":"110, 170, 180, 195, 68, 45, 35, 12","textCn":"110,170,180,195,68,45,35,12"},"D":{"textEn":"110, 170, 180, 195, 12, 35, 45, 68","textCn":"110,170,180,195,12,35,45,68"}},"answerKey":"C","explanationCn":"按题图给出的答案为C。SCAN算法按当前移动方向先服务该方向上的请求，到达一端后再反向服务另一侧请求。","explanationEn":"","needsReview":true},{"id":"os-ch12-004","chapterId":"ch12","chapterName":"Secondary Storage","stemEn":"If the disk head is currently at track 53, and the four pending disk requests are 98, 37, 124, and 65, which scheduling algorithm will make the disk head reach track 65 next? Assume the head is currently moving toward smaller track numbers.","stemCn":"如果磁头当前正在第53号磁道，现有4个磁道访问请求序列为98、37、124、65，当采用（ ）调度算法时，下一次磁头将达到65号磁道。假设此刻磁头方向指向号数小的磁道。","options":{"A":{"textEn":"LOOK algorithm","textCn":"LOOK算法"},"B":{"textEn":"SCAN algorithm","textCn":"扫描算法"},"C":{"textEn":"Shortest Seek Time First","textCn":"最短寻道时间优先"},"D":{"textEn":"First-Come, First-Served","textCn":"先来先服务"}},"answerKey":"C","explanationCn":"当前磁头在53号磁道，请求中距离53最近的是65，距离为12。因此采用最短寻道时间优先算法时，下一次会选择65号磁道。","explanationEn":""},{"id":"os-ch12-005","chapterId":"ch12","chapterName":"Secondary Storage","stemEn":"Among the following algorithms, which one may randomly change the moving direction of the disk head?","stemCn":"在以下算法中，（ ）可能会随时改变磁头的运动方向。","options":{"A":{"textEn":"First-Come, First-Served","textCn":"先来先服务"},"B":{"textEn":"LOOK algorithm","textCn":"Look算法"},"C":{"textEn":"SCAN algorithm","textCn":"扫描算法"},"D":{"textEn":"Circular SCAN algorithm","textCn":"循环扫描算法"}},"answerKey":"A","explanationCn":"先来先服务算法完全按照请求到达顺序访问磁道，不考虑磁头当前方向，因此相邻请求可能分布在不同方向上，磁头方向可能频繁改变。","explanationEn":""},{"id":"os-ch13-001","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"The I/O control of disk devices mainly adopts the ( ) method.","stemCn":"磁盘设备的 I/O 控制主要是采取（ ）方式。","options":{"A":{"textEn":"Programmed polling","textCn":"程序轮询"},"B":{"textEn":"I/O channel","textCn":"I/O 通道"},"C":{"textEn":"Interrupt control","textCn":"中断控制"},"D":{"textEn":"DMA","textCn":"DMA"}},"answerKey":"D","explanationCn":"磁盘属于高速块设备，数据传输量较大。采用 DMA 可以让数据在磁盘设备和内存之间直接传送，减少 CPU 参与，提高 I/O 效率。","explanationEn":""},{"id":"os-ch13-002","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"The DMA method establishes a direct data path between ( ).","stemCn":"DMA 方式是在（ ）之间建立一条直接数据通路。","options":{"A":{"textEn":"I/O device and memory","textCn":"I/O 设备和内存"},"B":{"textEn":"I/O device and CPU","textCn":"I/O 设备和 CPU"},"C":{"textEn":"CPU and main memory","textCn":"CPU 和主存"},"D":{"textEn":"Two I/O devices","textCn":"两个 I/O 设备"}},"answerKey":"A","explanationCn":"DMA 的核心思想是让外设和主存之间直接交换数据，CPU 只负责初始化和结束处理，不逐字节参与传输。","explanationEn":""},{"id":"os-ch13-003","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"Device independence means ( ).","stemCn":"设备的独立性是指（ ）。","options":{"A":{"textEn":"Each device has a unique identifier","textCn":"每一台设备都有一个唯一的编号"},"B":{"textEn":"The system manages each device independently","textCn":"系统对设备的管理是独立的"},"C":{"textEn":"An application program is independent of the physical device actually used","textCn":"应用程序独立于实际使用的物理设备"},"D":{"textEn":"Devices are independent of the computer system","textCn":"设备独立于计算机系统"}},"answerKey":"C","explanationCn":"设备独立性强调用户程序不需要关心具体使用哪台物理设备，只需通过逻辑设备名访问，由操作系统完成映射。","explanationEn":""},{"id":"os-ch13-004","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"When a program uses a system call to open an I/O device, the device identifier usually used is ( ).","stemCn":"程序员利用系统调用打开 I/O 设备时，通常使用的设备标识是（ ）。","options":{"A":{"textEn":"Logical device name","textCn":"逻辑设备名"},"B":{"textEn":"Major device number","textCn":"主设备号"},"C":{"textEn":"Minor device number","textCn":"从设备号"},"D":{"textEn":"Physical device name","textCn":"物理设备名"}},"answerKey":"A","explanationCn":"用户程序通常使用逻辑设备名访问设备，操作系统再把逻辑设备名转换为具体的物理设备，实现设备独立性。","explanationEn":""},{"id":"os-ch13-005","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"Which of the following statements about dedicated devices and shared devices is incorrect?","stemCn":"下面关于独占设备和共享设备的说法中不正确的是（ ）。","options":{"A":{"textEn":"Printers and scanners are dedicated devices","textCn":"打印机、扫描仪等属于独占设备"},"B":{"textEn":"Dedicated devices usually use static allocation","textCn":"对独占设备往往采用静态分配方式"},"C":{"textEn":"Shared devices usually use static allocation","textCn":"对共享设备往往采用静态分配方式"},"D":{"textEn":"A shared device means that after one job has not been removed, another job can use it, but at any moment only one job uses it","textCn":"共享设备是指一个作业尚未撤离，另一个作业即可使用，但每一时刻只有一个作业使用"}},"answerKey":"C","explanationCn":"共享设备一般采用动态分配方式，多个进程可以按一定策略共享使用设备。因此说共享设备往往采用静态分配方式是不正确的。","explanationEn":""},{"id":"os-ch13-006","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"The main purpose of Spooling technology is ( ).","stemCn":"Spooling 技术的主要目的是（ ）。","options":{"A":{"textEn":"Reduce the programming burden of users","textCn":"减轻用户编程负担"},"B":{"textEn":"Increase the speed of information exchange between CPU and devices","textCn":"提高 CPU 和设备交换信息的速度"},"C":{"textEn":"Transform dedicated devices into virtual devices and improve their utilization","textCn":"将独占设备改造成虚拟设备，提高独占设备的利用率"},"D":{"textEn":"Provide primary and auxiliary interfaces","textCn":"提供主、辅接口"}},"answerKey":"C","explanationCn":"Spooling 通过磁盘缓冲区模拟独占设备，使多个作业可以像共享设备一样提交请求，从而提高独占设备的利用率。","explanationEn":""},{"id":"os-ch13-007","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"After a user program issues a disk I/O request, the correct processing flow of the system is ( ).","stemCn":"用户程序发出磁盘 I/O 请求后，系统的正确处理流程是（ ）。","options":{"A":{"textEn":"User program → system call handler → interrupt handler → device driver","textCn":"用户程序 → 系统调用处理程序 → 中断处理程序 → 设备驱动程序"},"B":{"textEn":"User program → device driver → interrupt handler → system call handler","textCn":"用户程序 → 设备驱动程序 → 中断处理程序 → 系统调用处理程序"},"C":{"textEn":"User program → system call handler → device driver → interrupt handler","textCn":"用户程序 → 系统调用处理程序 → 设备驱动程序 → 中断处理程序"},"D":{"textEn":"User program → device driver → system call handler → interrupt handler","textCn":"用户程序 → 设备驱动程序 → 系统调用处理程序 → 中断处理程序"}},"answerKey":"C","explanationCn":"用户程序先通过系统调用进入内核，再由系统调用处理程序转交给设备驱动程序。设备完成 I/O 后，通过中断处理程序通知系统。","explanationEn":""},{"id":"os-ch13-008","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"A virtual device refers to ( ).","stemCn":"虚拟设备是指（ ）。","options":{"A":{"textEn":"Transforming one physical device into multiple corresponding logical devices","textCn":"把一个物理设备变换成多个对应的逻辑设备"},"B":{"textEn":"Allowing users to use physical devices in a standardized way","textCn":"允许用户以标准化方式来使用物理设备"},"C":{"textEn":"Allowing user programs to use system devices without being fully loaded into memory","textCn":"允许用户程序不必全部装入主存便可使用系统中的设备"},"D":{"textEn":"Allowing users to use more devices than the physical devices in the system","textCn":"允许用户使用比系统中具有的物理设备更多的设备"}},"answerKey":"A","explanationCn":"虚拟设备是通过软件技术把一个物理设备抽象成多个逻辑设备，使多个用户或作业看起来可以同时使用该设备。","explanationEn":""},{"id":"os-ch13-009","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"Which of the following does not belong to the device management data structures?","stemCn":"以下（ ）不属于设备管理数据结构。","options":{"A":{"textEn":"COCT","textCn":"COCT"},"B":{"textEn":"DCT","textCn":"DCT"},"C":{"textEn":"PCB","textCn":"PCB"},"D":{"textEn":"CHCT","textCn":"CHCT"}},"answerKey":"C","explanationCn":"PCB 是进程控制块，属于进程管理数据结构。DCT、COCT、CHCT 等才是设备管理中常见的数据结构。","explanationEn":""},{"id":"os-ch13-010","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"A file occupies 10 disk blocks. The file needs to be read block by block into the main-memory buffer and analyzed in the user area. Assume one buffer has the same size as one disk block, reading one disk block into a buffer takes 100 μs, transferring data from the buffer to the user area takes 50 μs, and the CPU takes 50 μs to analyze one block. Under a double-buffer structure, the time required to read and analyze the file is ( ).","stemCn":"某文件占 10 个磁盘块，现要把该文件磁盘块逐个读入主存缓冲区，并送用户区进行分析。假设一个缓冲区与一个磁盘块大小相同，把一个磁盘块读入缓冲区的时间为 100μs，将缓冲区的数据传送到用户区的时间是 50μs，CPU 对一块数据进行分析的时间为 50μs。在双缓冲区结构下，读入并分析该文件的时间是（ ）。","options":{"A":{"textEn":"1000 μs","textCn":"1000μs"},"B":{"textEn":"1500 μs","textCn":"1500μs"},"C":{"textEn":"1100 μs","textCn":"1100μs"},"D":{"textEn":"2000 μs","textCn":"2000μs"}},"answerKey":"C","explanationCn":"双缓冲区可以让读入下一个磁盘块与处理当前磁盘块并行。10 个磁盘块读入缓冲区需要 10×100=1000μs，最后一个磁盘块还需传送和分析 50+50=100μs，所以总时间为 1100μs。","explanationEn":""}],"tf":[{"id":"os-ch04-tf-001","chapterId":"ch04","chapterName":"processes","stemEn":"A state change of one process must cause a state change of another process.","stemCn":"一个进程的状态变化一定会引起另一个进程的状态变化。","answer":"F","explanationCn":"一个进程的状态变化不一定会影响其他进程。例如某进程因等待 I/O 而阻塞时，其他进程的状态不一定发生变化。","explanationEn":""},{"id":"os-ch04-tf-002","chapterId":"ch04","chapterName":"processes","stemEn":"After the I/O operation that a process is waiting for is completed, the process state changes from blocked to ready.","stemCn":"一个进程等待的 I/O 操作完成后，进程状态将会从阻塞变为就绪。","answer":"T","explanationCn":"等待的 I/O 事件完成后，阻塞原因消失，但进程还不能立即运行，需要先进入就绪队列等待调度。","explanationEn":""},{"id":"os-ch04-tf-003","chapterId":"ch04","chapterName":"processes","stemEn":"When the fork system call is executed, the child process copies the address space of the parent process.","stemCn":"执行 fork 系统调用时，子进程会复制父进程的地址空间。","answer":"T","explanationCn":"fork 会创建子进程，子进程在逻辑上获得父进程地址空间的副本。实际系统中可能使用写时复制优化。","explanationEn":""},{"id":"os-ch04-tf-004","chapterId":"ch04","chapterName":"processes","stemEn":"A process that shares data with other processes is a cooperating process.","stemCn":"与其他进程共享数据的进程是协作进程。","answer":"T","explanationCn":"协作进程可以与其他进程相互影响，共享数据是进程协作的一种典型形式。","explanationEn":""},{"id":"os-ch04-tf-005","chapterId":"ch04","chapterName":"processes","stemEn":"Short-term scheduling means selecting a job from the job queue and loading it into memory.","stemCn":"短调度是指从作业队列中选择作业并装入内存。","answer":"F","explanationCn":"从作业队列中选择作业并装入内存属于长程调度；短程调度是从就绪队列中选择进程分配 CPU。","explanationEn":""},{"id":"os-ch05-tf-001","chapterId":"ch05","chapterName":"threads","stemEn":"A thread also has three basic states: ready, blocked, and running.","stemCn":"线程也具有就绪、阻塞和运行三种基本状态。","answer":"T","explanationCn":"线程是处理器调度和执行的基本单位，因此也会随着调度和等待事件在就绪、运行、阻塞等状态之间转换。","explanationEn":""},{"id":"os-ch05-tf-002","chapterId":"ch05","chapterName":"threads","stemEn":"During CPU scheduling, the time slice is allocated to user-level threads.","stemCn":"CPU 调度时，时间片是分给用户线程的。","answer":"F","explanationCn":"用户级线程对内核不可见，内核调度的对象通常是进程或内核级线程，不会直接把时间片分配给用户级线程。","explanationEn":""},{"id":"os-ch05-tf-003","chapterId":"ch05","chapterName":"threads","stemEn":"The disadvantage of the many-to-one model is that true concurrency cannot be achieved.","stemCn":"多对一模型的缺点是不能实现真正的并发。","answer":"T","explanationCn":"多对一模型中多个用户级线程映射到一个内核线程，同一时刻只能有一个线程进入内核执行，因此不能在多处理器上实现真正并行。","explanationEn":""},{"id":"os-ch05-tf-004","chapterId":"ch05","chapterName":"threads","stemEn":"User-level threads are managed in user space, and the kernel can also perceive them.","stemCn":"用户线程是在用户空间管理的，内核也能感知。","answer":"F","explanationCn":"用户级线程由用户态线程库管理，内核通常不能直接感知每个用户级线程，只能看到所属进程或对应的内核实体。","explanationEn":""},{"id":"os-ch05-tf-005","chapterId":"ch05","chapterName":"threads","stemEn":"Multiple threads in the same process share the resources of the process.","stemCn":"同一个进程内的多个线程之间共享进程的资源。","answer":"T","explanationCn":"同一进程内的线程共享进程的地址空间、打开文件等资源，但每个线程有自己的线程控制信息和运行栈等。","explanationEn":""},{"id":"os-ch07-tf-001","chapterId":"ch07","chapterName":"synchronization","stemEn":"A critical section is the area where a critical resource is located.","stemCn":"临界区就是临界资源所在的区域。","answer":"F","explanationCn":"临界区是访问临界资源的代码段，不是临界资源本身所在的物理或存储区域。","explanationEn":""},{"id":"os-ch07-tf-002","chapterId":"ch07","chapterName":"synchronization","stemEn":"A semaphore is an integer variable, and it can be directly incremented by 1 or decremented by 1.","stemCn":"信号量是一个整型变量，可以直接对其进行加 1 和减 1 的操作。","answer":"F","explanationCn":"信号量虽然包含整数值，但只能通过原子性的 P、V 操作访问和修改，不能由进程随意直接加减。","explanationEn":""},{"id":"os-ch07-tf-003","chapterId":"ch07","chapterName":"synchronization","stemEn":"The V operation indicates applying for a resource.","stemCn":"V 操作表示申请一个资源。","answer":"F","explanationCn":"P 操作表示申请资源，V 操作表示释放资源，并可能唤醒等待该资源的进程。","explanationEn":""},{"id":"os-ch07-tf-004","chapterId":"ch07","chapterName":"synchronization","stemEn":"When a process accessing a critical resource is blocked because it requests an I/O operation, it allows other processes to enter its critical section.","stemCn":"一个正在访问临界资源的进程因为申请 I/O 操作而阻塞时，它允许其他进程进入其临界区。","answer":"F","explanationCn":"进程在临界区内即使因 I/O 阻塞，也仍占有临界资源或相关互斥访问权，通常不能允许其他进程直接进入该临界区。","explanationEn":""},{"id":"os-ch07-tf-005","chapterId":"ch07","chapterName":"synchronization","stemEn":"PV operations are atomic operations.","stemCn":"PV 操作是原子操作。","answer":"T","explanationCn":"P、V 操作必须不可分割地执行，否则会破坏信号量的正确性，导致互斥或同步失效。","explanationEn":""},{"id":"os-ch08-tf-001","chapterId":"ch08","chapterName":"deadlocks","stemEn":"The fundamental cause of deadlock is resource competition and improper process advancing order.","stemCn":"产生死锁的根本原因是资源竞争和进程推进顺序非法。","answer":"T","explanationCn":"死锁通常由系统资源竞争以及进程推进顺序不当共同造成，进程互相等待资源而无法继续执行。","explanationEn":""},{"id":"os-ch08-tf-002","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Deadlock can be resolved by resource preemption, and it can also be resolved by terminating processes.","stemCn":"采用资源剥夺可以解除死锁，还可以采用终止进程的方法解除死锁。","answer":"T","explanationCn":"死锁解除常见方法包括剥夺部分资源、终止一个或多个死锁进程，使系统打破循环等待。","explanationEn":""},{"id":"os-ch08-tf-003","chapterId":"ch08","chapterName":"deadlocks","stemEn":"If a cycle appears in a resource-allocation graph, deadlock must occur.","stemCn":"资源分配图中出现环路，则一定会死锁。","answer":"F","explanationCn":"当每类资源只有一个实例时，出现环通常意味着死锁；但若资源类有多个实例，出现环不一定发生死锁。","explanationEn":""},{"id":"os-ch08-tf-004","chapterId":"ch08","chapterName":"deadlocks","stemEn":"Deadlock means that all processes in the system are in the blocked state.","stemCn":"死锁是指系统中的全部进程都处于阻塞状态。","answer":"F","explanationCn":"死锁只要求一组进程互相等待而无法推进，并不一定是系统中所有进程都阻塞。","explanationEn":""},{"id":"os-ch08-tf-005","chapterId":"ch08","chapterName":"deadlocks","stemEn":"To avoid deadlock, processes should request resources one by one in a certain order.","stemCn":"为了避免死锁的发生，各进程应该按序逐个申请资源。","answer":"F","explanationCn":"资源有序分配法要求进程按统一资源编号顺序申请资源，但并不是简单地“逐个申请”就能避免死锁；若顺序不统一仍可能死锁。","explanationEn":""},{"id":"os-ch09-tf-001","chapterId":"ch09","chapterName":"memory management","stemEn":"Static relocation completes address translation when the program is loaded into memory.","stemCn":"静态重定位是程序在装入内存时完成地址变换。","answer":"T","explanationCn":"静态重定位在程序装入时一次性完成逻辑地址到物理地址的转换，装入后地址通常不再改变。","explanationEn":""},{"id":"os-ch09-tf-002","chapterId":"ch09","chapterName":"memory management","stemEn":"In paged memory management, the CPU needs only one memory access to fetch a data item from memory each time.","stemCn":"在分页内存管理中，CPU每次从内存中取一个数据需要1次内存访问。","answer":"F","explanationCn":"普通分页中需要先访问内存中的页表，再访问实际数据，通常需要两次内存访问；若有TLB命中则可减少页表访问开销。","explanationEn":""},{"id":"os-ch09-tf-003","chapterId":"ch09","chapterName":"memory management","stemEn":"In paging, each process has a page table, and the page table resides in memory.","stemCn":"分页时，每个进程拥有一个页表，且页表驻留在内存中。","answer":"T","explanationCn":"分页系统中每个进程通常有自己的页表，用于记录逻辑页到物理页框的映射，页表一般存放在内存中。","explanationEn":""},{"id":"os-ch09-tf-004","chapterId":"ch09","chapterName":"memory management","stemEn":"During static relocation, logical addresses and physical addresses are the same.","stemCn":"静态重定位时，逻辑地址和物理地址是相同的。","answer":"F","explanationCn":"静态重定位是在装入时把逻辑地址转换为物理地址，二者并不必然相同，只是转换工作提前完成。","explanationEn":""},{"id":"os-ch09-tf-005","chapterId":"ch09","chapterName":"memory management","stemEn":"Introducing a TLB is to solve the problem of two memory accesses in paging.","stemCn":"引入TLB是为了解决分页时两次内存访问的问题。","answer":"T","explanationCn":"TLB用于缓存近期使用的页表项，命中时可直接得到页框号，减少普通分页中先查页表再访问数据的额外访存开销。","explanationEn":""},{"id":"os-ch10-tf-001","chapterId":"ch10","chapterName":"virtual memory","stemEn":"Thrashing means that a process frequently performs page replacement, and the time spent on swapping is greater than the time spent on execution.","stemCn":"抖动是指进程频繁进行页面置换。在换页上的时间多于进程执行的时间。","answer":"T","explanationCn":"抖动表现为页面频繁调入调出，系统大量时间花在换页上，进程真正执行的时间反而很少。","explanationEn":""},{"id":"os-ch10-tf-002","chapterId":"ch10","chapterName":"virtual memory","stemEn":"No matter when, to improve CPU utilization, more multiprogramming should be added.","stemCn":"无论何时想要提高CPU的利用率，都应该增加多道程序的道。","answer":"F","explanationCn":"多道程序度过高可能导致内存不足和频繁缺页，甚至产生抖动，从而降低CPU利用率。","explanationEn":""},{"id":"os-ch10-tf-003","chapterId":"ch10","chapterName":"virtual memory","stemEn":"Discreteness is a characteristic of virtual memory.","stemCn":"离散性是虚拟存储的特征。","answer":"T","explanationCn":"虚拟存储通常以页或段为单位离散地装入内存，不要求整个作业连续驻留。","explanationEn":""},{"id":"os-ch10-tf-004","chapterId":"ch10","chapterName":"virtual memory","stemEn":"The maximum capacity of virtual memory is arbitrary.","stemCn":"虚拟存储器的最大容量是任意的。","answer":"F","explanationCn":"虚拟存储器容量受地址结构、外存容量和系统实现等限制，并不是任意无限的。","explanationEn":""},{"id":"os-ch10-tf-005","chapterId":"ch10","chapterName":"virtual memory","stemEn":"When a process runs, if all its working-set pages are in virtual memory, the process can run effectively; otherwise frequent page-in and page-out will occur.","stemCn":"在进程运行时，如果它的工作页面都在虚拟存储器内，能够使该进程有效的运行，否则会出现频繁的页面调入调出现象。","answer":"F","explanationCn":"工作集页面应尽量驻留在主存中，进程才能有效运行；若只在虚拟存储器而不在主存中，仍会产生频繁缺页。","explanationEn":""},{"id":"os-ch11-tf-001","chapterId":"ch11","chapterName":"File System","stemEn":"In a multi-level directory structure, file access is performed through the path name and the user directory name.","stemCn":"在多级目录结构中对文件的访问是通过路径名和用户目录名进行的。","answer":"F","explanationCn":"多级目录结构中文件访问主要通过路径名和文件名进行，而不是通过用户目录名本身完成。","explanationEn":""},{"id":"os-ch11-tf-002","chapterId":"ch11","chapterName":"File System","stemEn":"A file can be divided into several physical blocks of equal size, and the physical block size can be specified arbitrarily.","stemCn":"文件可以被划分成大小相等的若干物理块且物理块大小也可任意指定。","answer":"F","explanationCn":"文件可以划分为物理块，但物理块大小通常由系统或存储设备确定，不能任意指定。","explanationEn":""},{"id":"os-ch11-tf-003","chapterId":"ch11","chapterName":"File System","stemEn":"For a file with three-level indexing, accessing a record usually requires three disk accesses.","stemCn":"对于一个具有三级索引的文件，存取一个记录通常访问三次磁盘。","answer":"F","explanationCn":"三级索引通常需要依次访问多级索引块后再访问数据块，通常不止三次磁盘访问。","explanationEn":""},{"id":"os-ch11-tf-004","chapterId":"ch11","chapterName":"File System","stemEn":"The logical structure of a file refers to the storage organization of the file on disk.","stemCn":"文件的逻辑结构是指文件在磁盘上的存储组织方式。","answer":"F","explanationCn":"文件在磁盘上的存储组织方式属于物理结构；逻辑结构描述的是用户或程序看到的文件组织形式。","explanationEn":""},{"id":"os-ch11-tf-005","chapterId":"ch11","chapterName":"File System","stemEn":"Files using linked allocation can be randomly accessed.","stemCn":"对于采用链接分配的文件，可以进行随机访问。","answer":"F","explanationCn":"链接分配需要沿着指针逐块查找，适合顺序访问，不支持高效随机访问。","explanationEn":""},{"id":"os-ch13-tf-001","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"In a Spooling system, a user program can send output data to the output well at any time, and the Spooling system completes the actual output operation when the output device is idle.","stemCn":"Spooling 系统中的用户程序可以随时将输出数据送到输出井中，待输出设备空闲时再由 Spooling 系统完成数据的输出操作。","answer":"T","explanationCn":"Spooling 通过磁盘上的输出井暂存输出数据，用户进程不必直接占用慢速独占设备，实际输出由系统在设备空闲时完成。","explanationEn":""},{"id":"os-ch13-tf-002","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"Device independence means that the system has the ability to use different devices.","stemCn":"设备独立性就是指系统具有使用不同设备的能力。","answer":"F","explanationCn":"设备独立性强调用户程序与具体物理设备无关，程序使用逻辑设备名，由系统完成到物理设备的映射，而不是简单指系统能使用不同设备。","explanationEn":""},{"id":"os-ch13-tf-003","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"In Spooling technology, a user process can directly and efficiently use a character device.","stemCn":"在 Spooling 技术中，用户进程可以直接高效地使用字符设备。","answer":"F","explanationCn":"Spooling 的特点是用户进程不直接使用独占设备，而是通过输入井、输出井等缓冲区间接提交和取得数据。","explanationEn":""},{"id":"os-ch13-tf-004","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"Introducing buffers can alleviate the speed mismatch between the CPU and peripherals.","stemCn":"引入缓冲能够缓解 CPU 与外设间速度不匹配的矛盾。","answer":"T","explanationCn":"缓冲区可以暂存数据，使高速 CPU 和低速外设之间的数据交换更加平滑，从而减少等待时间。","explanationEn":""},{"id":"os-ch13-tf-005","chapterId":"ch13","chapterName":"I/O Systems","stemEn":"The function of the device driver layer is to hide the differences between device controllers from the kernel I/O subsystem.","stemCn":"设备驱动程序层的作用是为内核 I/O 子系统隐藏设备控制器之间的差异。","answer":"T","explanationCn":"设备驱动程序负责屏蔽具体硬件控制器的差异，向上层提供统一接口，使内核 I/O 子系统不必直接处理不同设备的硬件细节。","explanationEn":""}],"terms":[{"id":"os-ch01-term-001","termEn":"Concurrency","termCn":"并发","explanationCn":"多个任务在同一时间段内交替推进，看起来像同时执行。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-002","termEn":"Parallelism","termCn":"并行","explanationCn":"多个任务在同一时刻真正同时执行，通常需要多个处理器或多核支持。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-003","termEn":"Sharing","termCn":"共享","explanationCn":"多个用户、进程或线程共同使用 CPU、内存、文件和 I/O 设备等系统资源。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-004","termEn":"Virtual","termCn":"虚拟","explanationCn":"操作系统通过抽象让用户或程序看到的资源不一定等同于真实物理资源。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-005","termEn":"asynchronism","termCn":"异步性","explanationCn":"事件发生的时间不可预知，进程执行顺序和速度不是固定的。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-006","termEn":"Single batch processing","termCn":"单道批处理","explanationCn":"内存中一次只装入一个作业，由系统自动成批处理。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-007","termEn":"Multiprogrammed batch system","termCn":"多道批处理系统","explanationCn":"内存中同时装入多个作业，通过作业切换提高 CPU 利用率。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-008","termEn":"Multiprogramming","termCn":"多道程序设计","explanationCn":"多个程序同时驻留内存并交替运行，以提高系统资源利用率。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-009","termEn":"time-sharing system","termCn":"分时系统","explanationCn":"多个用户通过时间片轮流使用 CPU，使每个用户感觉自己独占系统。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-010","termEn":"real-time system","termCn":"实时系统","explanationCn":"系统必须在规定时间内对外部事件作出响应。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-011","termEn":"distributed system","termCn":"分布式系统","explanationCn":"多台计算机通过网络连接并协同完成任务的系统。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-012","termEn":"parallel system","termCn":"并行系统","explanationCn":"具有多个处理器或多个计算单元，能够同时执行多个任务的系统。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-013","termEn":"interrupt","termCn":"中断","explanationCn":"外部事件或硬件设备向 CPU 发出的请求，使 CPU 暂停当前程序转去处理中断服务程序。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-014","termEn":"trap","termCn":"陷阱","explanationCn":"也称软件中断，通常由程序内部事件引起，包括系统调用、缺页故障、访问越界等异常。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-015","termEn":"interrupt vector","termCn":"中断向量","explanationCn":"保存各类中断处理程序入口地址的数据结构。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-016","termEn":"interrupt handler","termCn":"中断处理程序","explanationCn":"用来处理中断事件的内核程序。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-017","termEn":"dual-mode operation","termCn":"双模式操作","explanationCn":"系统区分用户态和内核态，防止用户程序直接执行危险操作。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-018","termEn":"privileged instructions","termCn":"特权指令","explanationCn":"只能在内核态执行的指令，例如 I/O 控制、中断管理、修改页表等。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-019","termEn":"system calls","termCn":"系统调用","explanationCn":"用户程序请求操作系统内核服务的接口。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-020","termEn":"layered operating system","termCn":"分层操作系统","explanationCn":"把操作系统划分为若干层，每层只调用下一层提供的功能。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-021","termEn":"microkernel","termCn":"微内核","explanationCn":"只在内核中保留最基本功能，如进程通信、基本调度和低级地址空间管理。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-022","termEn":"macrokernel","termCn":"宏内核","explanationCn":"也称单体内核，大部分操作系统服务都运行在内核态。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch01-term-023","termEn":"loadable kernel modules","termCn":"可加载内核模块","explanationCn":"可以在系统运行时动态加载或卸载的内核功能模块。","explanationEn":"","chapterId":"ch01","chapterName":"basic structure"},{"id":"os-ch04-term-001","termEn":"Process","termCn":"进程","explanationCn":"程序的一次执行过程，是系统进行资源分配和调度的基本单位。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-002","termEn":"process state","termCn":"进程状态","explanationCn":"表示进程在生命周期中所处的运行阶段。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-003","termEn":"new","termCn":"新建态","explanationCn":"进程正在被创建。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-004","termEn":"ready","termCn":"就绪态","explanationCn":"进程已经具备运行条件，正在等待 CPU。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-005","termEn":"running","termCn":"运行态","explanationCn":"进程正在 CPU 上执行。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-006","termEn":"waiting / blocked","termCn":"等待态/阻塞态","explanationCn":"进程正在等待某个事件完成，例如 I/O 完成。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-007","termEn":"terminated / exit","termCn":"终止态","explanationCn":"进程执行结束或被系统终止。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-008","termEn":"ready suspended","termCn":"就绪挂起态","explanationCn":"进程在外存中，具备运行条件，但暂时不能进入内存运行。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-009","termEn":"blocked suspended","termCn":"阻塞挂起态","explanationCn":"进程在外存中，并且还在等待某个事件。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-010","termEn":"Process Control Block","termCn":"进程控制块","explanationCn":"简称 PCB，用来保存进程状态、寄存器、程序计数器、优先级、资源信息等。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-011","termEn":"priority","termCn":"优先级","explanationCn":"用于表示进程获得 CPU 的优先程度。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-012","termEn":"process schedule queue","termCn":"进程调度队列","explanationCn":"操作系统按不同状态组织进程的队列，例如就绪队列、等待队列。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-013","termEn":"short-term scheduler","termCn":"短程调度","explanationCn":"也叫 CPU 调度，从就绪队列中选择一个进程运行。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-014","termEn":"long-term scheduler","termCn":"长程调度","explanationCn":"也叫作业调度，决定哪些作业进入内存成为进程。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-015","termEn":"medium-term scheduler","termCn":"中程调度","explanationCn":"负责进程的挂起与恢复，调节内存中进程数量。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-016","termEn":"context switch","termCn":"上下文切换","explanationCn":"CPU 从一个进程切换到另一个进程时保存和恢复运行现场的过程。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-017","termEn":"interprocess communication","termCn":"进程间通信","explanationCn":"简称 IPC，指进程之间交换数据和信息的机制。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-018","termEn":"shared memory system","termCn":"共享内存系统","explanationCn":"多个进程通过共享一块内存区域进行通信。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-019","termEn":"message-passing system","termCn":"消息传递系统","explanationCn":"进程通过发送和接收消息进行通信。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-020","termEn":"thread","termCn":"线程","explanationCn":"进程中的一个执行流，是 CPU 调度的基本单位。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-021","termEn":"single thread","termCn":"单线程","explanationCn":"进程中只有一个执行流。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-022","termEn":"multi-thread process","termCn":"多线程进程","explanationCn":"一个进程中包含多个线程，这些线程共享进程资源。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-023","termEn":"kernel-level thread","termCn":"内核级线程","explanationCn":"由操作系统内核直接管理和调度的线程。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-024","termEn":"user-level thread","termCn":"用户级线程","explanationCn":"由用户态线程库管理，内核不知道其具体存在。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-025","termEn":"many-to-one","termCn":"多对一模型","explanationCn":"多个用户线程映射到一个内核线程。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-026","termEn":"one-to-one","termCn":"一对一模型","explanationCn":"一个用户线程对应一个内核线程。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-027","termEn":"many-to-many","termCn":"多对多模型","explanationCn":"多个用户线程映射到多个内核线程。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch04-term-028","termEn":"lightweight threads","termCn":"轻量级线程","explanationCn":"通常指比传统进程开销更小、可由内核支持调度的执行单位。","explanationEn":"","chapterId":"ch04","chapterName":"processes and threads"},{"id":"os-ch06-term-001","termEn":"burst time","termCn":"CPU 执行时间","explanationCn":"进程连续占用 CPU 的一段时间，也可称 CPU burst。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-002","termEn":"nonpreemptive","termCn":"非抢占式","explanationCn":"进程一旦获得 CPU，除非主动放弃或结束，否则不会被强制剥夺 CPU。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-003","termEn":"preemptive","termCn":"抢占式","explanationCn":"操作系统可以强制暂停当前进程，把 CPU 分配给其他进程。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-004","termEn":"dispatcher","termCn":"分派程序","explanationCn":"负责把 CPU 控制权交给调度器选中的进程。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-005","termEn":"scheduling criteria","termCn":"调度准则","explanationCn":"用于评价调度算法好坏的指标，如 CPU 利用率、吞吐量、周转时间、等待时间、响应时间。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-006","termEn":"scheduling algorithm","termCn":"调度算法","explanationCn":"用来决定哪个进程获得 CPU 的具体方法。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-007","termEn":"FCFS","termCn":"先来先服务调度","explanationCn":"按照进程到达顺序依次执行。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-008","termEn":"SJF","termCn":"短作业优先调度","explanationCn":"优先选择预计运行时间最短的进程。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-009","termEn":"Priority scheduling","termCn":"优先级调度","explanationCn":"优先选择优先级最高的进程。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-010","termEn":"Round Robin","termCn":"时间片轮转调度","explanationCn":"每个进程依次获得一个固定长度的时间片。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-011","termEn":"time quantum","termCn":"时间片","explanationCn":"分时系统中分配给每个进程连续运行的最大时间。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-012","termEn":"multilevel queue","termCn":"多级队列调度","explanationCn":"把就绪队列分成多个独立队列，每个队列可以采用不同调度算法。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-013","termEn":"multilevel feedback queue","termCn":"多级反馈队列调度","explanationCn":"进程可以在不同优先级队列之间移动，兼顾交互性和公平性。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-014","termEn":"HRRN","termCn":"最高响应比优先调度","explanationCn":"一种非抢占式调度算法。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch06-term-015","termEn":"High Response Ratio Next","termCn":"最高响应比优先","explanationCn":"响应比通常为（等待时间 + 服务时间）/ 服务时间。","explanationEn":"","chapterId":"ch06","chapterName":"CPU scheduling"},{"id":"os-ch07-term-001","termEn":"Critical section","termCn":"临界区","explanationCn":"访问共享资源的代码区域，同一时刻只允许一个进程或线程进入。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-002","termEn":"entry section","termCn":"进入区","explanationCn":"进程进入临界区之前执行的申请和检查部分。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-003","termEn":"exit section","termCn":"退出区","explanationCn":"进程离开临界区后执行的释放部分。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-004","termEn":"remainder section","termCn":"剩余区","explanationCn":"进程中除进入区、临界区和退出区之外的其他代码。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-005","termEn":"Peterson algorithm","termCn":"Peterson 算法","explanationCn":"一种用于两个进程互斥进入临界区的软件同步算法，通过 turn 和 flag 变量保证互斥、进步和有限等待。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-006","termEn":"Synchronization Hardware","termCn":"同步硬件","explanationCn":"利用硬件原子指令实现进程同步和互斥。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-007","termEn":"Test-and-Set","termCn":"测试并设置指令","explanationCn":"一种原子操作，用于实现自旋锁等互斥机制。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-008","termEn":"Swap","termCn":"交换指令","explanationCn":"一种原子操作，用于交换两个变量的值，也可用于实现互斥。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-009","termEn":"mutex lock","termCn":"互斥锁","explanationCn":"用于保证同一时刻只有一个线程进入临界区。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-010","termEn":"Semaphore","termCn":"信号量","explanationCn":"由一个整数值和两个原子操作 wait、signal 组成，用于进程同步和互斥。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-011","termEn":"Synchronization","termCn":"同步","explanationCn":"多个进程或线程按照一定顺序协调执行。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-012","termEn":"bounded-buffer","termCn":"有界缓冲区问题","explanationCn":"也叫生产者消费者问题，用来说明同步与互斥。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-013","termEn":"reader and writer","termCn":"读者写者问题","explanationCn":"描述多个读进程和写进程共享数据时的同步问题。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch07-term-014","termEn":"dining-philosopher","termCn":"哲学家进餐问题","explanationCn":"经典同步问题，用来说明死锁和资源竞争。","explanationEn":"","chapterId":"ch07","chapterName":"synchronization"},{"id":"os-ch08-term-001","termEn":"deadlock","termCn":"死锁","explanationCn":"多个进程因互相等待对方占有的资源而无法继续执行。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-002","termEn":"mutual exclusion","termCn":"互斥","explanationCn":"某些资源一次只能被一个进程占有。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-003","termEn":"hold and wait","termCn":"占有并等待","explanationCn":"进程已经占有至少一个资源，同时又等待新的资源。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-004","termEn":"no preemption","termCn":"不可抢占","explanationCn":"资源不能被强制剥夺，只能由占有它的进程主动释放。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-005","termEn":"circular wait","termCn":"循环等待","explanationCn":"存在一个进程循环链，每个进程都在等待下一个进程占有的资源。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-006","termEn":"resource-allocation graph","termCn":"资源分配图","explanationCn":"用图形表示进程和资源之间的请求、分配关系。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-007","termEn":"deadlock prevention","termCn":"死锁预防","explanationCn":"通过破坏死锁产生的必要条件之一来防止死锁。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-008","termEn":"deadlock avoidance","termCn":"死锁避免","explanationCn":"在资源分配前进行判断，避免系统进入不安全状态。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-009","termEn":"safe state","termCn":"安全状态","explanationCn":"系统存在某种安全序列，使所有进程都能顺利完成。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-010","termEn":"banker’s algorithm","termCn":"银行家算法","explanationCn":"根据最大需求、已分配资源和可用资源判断分配是否安全。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-011","termEn":"deadlock detection","termCn":"死锁检测","explanationCn":"允许死锁发生，然后通过检测算法判断系统是否已经死锁。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-012","termEn":"recovery scheme","termCn":"死锁恢复方案","explanationCn":"检测到死锁后采取措施恢复系统运行。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-013","termEn":"process termination","termCn":"进程终止","explanationCn":"通过终止一个或多个死锁进程来解除死锁。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch08-term-014","termEn":"resource preemption","termCn":"资源抢占","explanationCn":"通过强制回收某些资源并重新分配来解除死锁。","explanationEn":"","chapterId":"ch08","chapterName":"deadlocks"},{"id":"os-ch09-term-001","termEn":"logical address","termCn":"逻辑地址","explanationCn":"也叫虚拟地址，是程序生成的地址。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-002","termEn":"physical address","termCn":"物理地址","explanationCn":"内存硬件中真实的地址。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-003","termEn":"dynamic loading","termCn":"动态装入","explanationCn":"程序模块在真正需要执行时才装入内存。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-004","termEn":"dynamic linking","termCn":"动态链接","explanationCn":"程序运行时才把库函数或模块链接进来。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-005","termEn":"overlay","termCn":"覆盖技术","explanationCn":"把程序划分为若干段，不同时需要的段可以共用同一块内存区域。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-006","termEn":"swapping","termCn":"交换","explanationCn":"把进程暂时从内存换出到外存，需要时再换入内存。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-007","termEn":"contiguous allocation","termCn":"连续分配","explanationCn":"给一个进程分配一块连续的内存空间。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-008","termEn":"fixed partition allocation","termCn":"固定分区分配","explanationCn":"把内存预先划分为大小固定的若干分区。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-009","termEn":"dynamic storage-allocation","termCn":"动态存储分配","explanationCn":"根据进程需要动态划分内存空间。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-010","termEn":"first fit","termCn":"首次适应算法","explanationCn":"选择第一个足够大的空闲分区进行分配。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-011","termEn":"best fit","termCn":"最佳适应算法","explanationCn":"选择能够满足需求且剩余空间最小的空闲分区。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-012","termEn":"worst fit","termCn":"最坏适应算法","explanationCn":"选择最大的空闲分区进行分配。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-013","termEn":"fragmentation","termCn":"碎片","explanationCn":"内存中不能被有效利用的小块空间，分为内部碎片和外部碎片。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-014","termEn":"paging","termCn":"分页","explanationCn":"把逻辑地址空间划分为页，把物理内存划分为页框。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-015","termEn":"pages","termCn":"页","explanationCn":"逻辑地址空间中的固定大小块。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-016","termEn":"frames","termCn":"页框","explanationCn":"物理内存中的固定大小块，与页大小相同。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-017","termEn":"address translation","termCn":"地址转换","explanationCn":"把逻辑地址转换为物理地址的过程。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-018","termEn":"page table","termCn":"页表","explanationCn":"保存逻辑页号到物理页框号映射关系的数据结构。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-019","termEn":"associative register","termCn":"联想寄存器","explanationCn":"在内存管理中通常指 TLB，用于加快页表查询。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-020","termEn":"TLB","termCn":"快表","explanationCn":"保存近期使用的页表项，以提高地址转换速度。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-021","termEn":"two-level page-table","termCn":"二级页表","explanationCn":"把页表再分页，减少连续存放大页表的内存压力。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-022","termEn":"hashed page table","termCn":"哈希页表","explanationCn":"利用哈希函数根据页号查找页表项，常用于大地址空间。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-023","termEn":"inverted page table","termCn":"倒置页表","explanationCn":"按物理页框建立表项，每个页框对应一个表项。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-024","termEn":"segmentation","termCn":"分段","explanationCn":"把程序按逻辑意义划分为代码段、数据段、堆栈段等。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch09-term-025","termEn":"segmentation with paging","termCn":"段页式管理","explanationCn":"先分段再分页，结合分段的逻辑性和分页的离散分配优点。","explanationEn":"","chapterId":"ch09","chapterName":"memory management"},{"id":"os-ch10-term-001","termEn":"virtual memory","termCn":"虚拟内存","explanationCn":"使程序看到的地址空间可以大于实际物理内存。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-002","termEn":"physical memory","termCn":"物理内存","explanationCn":"计算机实际安装的主存空间。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-003","termEn":"locality of reference","termCn":"局部性原理","explanationCn":"程序在一段时间内倾向于访问相近或最近使用过的地址。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-004","termEn":"demand paging","termCn":"请求分页","explanationCn":"只有当页面被访问且不在内存时才调入页面。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-005","termEn":"demand segmentation","termCn":"请求分段","explanationCn":"只有当段被访问且不在内存时才调入段。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-006","termEn":"fetch paging","termCn":"取页","explanationCn":"指把需要的页面从外存调入内存。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-007","termEn":"valid-invalid bit","termCn":"有效/无效位","explanationCn":"页表项中表示该页是否在内存或是否合法的标志位。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-008","termEn":"page fault","termCn":"缺页中断","explanationCn":"访问的页面不在内存时产生的异常。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-009","termEn":"effective access time","termCn":"有效访问时间","explanationCn":"考虑 TLB 命中率、缺页率等因素后的平均访存时间。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-010","termEn":"page replacement","termCn":"页面置换","explanationCn":"当内存没有空闲页框时，选择某个页面换出。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-011","termEn":"optimal algorithm","termCn":"最优置换算法","explanationCn":"淘汰未来最长时间不会被访问的页面，是理论最优算法。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-012","termEn":"FIFO","termCn":"先进先出页面置换","explanationCn":"淘汰最早进入内存的页面。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-013","termEn":"LRU","termCn":"最近最少使用页面置换","explanationCn":"淘汰最长时间未被访问的页面。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-014","termEn":"Belady","termCn":"Belady 异常","explanationCn":"指在某些算法中增加页框数反而导致缺页次数增加的现象。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-015","termEn":"second-chance / clock","termCn":"第二次机会算法/时钟算法","explanationCn":"FIFO 的改进算法，结合访问位判断是否淘汰页面。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-016","termEn":"allocation of frames","termCn":"页框分配","explanationCn":"决定每个进程可以获得多少个物理页框。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-017","termEn":"global replacement","termCn":"全局置换","explanationCn":"进程发生缺页时可以从所有进程的页框中选择页面换出。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-018","termEn":"local replacement","termCn":"局部置换","explanationCn":"进程只能从自己占有的页框中选择页面换出。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-019","termEn":"fixed allocation","termCn":"固定分配","explanationCn":"每个进程分配固定数量的页框。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-020","termEn":"thrashing","termCn":"抖动","explanationCn":"系统频繁缺页并大量进行页面换入换出，导致 CPU 利用率下降。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-021","termEn":"working set","termCn":"工作集","explanationCn":"某段时间窗口内进程实际访问的页面集合。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch10-term-022","termEn":"working set window","termCn":"工作集窗口","explanationCn":"用于统计工作集的一段固定长度的时间或访问范围。","explanationEn":"","chapterId":"ch10","chapterName":"virtual memory"},{"id":"os-ch11-term-001","termEn":"File control block","termCn":"文件控制块","explanationCn":"简称 FCB，用来保存文件的属性、位置、权限、大小等信息。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-002","termEn":"Sequential file","termCn":"顺序文件","explanationCn":"记录按顺序组织，通常适合顺序访问。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-003","termEn":"indexed file","termCn":"索引文件","explanationCn":"通过索引表查找文件记录。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-004","termEn":"indexed sequential file","termCn":"索引顺序文件","explanationCn":"既保留顺序组织，又通过索引提高查找效率。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-005","termEn":"sequential access","termCn":"顺序访问","explanationCn":"按照文件内容的先后顺序依次访问。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-006","termEn":"direct access","termCn":"直接访问","explanationCn":"也叫随机访问，可以直接访问文件中的指定位置或记录。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-007","termEn":"Contiguous allocation","termCn":"连续分配","explanationCn":"文件在磁盘上占用一组连续的物理块。这里指文件系统中的连续分配，不是内存管理中的连续分配。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-008","termEn":"linked allocation","termCn":"链接分配","explanationCn":"文件的磁盘块可以分散存放，每个块中保存指向下一个块的指针。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-009","termEn":"FAT","termCn":"文件分配表","explanationCn":"File Allocation Table，用表记录文件各磁盘块之间的链接关系。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-010","termEn":"indexed allocation","termCn":"索引分配","explanationCn":"为每个文件建立索引块，索引块中保存文件数据块的地址。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-011","termEn":"file directory","termCn":"文件目录","explanationCn":"用于保存文件名与文件控制信息之间的对应关系。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-012","termEn":"Single-level directory","termCn":"单级目录","explanationCn":"系统中只有一个目录，所有文件都放在同一级。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-013","termEn":"Two-level directory","termCn":"二级目录","explanationCn":"每个用户有自己的用户文件目录，上面还有主文件目录。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-014","termEn":"Tree-structured directory","termCn":"树形目录","explanationCn":"目录可以分层嵌套，形成树状结构。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-015","termEn":"acyclic-graph directory","termCn":"无环图目录","explanationCn":"允许文件或目录共享，但目录结构中不能出现环。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-016","termEn":"Link","termCn":"链接","explanationCn":"多个目录项指向同一个文件或文件对象。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-017","termEn":"symlink","termCn":"符号链接","explanationCn":"也叫软链接，保存目标文件路径的特殊文件。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-018","termEn":"Free-space management","termCn":"空闲空间管理","explanationCn":"操作系统管理磁盘空闲块的方法。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-019","termEn":"bit map","termCn":"位图","explanationCn":"用一串二进制位表示磁盘块是否空闲。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-020","termEn":"linked free list","termCn":"空闲链表","explanationCn":"把所有空闲磁盘块通过指针链接起来。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch11-term-021","termEn":"file access control","termCn":"文件访问控制","explanationCn":"用于规定用户对文件的读、写、执行等权限。","explanationEn":"","chapterId":"ch11","chapterName":"file systems"},{"id":"os-ch13-term-001","termEn":"Disk cache","termCn":"磁盘高速缓存","explanationCn":"把常用磁盘数据暂存在内存中，以减少磁盘 I/O 次数。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-002","termEn":"Controller","termCn":"设备控制器","explanationCn":"连接 CPU、内存和外部设备的硬件部件，负责控制具体设备操作。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-003","termEn":"Programmed I/O","termCn":"程序控制 I/O","explanationCn":"也叫轮询方式，CPU 不断检查设备状态并完成数据传输。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-004","termEn":"Polling","termCn":"轮询","explanationCn":"CPU 主动反复查询设备是否就绪。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-005","termEn":"Interrupt-driven","termCn":"中断驱动 I/O","explanationCn":"设备完成操作后通过中断通知 CPU。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-006","termEn":"DMA","termCn":"直接存储器访问","explanationCn":"设备和内存之间直接传输数据，减少 CPU 参与。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-007","termEn":"SDT","termCn":"系统设备表","explanationCn":"System Device Table，记录系统中所有设备的总体信息。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-008","termEn":"DCT","termCn":"设备控制表","explanationCn":"Device Control Table，记录某一具体设备的状态和控制信息。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-009","termEn":"COCT","termCn":"设备控制器表","explanationCn":"Controller Control Table，记录设备控制器相关信息。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-010","termEn":"CHCT","termCn":"通道控制表","explanationCn":"Channel Control Table，记录通道的状态和控制信息。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-011","termEn":"LUT","termCn":"逻辑设备表","explanationCn":"Logical Unit Table，用于逻辑设备名到物理设备的映射。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"},{"id":"os-ch13-term-012","termEn":"SPOOLing","termCn":"假脱机技术","explanationCn":"把独占设备改造成逻辑上的共享设备，典型例子是打印机假脱机。","explanationEn":"","chapterId":"ch13","chapterName":"I/O systems"}]}]};
